def calcola_costo_turni(prezzi, mw_f1, mw_f2, mw_f3):
    """Costo di fornitura scomposto per turno di produzione industriale.

    Molti clienti industriali lavorano su 3 turni da 8 ore: Notte 22-06,
    Mattina 06-14, Pomeriggio 14-22. Il prezzo spot (e quindi il costo di
    fornitura a prezzo variabile) cambia molto tra notte e giorno: questo
    tab dice all'energy manager quanto costa far girare ciascun turno e
    quale turno e' il piu' caro in EUR/MWh — informazione operativa per
    spostare produzione, manutenzione o fermi sui turni piu' economici.

    Il profilo di carico dell'app e' piatto per fascia (MW costanti in
    F1/F2/F3): il carico orario e' il MW della fascia di ciascuna ora (via
    fascia_oraria). Il costo orario e' prezzo x carico; ogni ora cade in
    esattamente un turno.

    Metodo (tutto deterministico a parita' di input):
    - turno(h): 22,23,0-5 -> "Notte (22-06)"; 6-13 -> "Mattina (06-14)";
      14-21 -> "Pomeriggio (14-22)";
    - per turno: ore, MWh = somma carico, costo = somma(prezzo x carico),
      prezzo medio = costo / MWh (None se MWh = 0), % costo = costo /
      costo totale x 100 (0.0 se costo totale = 0);
    - KPI: turno piu' costoso (max costo), turno piu' caro in EUR/MWh
      (max prezzo medio tra i turni con MWh > 0), quota % del turno di
      punta sul totale;
    - df_mesi: per mese di calendario, costo EUR per turno (somme
      esatte: la somma su turni e mesi = costo totale).

    NaN-safe: serie vuota, MW tutti a zero o non validi -> statistiche
    neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'mwh_totale', 'costo_totale', 'turno_piu_costoso',
    'turno_piu_caro_mwh', 'pct_turno_punta' (None se costo_totale = 0),
    'df_turni' ('Turno', 'Ore', 'MWh', 'Costo (€)', 'Prezzo medio (€/MWh)',
    '% costo'), 'df_mesi' ('Mese', 'Notte (€)', 'Mattina (€)',
    'Pomeriggio (€)').
    """
    turni = ["Notte (22-06)", "Mattina (06-14)", "Pomeriggio (14-22)"]
    cols_t = ["Turno", "Ore", "MWh", "Costo (€)", "Prezzo medio (€/MWh)", "% costo"]
    cols_m = ["Mese", "Notte (€)", "Mattina (€)", "Pomeriggio (€)"]

    def turno_di(h):
        if h >= 22 or h < 6:
            return "Notte (22-06)"
        if h < 14:
            return "Mattina (06-14)"
        return "Pomeriggio (14-22)"

    vuoto = {"ore": 0, "mwh_totale": 0.0, "costo_totale": 0.0,
             "turno_piu_costoso": None, "turno_piu_caro_mwh": None,
             "pct_turno_punta": None,
             "df_turni": pd.DataFrame([{"Turno": t, "Ore": 0, "MWh": 0.0,
                                        "Costo (€)": 0.0,
                                        "Prezzo medio (€/MWh)": None,
                                        "% costo": 0.0} for t in turni]),
             "df_mesi": pd.DataFrame(columns=cols_m)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        mws = [0.0, 0.0, 0.0]
    out = dict(vuoto)
    out["ore"] = len(p)
    try:
        ore_turno = pd.Series([turno_di(ts.hour) for ts in p.index],
                              index=p.index, dtype="string")
        carico = p.index.map(fascia_oraria).map(
            {"F1": mws[0], "F2": mws[1], "F3": mws[2]}).astype(float)
    except Exception:
        return out
    costo_orario = (p.values * carico.values)
    df_h = pd.DataFrame({"turno": ore_turno.values, "mwh": carico.values,
                         "costo": costo_orario})
    g = df_h.groupby("turno", observed=True)
    righe = []
    costi = {}
    for t in turni:
        if t in g.groups:
            gg = g.get_group(t)
            ore_t = int(len(gg))
            mwh_t = float(gg["mwh"].sum())
            costo_t = float(gg["costo"].sum())
        else:
            ore_t, mwh_t, costo_t = 0, 0.0, 0.0
        pm = (costo_t / mwh_t) if mwh_t > 0 else None
        costi[t] = costo_t
        righe.append({"Turno": t, "Ore": ore_t, "MWh": round(mwh_t, 3),
                      "Costo (€)": round(costo_t, 2),
                      "Prezzo medio (€/MWh)": (round(pm, 2) if pm is not None else None),
                      "% costo": 0.0})
    costo_tot = float(df_h["costo"].sum())
    mwh_tot = float(df_h["mwh"].sum())
    for rg in righe:
        rg["% costo"] = round(rg["Costo (€)"] / costo_tot * 100.0, 1) if costo_tot > 0 else 0.0
    # Chiudi l'arrotondamento a 1 decimale: la somma deve fare 100.0
    if costo_tot > 0:
        residuo = round(100.0 - sum(rg["% costo"] for rg in righe), 1)
        if abs(residuo) > 0.0:
            tmax_r = max(turni, key=lambda t: costi[t])
            for rg in righe:
                if rg["Turno"] == tmax_r:
                    rg["% costo"] = round(rg["% costo"] + residuo, 1)
                    break
    out["df_turni"] = pd.DataFrame(righe, columns=cols_t)
    out["mwh_totale"] = round(mwh_tot, 3)
    out["costo_totale"] = round(costo_tot, 2)
    if costo_tot > 0:
        tmax = max(turni, key=lambda t: costi[t])
        out["turno_piu_costoso"] = tmax
        out["pct_turno_punta"] = round(costi[tmax] / costo_tot * 100.0, 1)
        pm_vals = {r["Turno"]: r["Prezzo medio (€/MWh)"] for r in righe
                   if r["Prezzo medio (€/MWh)"] is not None}
        out["turno_piu_caro_mwh"] = max(pm_vals, key=pm_vals.get) if pm_vals else None
    # Dettaglio mensile: costo per turno, mese di calendario
    try:
        df_h["mese"] = pd.PeriodIndex(p.index, freq="M").astype(str)
        dm = (df_h.groupby(["mese", "turno"], observed=True)["costo"]
              .sum().unstack(fill_value=0.0))
        for t in turni:
            if t not in dm.columns:
                dm[t] = 0.0
        dm = dm[turni].reset_index()
        dm.columns = ["Mese", "Notte (€)", "Mattina (€)", "Pomeriggio (€)"]
        for c in ["Notte (€)", "Mattina (€)", "Pomeriggio (€)"]:
            dm[c] = dm[c].round(2)
        out["df_mesi"] = dm.sort_values("Mese").reset_index(drop=True)
    except Exception:
        pass
    return out

def calcola_backtest_ordini_limite(prezzi, mw_f1, mw_f2, mw_f3, soglie):
    """Backtest deterministico di ordini limite di acquisto sul mercato spot.

    Domanda operativa dell'energy analyst: "se automatizzassi l'acquisto con
    un ordine limite a X euro/MWh (algo 'buy-the-dip' per carichi flessibili,
    ricariche, pompaggi, batch), quante ore si riempirebbero, a che prezzo
    medio comprerei davvero e quanto risparmierei rispetto a comprare tutto
    al prezzo medio di periodo?" — l'ordine si riempie in OGNI ora con
    prezzo <= soglia (fill deterministico sullo storico; nessuno slippage
    modellato, i volumi orari del profilo sono piccoli rispetto al mercato).

    Diverso dal tab Finestre di acquisto (tab23: cerca la finestra CONTIGUA
    di N ore piu' economica di ogni giorno — timing, non prezzo) e dal tab
    Top ore di costo (tab39: le ore piu' care GIA' accadute, non una
    strategia eseguibile in avanti).

    Per ogni soglia S:
    - ore riempite = ore con prezzo <= S; quota ore = riempite / ore totali;
    - MWh acquistabili = somma dei MW di fascia nelle ore riempite;
    - prezzo medio di riempimento = media dei prezzi nelle ore riempite
      (il prezzo a cui compreresti davvero con quel limite: sempre < S);
    - risparmio vs media = (prezzo medio periodo - prezzo medio
      riempimento) x MWh riempiti (positivo = risparmi, negativo = paghi
      di piu' — puo' succedere solo se il profilo pesa sulle ore care).

    Sanitizzazione: ore con prezzo NaN scartate, timestamp duplicati ->
    primo tenuto, serie ordinata per tempo; ore in Europe/Zurich per la
    fascia corretta; soglie non numeriche/non finite scartate, duplicate
    rimosse, ordinate in modo crescente. Serie con meno di 24 ore, profilo
    nullo o nessuna soglia valida -> 'ok' False.

    Ritorna dict con 'ok', 'prezzo_medio_periodo', 'mwh_totale',
    'tot_ore', 'df_soglie' ('Soglia (euro/MWh)' / 'Ore riempite' /
    'Quota ore %' / 'MWh acquistabili' / 'Quota MWh %' / 'Prezzo medio
    riempimento (euro/MWh)' / 'Risparmio vs media (euro)'), 'df_mesi'
    ('Mese' + una colonna 'MWh @ <soglia>' per soglia testata), 'df_ore'
    ('Data' / 'Ora' / 'Prezzo (euro/MWh)' / 'Fascia' / 'MW' / 'MWh') con
    tutte le ore del periodo: la UI filtra per la soglia selezionata."""
    COLS_S = ["Soglia (euro/MWh)", "Ore riempite", "Quota ore %",
              "MWh acquistabili", "Quota MWh %",
              "Prezzo medio riempimento (euro/MWh)",
              "Risparmio vs media (euro)"]
    COLS_O = ["Data", "Ora", "Prezzo (euro/MWh)", "Fascia", "MW", "MWh"]

    def _vuoto():
        return {"ok": False, "prezzo_medio_periodo": None, "mwh_totale": 0.0,
                "tot_ore": 0,
                "df_soglie": pd.DataFrame(columns=COLS_S),
                "df_mesi": pd.DataFrame(columns=["Mese"]),
                "df_ore": pd.DataFrame(columns=COLS_O)}

    try:
        p = prezzi.astype(float)
        if hasattr(p.index, "duplicated"):
            p = p[~p.index.duplicated(keep="first")]
        p = p.dropna().sort_index()
    except Exception:
        return _vuoto()
    if len(p) < 24:
        return _vuoto()
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        return _vuoto()
    if sum(mws) <= 0:
        return _vuoto()
    soglie_pulite = []
    try:
        soglie_iter = list(soglie)
    except TypeError:
        return _vuoto()
    for s in soglie_iter:
        try:
            v = float(s)
        except (TypeError, ValueError):
            continue
        if np.isfinite(v) and v not in soglie_pulite:
            soglie_pulite.append(v)
    soglie_pulite = sorted(soglie_pulite)
    if not soglie_pulite:
        return _vuoto()

    idx = p.index.tz_convert("Europe/Zurich") if p.index.tz is not None else p.index
    valori = p.to_numpy(dtype=float)
    fasce = np.array([fascia_oraria(ts) for ts in idx])
    mw_map = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    mw_ore = np.array([mw_map.get(fx, 0.0) for fx in fasce], dtype=float)
    medio = float(np.mean(valori))
    mwh_tot = float(mw_ore.sum())

    righe = []
    maschere = []
    for s in soglie_pulite:
        mask = valori <= s
        maschere.append(mask)
        n_fill = int(mask.sum())
        mwh_fill = float(mw_ore[mask].sum())
        if n_fill > 0:
            medio_fill = float(np.mean(valori[mask]))
            risp = (medio - medio_fill) * mwh_fill
        else:
            medio_fill, risp = None, 0.0
        righe.append({
            "Soglia (euro/MWh)": s,
            "Ore riempite": n_fill,
            "Quota ore %": round(n_fill / len(valori) * 100.0, 2),
            "MWh acquistabili": round(mwh_fill, 1),
            "Quota MWh %": round(mwh_fill / mwh_tot * 100.0, 2) if mwh_tot > 0 else 0.0,
            "Prezzo medio riempimento (euro/MWh)": (round(medio_fill, 2)
                                                   if medio_fill is not None else None),
            "Risparmio vs media (euro)": round(risp, 2),
        })
    df_soglie = pd.DataFrame(righe, columns=COLS_S)

    # MWh riempiti per mese di calendario e per soglia.
    try:
        mesi = pd.PeriodIndex(idx, freq="M").astype(str).to_numpy()
        dfm = pd.DataFrame({"mese": mesi})
        for s, mask in zip(soglie_pulite, maschere):
            dfm[f"@ {s:g}"] = np.where(mask, mw_ore, 0.0)
        g = dfm.groupby("mese", observed=True).sum(numeric_only=True)
        df_mesi = g.reset_index().rename(columns={"mese": "Mese"})
        df_mesi = df_mesi.sort_values("Mese").reset_index(drop=True)
        for c in df_mesi.columns[1:]:
            df_mesi[c] = df_mesi[c].round(1)
    except Exception:
        df_mesi = pd.DataFrame(columns=["Mese"])

    # Dettaglio orario completo: la UI filtra per la soglia selezionata.
    try:
        df_ore = pd.DataFrame({
            "Data": idx.strftime("%d/%m/%Y"),
            "Ora": idx.hour,
            "Prezzo (euro/MWh)": np.round(valori, 2),
            "Fascia": fasce,
            "MW": np.round(mw_ore, 3),
            "MWh": np.round(mw_ore, 3),
        })
    except Exception:
        df_ore = pd.DataFrame(columns=COLS_O)

    return {"ok": True, "prezzo_medio_periodo": round(medio, 2),
            "mwh_totale": round(mwh_tot, 1), "tot_ore": int(len(p)),
            "df_soglie": df_soglie, "df_mesi": df_mesi, "df_ore": df_ore}


def calcola_take_or_pay(prezzi, mw_f1, mw_f2, mw_f3, prezzo_fisso,
                        volume_mode="profilo", tolleranza_pct=10.0,
                        pen_sopra_pct=0.0, pen_sotto_pct=0.0,
                        sweep_prezzi=None):
    """Take-or-pay: contratto di fornitura a prezzo fisso con banda di
    tolleranza sui volumi orari.

    Domanda operativa dell'energy analyst: "se firmo un fisso a P euro/MWh
    con volume orario contrattato V e tolleranza +/-X%, quanto pago DAVVERO
    col mio profilo?" — il contratto copre al prezzo P solo il volume
    dentro la banda [V*(1-X), V*(1+X)]: il consumo OLTRE il cap si regola
    a spot maggiorato di una penale, il volume SOTTO il floor resta comunque
    pagato a P (take-or-pay) con eventuale rivendita a spot scontato.

    Diverso dal tab Fisso vs indicizzato (tab46: fisso PURO senza banda
    volumi, tutto il consumo a P) e dal tab Sbilanciamento (tab55: errore
    di PREVISIONE del carico regolato dal TSO, non un contratto
    commerciale). Qui il driver di costo e' la RIGIDITA' del volume
    contrattato rispetto al profilo reale.

    volume_mode: "profilo" = il volume contrattato segue il profilo
    dichiarato F1/F2/F3 (V_h = consumo di fascia); "piatto" = baseload
    (V_h = consumo medio orario). Con "profilo" e tolleranza 0 il contratto
    copre esattamente il profilo dichiarato a P.

    Per ogni ora h, con C = consumo, V = volume contrattato,
    floor = V*(1-tol), cap = V*(1+tol), S = spot:
    - quota in banda: min(max(C, floor), cap) pagata a P;
    - eccedenza sopra cap: (C - cap) a S * (1 + pen_sopra);
    - take-or-pay sotto floor: floor pagato a P, meno credito di rivendita
      (floor - C) * S * (1 - pen_sotto).

    Sanitizzazione: ore con prezzo NaN scartate, timestamp duplicati ->
    primo tenuto, serie ordinata per tempo; ore in Europe/Zurich per la
    fascia corretta; tolleranza clamp 0-100, penali clamp 0-100, prezzo
    fisso >= 0 e finito. Serie con meno di 24 ore, profilo nullo o prezzo
    fisso non valido -> 'ok' False.

    Ritorna dict con 'ok', 'prezzo_fisso', 'tot_ore', 'mwh_consumati',
    'mwh_contrattati', 'costo_totale', 'prezzo_medio_effettivo',
    'costo_spot', 'delta_vs_spot' (positivo = il contratto costa DI PIU'
    dello spot), 'pct_ore_in_banda' / 'pct_ore_sotto_floor' /
    'pct_ore_sopra_cap', 'mwh_take_or_pay' (pagati a P ma non consumati),
    'mwh_eccedenza', 'df_ore' ('Data' / 'Ora' / 'Fascia' /
    'Prezzo (euro/MWh)' / 'MW consumati' / 'MW contrattati' / 'Floor (MW)' /
    'Cap (MW)' / 'Stato' / 'Costo orario (euro)'), 'df_mesi' ('Mese' /
    'Costo contratto (euro)' / 'Costo spot (euro)' / 'MWh' /
    'Prezzo medio effettivo (euro/MWh)'), 'df_sweep' ('Prezzo fisso
    (euro/MWh)' / 'Prezzo medio effettivo (euro/MWh)' / 'Delta vs spot
    (euro)') per i prezzi in sweep_prezzi (sanitizzati, finiti, >= 0,
    deduplicati, ordinati)."""
    COLS_O = ["Data", "Ora", "Fascia", "Prezzo (euro/MWh)", "MW consumati",
              "MW contrattati", "Floor (MW)", "Cap (MW)", "Stato",
              "Costo orario (euro)"]
    COLS_S = ["Prezzo fisso (euro/MWh)", "Prezzo medio effettivo (euro/MWh)",
              "Delta vs spot (euro)"]

    def _vuoto():
        return {"ok": False, "prezzo_fisso": None, "tot_ore": 0,
                "mwh_consumati": 0.0, "mwh_contrattati": 0.0,
                "costo_totale": 0.0, "prezzo_medio_effettivo": None,
                "costo_spot": 0.0, "delta_vs_spot": 0.0,
                "pct_ore_in_banda": 0.0, "pct_ore_sotto_floor": 0.0,
                "pct_ore_sopra_cap": 0.0, "mwh_take_or_pay": 0.0,
                "mwh_eccedenza": 0.0,
                "df_ore": pd.DataFrame(columns=COLS_O),
                "df_mesi": pd.DataFrame(columns=["Mese"]),
                "df_sweep": pd.DataFrame(columns=COLS_S)}

    try:
        p = prezzi.astype(float)
        if hasattr(p.index, "duplicated"):
            p = p[~p.index.duplicated(keep="first")]
        p = p.dropna().sort_index()
    except Exception:
        return _vuoto()
    if len(p) < 24:
        return _vuoto()
    try:
        mws = [max(0.0, float(x)) for x in (mw_f1, mw_f2, mw_f3)]
    except (TypeError, ValueError):
        return _vuoto()
    if sum(mws) <= 0:
        return _vuoto()
    try:
        P = float(prezzo_fisso)
    except (TypeError, ValueError):
        return _vuoto()
    if not np.isfinite(P) or P < 0:
        return _vuoto()
    try:
        tol = max(0.0, min(100.0, float(tolleranza_pct))) / 100.0
        pen_up = 1.0 + max(0.0, min(100.0, float(pen_sopra_pct))) / 100.0
        pen_down = 1.0 - max(0.0, min(100.0, float(pen_sotto_pct))) / 100.0
    except (TypeError, ValueError):
        return _vuoto()

    idx = p.index.tz_convert("Europe/Zurich") if p.index.tz is not None else p.index
    valori = p.to_numpy(dtype=float)
    fasce = np.array([fascia_oraria(ts) for ts in idx])
    mw_map = {"F1": mws[0], "F2": mws[1], "F3": mws[2]}
    consumo = np.array([mw_map.get(fx, 0.0) for fx in fasce], dtype=float)
    if volume_mode == "piatto":
        vol = np.full_like(consumo, consumo.mean())
    else:
        vol = consumo.copy()
    floor = vol * (1.0 - tol)
    cap = vol * (1.0 + tol)

    in_banda = np.minimum(np.maximum(consumo, floor), cap)
    eccesso = np.maximum(0.0, consumo - cap)
    mancante = np.maximum(0.0, floor - consumo)
    costo_eccesso = eccesso * valori * pen_up
    credito = mancante * valori * pen_down

    def _costo_totale(pf):
        return float(np.sum(in_banda * pf + costo_eccesso - credito))

    costo_tot = _costo_totale(P)
    mwh = float(consumo.sum())
    pme = costo_tot / mwh if mwh > 0 else None
    costo_spot = float(np.sum(consumo * valori))
    delta = costo_tot - costo_spot

    n = len(valori)
    sopra = consumo > cap
    sotto = consumo < floor
    pct_sopra = round(float(sopra.sum()) / n * 100.0, 2)
    pct_sotto = round(float(sotto.sum()) / n * 100.0, 2)
    pct_banda = round(100.0 - pct_sopra - pct_sotto, 2)

    try:
        sweep = []
        if sweep_prezzi is not None:
            for s in list(sweep_prezzi):
                try:
                    v = float(s)
                except (TypeError, ValueError):
                    continue
                if np.isfinite(v) and v >= 0 and v not in sweep:
                    sweep.append(v)
        sweep = sorted(sweep)
    except TypeError:
        sweep = []
    righe_s = [{"Prezzo fisso (euro/MWh)": s,
                "Prezzo medio effettivo (euro/MWh)": round(_costo_totale(s) / mwh, 2) if mwh > 0 else None,
                "Delta vs spot (euro)": round(_costo_totale(s) - costo_spot, 2)}
               for s in sweep]
    df_sweep = pd.DataFrame(righe_s, columns=COLS_S)

    stati = np.where(sopra, "sopra cap", np.where(sotto, "sotto floor (take-or-pay)", "in banda"))
    costo_ora = in_banda * P + costo_eccesso - credito
    try:
        df_ore = pd.DataFrame({
            "Data": idx.strftime("%d/%m/%Y"),
            "Ora": idx.hour,
            "Fascia": fasce,
            "Prezzo (euro/MWh)": np.round(valori, 2),
            "MW consumati": np.round(consumo, 3),
            "MW contrattati": np.round(vol, 3),
            "Floor (MW)": np.round(floor, 3),
            "Cap (MW)": np.round(cap, 3),
            "Stato": stati,
            "Costo orario (euro)": np.round(costo_ora, 2),
        })
    except Exception:
        df_ore = pd.DataFrame(columns=COLS_O)

    try:
        dfm = pd.DataFrame({
            "mese": pd.PeriodIndex(idx, freq="M").astype(str),
            "costo_c": costo_ora,
            "costo_s": consumo * valori,
            "mwh": consumo,
        })
        g = dfm.groupby("mese", observed=True).sum(numeric_only=True)
        df_mesi = g.reset_index().rename(columns={
            "mese": "Mese", "costo_c": "Costo contratto (euro)",
            "costo_s": "Costo spot (euro)", "mwh": "MWh"})
        df_mesi = df_mesi.sort_values("Mese").reset_index(drop=True)
        df_mesi["Costo contratto (euro)"] = df_mesi["Costo contratto (euro)"].round(0)
        df_mesi["Costo spot (euro)"] = df_mesi["Costo spot (euro)"].round(0)
        df_mesi["MWh"] = df_mesi["MWh"].round(1)
        df_mesi["Prezzo medio effettivo (euro/MWh)"] = (
            df_mesi["Costo contratto (euro)"] / df_mesi["MWh"].replace(0, np.nan)).round(2)
    except Exception:
        df_mesi = pd.DataFrame(columns=["Mese"])

    return {"ok": True, "prezzo_fisso": P, "tot_ore": n,
            "mwh_consumati": round(mwh, 1),
            "mwh_contrattati": round(float(vol.sum()), 1),
            "costo_totale": round(costo_tot, 2),
            "prezzo_medio_effettivo": round(pme, 2) if pme is not None else None,
            "costo_spot": round(costo_spot, 2),
            "delta_vs_spot": round(delta, 2),
            "pct_ore_in_banda": pct_banda,
            "pct_ore_sotto_floor": pct_sotto,
            "pct_ore_sopra_cap": pct_sopra,
            "mwh_take_or_pay": round(float(mancante.sum()), 1),
            "mwh_eccedenza": round(float(eccesso.sum()), 1),
            "df_ore": df_ore, "df_mesi": df_mesi, "df_sweep": df_sweep}


def _irr_sizing(netto_annuo, capex, anni, degrado, tol=1e-6):
    """Tasso interno di rendimento: risolve NPV(r) = 0 con ricavi netti in degrado
    geometrico annuo. Ritorna la percentuale arrotondata, None se non converge."""
    if netto_annuo is None or capex is None or netto_annuo <= 0 or capex <= 0 or anni <= 0:
        return None

    def npv_r(r):
        if r <= -1.0:
            return float("inf")
        q = (1.0 - degrado) / (1.0 + r)
        f = float(anni) if abs(1.0 - q) < 1e-12 else q * (1.0 - q ** anni) / (1.0 - q)
        return netto_annuo * f - capex

    lo, hi = -0.999, 10.0
    if npv_r(lo) < 0 or npv_r(hi) > 0:
        return None
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if npv_r(mid) > 0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return round(0.5 * (lo + hi) * 100.0, 1)


def calcola_sizing_batteria(prezzi, eff=0.85, cap_max=20.0, pot_max=10.0,
                            step=2.0, ore_finestra=2.0, cicli_giorno=1,
                            capex_kwh=250.0, capex_kw=150.0, opex_pct=0.02,
                            anni=15, tasso=0.06, degrado_annuo=0.02,
                            budget_max=1_500_000.0, payback_target=8.0):
    """Sizing batteria per arbitraggio: sweep su griglia capacita' (MWh) x potenza (MW).

    Strategia: cicli_giorno cicli/giorno, carica all'ora piu' economica e scarica a quella
    piu' cara di ogni giorno; spread netto = max(0, p_max - p_min / eff), energia per
    ciclo = min(cap, pot * ore_finestra) (la potenza limita quanto riesci a muovere
    nella finestra di prezzo). Spread annualizzato sul periodo disponibile.
    Economia: CAPEX = cap*capex_kwh + pot*capex_kw, OPEX annuo = CAPEX*opex_pct,
    ricavi netti in degrado geometrico, NPV con tasso di sconto, PI = NPV/CAPEX.
    Ottimo = max NPV entro budget_max; target = min CAPEX con payback <= payback_target.
    Ritorna dict con ok, df_grid, matrici per heatmap, ottimo, target_payback."""
    try:
        p = pd.Series(prezzi).astype(float).dropna()
    except Exception:
        return {"ok": False, "errore": "prezzi non validi"}
    if not isinstance(p.index, pd.DatetimeIndex):
        return {"ok": False, "errore": "indice temporale non valido"}
    if len(p) < 24 or not (0 < eff <= 1) or step <= 0 or cap_max <= 0 or pot_max <= 0:
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    if anni <= 0 or not (0 <= degrado_annuo < 1):
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    try:
        giorni = p.index.normalize()
    except Exception:
        return {"ok": False, "errore": "indice temporale non valido"}
    dmin = p.groupby(giorni).min()
    dmax = p.groupby(giorni).max()
    spread = (dmax - dmin / eff).clip(lower=0.0)
    n_giorni = int(len(spread))
    if n_giorni == 0:
        return {"ok": False, "errore": "nessun giorno completo"}
    spread_annuo = float(spread.sum()) * (365.25 / n_giorni)

    caps = np.arange(step, cap_max + step * 0.5, step)
    pots = np.arange(step, pot_max + step * 0.5, step)
    if len(caps) == 0 or len(pots) == 0:
        return {"ok": False, "errore": "parametri non validi o dati insufficienti"}
    energia = np.minimum(caps[:, None], pots[None, :] * ore_finestra) * max(1, int(cicli_giorno))
    ricavo = spread_annuo * energia
    capex = caps[:, None] * 1000.0 * capex_kwh + pots[None, :] * 1000.0 * capex_kw
    opex = capex * opex_pct
    netto = ricavo - opex
    with np.errstate(divide="ignore", invalid="ignore"):
        payback = np.where(netto > 0, capex / netto, np.inf)
    q = (1.0 - degrado_annuo) / (1.0 + tasso)
    fattore = float(anni) if abs(1.0 - q) < 1e-12 else q * (1.0 - q ** anni) / (1.0 - q)
    npv = netto * fattore - capex
    with np.errstate(divide="ignore", invalid="ignore"):
        pi = np.where(capex > 0, npv / capex, 0.0)

    righe = []
    for i, c in enumerate(caps):
        for j, pw in enumerate(pots):
            righe.append({
                "Capacità (MWh)": round(float(c), 2),
                "Potenza (MW)": round(float(pw), 2),
                "Energia ciclo (MWh)": round(float(energia[i, j]), 2),
                "Ricavo annuo (€)": round(float(ricavo[i, j]), 0),
                "CAPEX (€)": round(float(capex[i, j]), 0),
                "OPEX annuo (€)": round(float(opex[i, j]), 0),
                "Payback (anni)": round(float(payback[i, j]), 1) if np.isfinite(payback[i, j]) else None,
                "NPV (€)": round(float(npv[i, j]), 0),
                "PI": round(float(pi[i, j]), 2),
            })
    df = pd.DataFrame(righe)

    def _riga(i, j):
        netto_ij = float(netto[i, j])
        return {"cap_mwh": float(caps[i]), "pot_mw": float(pots[j]),
                "energia_ciclo": float(energia[i, j]),
                "ricavo_annuo": float(ricavo[i, j]), "capex": float(capex[i, j]),
                "opex_annuo": float(opex[i, j]), "netto_annuo": netto_ij,
                "payback": float(payback[i, j]),
                "npv": float(npv[i, j]), "pi": float(pi[i, j]),
                "irr": _irr_sizing(netto_ij, float(capex[i, j]), anni, degrado_annuo)}

    cand = np.ones_like(capex, dtype=bool)
    if budget_max is not None and budget_max > 0:
        cand = capex <= budget_max
    ottimo = None
    if cand.any():
        ii, jj = np.unravel_index(np.argmax(np.where(cand, npv, -np.inf)), npv.shape)
        ottimo = _riga(ii, jj)
        ottimo["budget_vincolante"] = bool(budget_max is not None and budget_max > 0
                                           and ottimo["capex"] >= 0.999 * budget_max)
    target = None
    okp = np.isfinite(payback) & (payback <= payback_target)
    if okp.any():
        ii, jj = np.unravel_index(np.argmin(np.where(okp, capex, np.inf)), capex.shape)
        target = _riga(ii, jj)

    return {"ok": True, "n_giorni": n_giorni, "spread_annuo": round(spread_annuo, 2),
            "fattore_att": round(fattore, 4),
            "df_grid": df, "mat_payback": payback, "mat_npv": npv, "mat_pi": pi,
            "caps": caps.tolist(), "pots": pots.tolist(),
            "ottimo": ottimo, "target_payback": target}


# Metriche giornaliere disponibili per gli alert personalizzati (tab77)
METRICHE_ALERT = {
    "max_orario": "Max orario del giorno (€/MWh)",
    "min_orario": "Min orario del giorno (€/MWh)",
    "media_giorno": "Media giornaliera (€/MWh)",
    "spread_giorno": "Spread giornaliero max-min (€/MWh)",
    "ore_sopra_livello": "Ore sopra il livello critico (n. ore)",
    "ore_sotto_livello": "Ore sotto il livello basso (n. ore)",
    "var_media_7gg": "Variazione % media vs 7 giorni prima (%)",
}
_LABEL2KEY_ALERT = {v: k for k, v in METRICHE_ALERT.items()}
_OPERATORI_ALERT = {
    ">": np.greater,
    ">=": np.greater_equal,
    "<": np.less,
    "<=": np.less_equal,
}


def calcola_alert_personalizzati(prezzi, regole, livello_critico=150.0, livello_basso=20.0, k_critico=2):
    """Motore di alert personalizzati: valuta regole di monitoraggio sui prezzi orari.

    Ogni regola e' un dict {nome, metrica, operatore, soglia} dove metrica e' una
    delle chiavi di METRICHE_ALERT (o la sua label), operatore in > >= < <= e
    soglia un numero finito. Le metriche sono calcolate per giorno di calendario:
    max/min/media/spread orari, n. ore sopra il livello critico o sotto il livello
    basso, variazione % della media vs la media dei 7 giorni precedenti.
    Un giorno e' 'critico' se almeno k_critico regole scattano insieme.
    I NaN (es. var_media_7gg nei primi 7 giorni) non fanno mai scattare una regola.
    Ritorna dict con ok, df_giorni (bool per regola + conteggi), df_regole
    (statistiche per regola), serie metriche giornaliere e conteggi aggregati.
    """
    try:
        p = pd.Series(prezzi).astype(float).dropna()
    except Exception:
        return {"ok": False, "errore": "prezzi non validi"}
    if not isinstance(p.index, pd.DatetimeIndex):
        return {"ok": False, "errore": "indice temporale non valido"}
    if len(p) < 24:
        return {"ok": False, "errore": "servono almeno 24 ore di prezzi"}
    try:
        giorni = p.index.normalize()
    except Exception:
        return {"ok": False, "errore": "indice temporale non valido"}
    g = p.groupby(giorni)
    dmax = g.max()
    dmin = g.min()
    dmean = g.mean()
    spread = dmax - dmin
    ore_sopra = g.apply(lambda s: int((s > float(livello_critico)).sum()))
    ore_sotto = g.apply(lambda s: int((s < float(livello_basso)).sum()))
    media_7gg = dmean.shift(7)
    with np.errstate(divide="ignore", invalid="ignore"):
        var_7gg = np.where(media_7gg.abs() > 1e-9,
                           (dmean - media_7gg) / media_7gg.abs() * 100.0, np.nan)
    var_7gg = pd.Series(var_7gg, index=dmean.index)
    metriche = {
        "max_orario": dmax,
        "min_orario": dmin,
        "media_giorno": dmean,
        "spread_giorno": spread,
        "ore_sopra_livello": ore_sopra,
        "ore_sotto_livello": ore_sotto,
        "var_media_7gg": var_7gg,
    }

    valide, scartate, visti = [], 0, set()
    for r in (regole or []):
        try:
            nome = str(r.get("nome", "")).strip()
            met = str(r.get("metrica", "")).strip()
            op = str(r.get("operatore", "")).strip()
            soglia = float(r.get("soglia"))
        except (TypeError, ValueError, AttributeError):
            scartate += 1
            continue
        if met in _LABEL2KEY_ALERT:
            met = _LABEL2KEY_ALERT[met]
        if (not nome or met not in metriche or op not in _OPERATORI_ALERT
                or not np.isfinite(soglia) or nome in visti):
            scartate += 1
            continue
        visti.add(nome)
        valide.append({"nome": nome, "metrica": met, "operatore": op, "soglia": soglia})
    if not valide:
        return {"ok": False, "errore": "nessuna regola valida"}

    date_idx = dmean.index
    nomi = [rv["nome"] for rv in valide]
    df = pd.DataFrame(index=date_idx)
    serie_metriche = {}
    for rv in valide:
        s = metriche[rv["metrica"]].reindex(date_idx)
        serie_metriche[rv["nome"]] = s
        fill = -np.inf if rv["operatore"] in (">", ">=") else np.inf
        trig = _OPERATORI_ALERT[rv["operatore"]](s.fillna(fill).to_numpy(), rv["soglia"])
        df[rv["nome"]] = pd.Series(np.asarray(trig, dtype=bool), index=date_idx)
    df["n_regole_attive"] = df[nomi].sum(axis=1).astype(int)
    k = max(1, int(k_critico))
    df["giorno_critico"] = df["n_regole_attive"] >= k

    righe = []
    for rv in valide:
        t = df[rv["nome"]]
        n_trig = int(t.sum())
        ultimo = df.index[t].max() if n_trig else None
        estremo = None
        if n_trig:
            sv = serie_metriche[rv["nome"]][t].dropna()
            if len(sv):
                estremo = float(sv.max()) if rv["operatore"] in (">", ">=") else float(sv.min())
        righe.append({
            "Regola": rv["nome"],
            "Metrica": METRICHE_ALERT[rv["metrica"]],
            "Operatore": rv["operatore"],
            "Soglia": rv["soglia"],
            "N. trigger": n_trig,
            "% giorni": round(100.0 * n_trig / len(date_idx), 1),
            "Ultimo trigger": ultimo,
            "Valore estremo": round(estremo, 2) if estremo is not None else None,
        })
    df_regole = pd.DataFrame(righe)

    attive = df[nomi].apply(lambda row: ", ".join([c for c in nomi if row[c]]), axis=1)
    df_out = pd.DataFrame({
        "Data": date_idx,
        "N. regole attive": df["n_regole_attive"].to_numpy(),
        "Giorno critico": np.where(df["giorno_critico"].to_numpy(), "sì", "no"),
        "Regole attive": attive.to_numpy(),
    })
    return {"ok": True, "n_giorni": len(date_idx),
            "n_con_alert": int((df["n_regole_attive"] > 0).sum()),
            "n_critici": int(df["giorno_critico"].sum()),
            "n_scartate": scartate, "k_critico": k,
            "livello_critico": float(livello_critico), "livello_basso": float(livello_basso),
            "df_giorni": df_out, "df_bool": df[nomi], "df_regole": df_regole,
            "serie_metriche": serie_metriche,
            "serie_media": dmean, "serie_max": dmax,
            "regole_valide": valide}


def calcola_autoconsumo_fv(prezzi, mw_f1, mw_f2, mw_f3, potenza_mwp,
                           perdite_pct=14.0, feedin_eur_mwh=60.0,
                           capex_eur_kwp=1100.0):
    """Autoconsumo fotovoltaico behind-the-meter (tab 'Autoconsumo FV').

    Simula un impianto FV sul sito del cliente: la generazione oraria
    (profilo_solare deterministico x potenza x (1 - perdite)) copre per prima
    cosa il carico orario del profilo (MW per fascia, come nel resto dell'app);
    l'eccedenza viene immessa in rete e valorizzata al prezzo di ritiro
    dedicato (feed-in).

    A differenza del tab Price capture (tutta la generazione venduta a spot),
    qui la domanda e': quanto risparmio in bolletta con il FV sul tetto.

    Metodo (tutto deterministico a parita' di input):
    - carico orario = MW della fascia di ciascuna ora (via fascia_oraria);
    - gen oraria = profilo_solare(prezzi, potenza_mwp) x (1 - perdite_pct/100);
    - autoconsumo_h = min(gen_h, carico_h); eccedenza_h = gen_h - autoconsumo_h;
    - costo evitato = somma(autoconsumo_h x prezzo_h): bolletta che non paghi;
    - ricavo eccedenze = somma(eccedenza_h) x feedin;
    - risparmio periodo = costo evitato + ricavo eccedenze;
    - quota autoconsumo = autoconsumo / generazione (None se gen = 0);
    - quota autosufficienza = autoconsumo / carico (None se carico = 0);
    - annualizzazione x 8760/ore: produzione annua, risparmio annuo;
    - payback = CAPEX / risparmio annuo (None se risparmio annuo <= 0);
    - produzione specifica = kWh/kWp/anno;
    - df_mesi: per mese Generazione/Autoconsumo/Eccedenza (MWh), Costo evitato
      (EUR), Ricavo eccedenze (EUR), quote %;
    - sweep dimensionamento: 21 potenze da 0 a pmax = max(2 x picco carico,
      potenza x 1.5, 0.05 MWp); per ciascuna risparmio annuo, payback e quote
      (vettorizzato sul profilo normalizzato a 1 MWp).

    prezzi: Series oraria in EUR/MWh (indice datetime).
    potenza_mwp: taglia impianto in MWp (>= 0). perdite_pct: perdite di sistema
    % (0-90). feedin_eur_mwh: prezzo di ritiro delle eccedenze. capex_eur_kwp:
    costo chiavi in mano per kWp (solo per il payback).

    NaN-safe: serie vuota, MW tutti a zero, parametri non validi ->
    statistiche neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'picco_carico_mw', 'potenza_mwp', 'capex_eur',
    'gen_mwh', 'autoconsumo_mwh', 'eccedenza_mwh', 'carico_mwh',
    'quota_autoconsumo', 'quota_autosufficienza', 'costo_base_eur',
    'costo_evitato_eur', 'ricavo_eccedenze_eur', 'risparmio_periodo_eur',
    'risparmio_annuo_eur', 'payback_anni', 'produzione_specifica_kwh_kwp',
    'df_mesi', 'df_sweep' ('Potenza (MWp)', 'Risparmio annuo (EUR)',
    'Payback (anni)', 'Quota autoconsumo (%)', 'Quota autosufficienza (%)').
    """
    cols_m = ["Mese", "Generazione (MWh)", "Autoconsumo (MWh)", "Eccedenza (MWh)",
              "Costo evitato (EUR)", "Ricavo eccedenze (EUR)",
              "Quota autoconsumo (%)", "Quota autosufficienza (%)"]
    cols_s = ["Potenza (MWp)", "Risparmio annuo (EUR)", "Payback (anni)",
              "Quota autoconsumo (%)", "Quota autosufficienza (%)"]
    vuoto = {"ore": 0, "picco_carico_mw": 0.0, "potenza_mwp": 0.0, "capex_eur": 0.0,
             "gen_mwh": 0.0, "autoconsumo_mwh": 0.0, "eccedenza_mwh": 0.0,
             "carico_mwh": 0.0, "quota_autoconsumo": None,
             "quota_autosufficienza": None, "costo_base_eur": 0.0,
             "costo_evitato_eur": 0.0, "ricavo_eccedenze_eur": 0.0,
             "risparmio_periodo_eur": 0.0, "risparmio_annuo_eur": 0.0,
             "payback_anni": None, "produzione_specifica_kwh_kwp": None,
             "df_mesi": pd.DataFrame(columns=cols_m),
             "df_sweep": pd.DataFrame(columns=cols_s)}
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        pot = max(0.0, float(potenza_mwp))
    except (TypeError, ValueError):
        pot = 0.0
    try:
        perd = float(perdite_pct)
    except (TypeError, ValueError):
        perd = 14.0
    perd = min(90.0, max(0.0, perd))
    try:
        feedin = max(0.0, float(feedin_eur_mwh))
    except (TypeError, ValueError):
        feedin = 0.0
    try:
        capex_kwp = max(0.0, float(capex_eur_kwp))
    except (TypeError, ValueError):
        capex_kwp = 0.0
    out = dict(vuoto)
    out["ore"] = len(p)
    out["potenza_mwp"] = round(pot, 4)
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return out
    try:
        mw_map = {"F1": max(0.0, float(mw_f1)), "F2": max(0.0, float(mw_f2)),
                  "F3": max(0.0, float(mw_f3))}
    except (TypeError, ValueError):
        mw_map = {"F1": 0.0, "F2": 0.0, "F3": 0.0}
    carico = fasce.map(mw_map).to_numpy(dtype=float)
    picco = float(carico.max()) if len(carico) else 0.0
    out["picco_carico_mw"] = round(picco, 3)
    try:
        gen1 = profilo_solare(p, 1.0).to_numpy(dtype=float) * (1.0 - perd / 100.0)
    except Exception:
        return out
    pr = p.to_numpy(dtype=float)
    fattore_annuo = 8760.0 / len(p)
    capex = pot * 1000.0 * capex_kwp
    out["capex_eur"] = round(capex, 2)
    carico_mwh = float(carico.sum())
    out["carico_mwh"] = round(carico_mwh, 2)
    out["costo_base_eur"] = round(float((carico * pr).sum()), 2)
    # --- sweep dimensionamento (vettorizzato su profilo normalizzato) ---
    pmax = max(2.0 * picco, pot * 1.5, 0.05)
    ps = np.linspace(0.0, pmax, 21)
    G = gen1[:, None] * ps[None, :]
    AUTO = np.minimum(G, carico[:, None])
    ECC = G - AUTO
    evitato_v = (AUTO * pr[:, None]).sum(axis=0)
    ricavo_v = ECC.sum(axis=0) * feedin
    risp_annuo_v = (evitato_v + ricavo_v) * fattore_annuo
    gen_v = G.sum(axis=0)
    with np.errstate(divide="ignore", invalid="ignore"):
        q_auto_v = np.where(gen_v > 0, AUTO.sum(axis=0) / gen_v * 100.0, np.nan)
        q_self_v = np.where(carico_mwh > 0, AUTO.sum(axis=0) / carico_mwh * 100.0, np.nan)
        capex_v = ps * 1000.0 * capex_kwp
        pb_v = np.where(risp_annuo_v > 0, capex_v / risp_annuo_v, np.nan)
    righe_s = []
    for i, pv in enumerate(ps):
        righe_s.append({"Potenza (MWp)": round(float(pv), 4),
                        "Risparmio annuo (EUR)": round(float(risp_annuo_v[i]), 2),
                        "Payback (anni)": (round(float(pb_v[i]), 2)
                                            if np.isfinite(pb_v[i]) else None),
                        "Quota autoconsumo (%)": (round(float(q_auto_v[i]), 1)
                                                  if np.isfinite(q_auto_v[i]) else None),
                        "Quota autosufficienza (%)": (round(float(q_self_v[i]), 1)
                                                      if np.isfinite(q_self_v[i]) else None)})
    out["df_sweep"] = pd.DataFrame(righe_s, columns=cols_s)
    # --- punto di lavoro (potenza scelta) ---
    g = gen1 * pot
    auto = np.minimum(g, carico)
    ecc = g - auto
    gen_mwh = float(g.sum())
    auto_mwh = float(auto.sum())
    ecc_mwh = float(ecc.sum())
    out["gen_mwh"] = round(gen_mwh, 2)
    out["autoconsumo_mwh"] = round(auto_mwh, 2)
    out["eccedenza_mwh"] = round(ecc_mwh, 2)
    out["quota_autoconsumo"] = round(100.0 * auto_mwh / gen_mwh, 1) if gen_mwh > 0 else None
    out["quota_autosufficienza"] = (round(100.0 * auto_mwh / carico_mwh, 1)
                                    if carico_mwh > 0 else None)
    evitato = float((auto * pr).sum())
    ricavo = float(ecc_mwh * feedin)
    out["costo_evitato_eur"] = round(evitato, 2)
    out["ricavo_eccedenze_eur"] = round(ricavo, 2)
    risp = evitato + ricavo
    out["risparmio_periodo_eur"] = round(risp, 2)
    risp_annuo = risp * fattore_annuo
    out["risparmio_annuo_eur"] = round(risp_annuo, 2)
    out["payback_anni"] = round(capex / risp_annuo, 2) if risp_annuo > 0 else None
    out["produzione_specifica_kwh_kwp"] = (
        round(gen_mwh * fattore_annuo * 1000.0 / (pot * 1000.0), 0)
        if pot > 0 else None)
    # --- dettaglio mensile ---
    mesi = p.index.to_period("M").astype(str)
    righe = []
    for m in sorted(set(mesi)):
        idx = mesi == m
        gm = float(g[idx].sum())
        am = float(auto[idx].sum())
        em = float(ecc[idx].sum())
        cm = float(carico[idx].sum())
        righe.append({"Mese": m,
                      "Generazione (MWh)": round(gm, 2),
                      "Autoconsumo (MWh)": round(am, 2),
                      "Eccedenza (MWh)": round(em, 2),
                      "Costo evitato (EUR)": round(float((auto[idx] * pr[idx]).sum()), 2),
                      "Ricavo eccedenze (EUR)": round(em * feedin, 2),
                      "Quota autoconsumo (%)": round(100.0 * am / gm, 1) if gm > 0 else None,
                      "Quota autosufficienza (%)": round(100.0 * am / cm, 1) if cm > 0 else None})
    out["df_mesi"] = pd.DataFrame(righe, columns=cols_m)
    return out


def calcola_nuovo_carico(prezzi, profilo_24, potenza_mw, mw_f1, mw_f2, mw_f3,
                         tariffa_picco_eur_kw_anno=0.0, mod_mensile=None):
    """Costo marginale di un nuovo carico (tab 'Nuovo carico').

    Valuta quanto costa aggiungere un nuovo consumo (es. flotta EV, pompe di
    calore, datacenter) con un profilo giornaliero dato, valorizzato ai prezzi
    spot orari del periodo selezionato.

    Metodo (tutto deterministico a parita' di input):
    - profilo_24: 24 fattori 0..1 (frazione della potenza nominale per ora);
      valori fuori range vengono clampati; lunghezza diversa da 24 -> neutrali.
    - mod_mensile: 12 moltiplicatori mensili (default 1.0) per carichi
      stagionali (es. pompe di calore); valori negativi -> 0; lunghezza
      diversa da 12 -> neutrali.
    - carico_nuovo_h = potenza_mw x profilo_24[ora] x mod_mensile[mese];
    - costo_h = carico_nuovo_h x prezzo_h;
    - prezzo medio = somma(costo) / somma(energia) (None se energia = 0);
    - confronto con carico esistente: stesso calcolo sul profilo per fascia
      (come nel resto dell'app) -> delta €/MWh e % (shape del nuovo carico
      migliore o peggiore della media del carico esistente);
    - picco: picco esistente dal carico per fascia; picco totale coincidente
      = max(carico_esistente_h + carico_nuovo_h); incremento = totale -
      esistente (>= 0); un carico notturno puo' alzare il picco meno della sua
      potenza nominale se il picco esistente e' diurno;
    - costo potenza = incremento_picco_MW x 1000 x tariffa €/kW/anno;
    - annualizzazione x 8760/ore: energia e costi annui stimati;
    - df_mesi: per mese Energia (MWh), Costo (EUR), Prezzo medio (€/MWh),
      Picco nuovo (MW);
    - df_ore: 24 righe con Ora, Frazione profilo, Energia (MWh), Prezzo medio
      ora (€/MWh) ponderato sull'energia del nuovo carico in quell'ora.

    NaN-safe: serie vuota, potenza 0, profilo tutto a zero, parametri non
    validi -> statistiche neutrali con DataFrame dalle colonne giuste.

    Ritorna dict con 'ore', 'potenza_mw', 'energia_mwh', 'energia_annua_mwh',
    'costo_periodo_eur', 'costo_annuo_eur', 'prezzo_medio_eur_mwh',
    'prezzo_medio_base_eur_mwh', 'delta_eur_mwh', 'delta_pct',
    'picco_nuovo_mw', 'picco_esistente_mw', 'picco_totale_mw',
    'incremento_picco_mw', 'costo_potenza_annuo_eur',
    'costo_totale_annuo_eur', 'quota_costo_f1_pct', 'df_mesi', 'df_ore'.
    """
    cols_m = ["Mese", "Energia (MWh)", "Costo (EUR)", "Prezzo medio (€/MWh)",
              "Picco nuovo (MW)"]
    cols_h = ["Ora", "Frazione profilo", "Energia (MWh)",
              "Prezzo medio ora (€/MWh)"]
    vuoto = {"ore": 0, "potenza_mw": 0.0, "energia_mwh": 0.0,
             "energia_annua_mwh": 0.0, "costo_periodo_eur": 0.0,
             "costo_annuo_eur": 0.0, "prezzo_medio_eur_mwh": None,
             "prezzo_medio_base_eur_mwh": None, "delta_eur_mwh": None,
             "delta_pct": None, "picco_nuovo_mw": 0.0,
             "picco_esistente_mw": 0.0, "picco_totale_mw": 0.0,
             "incremento_picco_mw": 0.0, "costo_potenza_annuo_eur": 0.0,
             "costo_totale_annuo_eur": 0.0, "quota_costo_f1_pct": None,
             "df_mesi": pd.DataFrame(columns=cols_m),
             "df_ore": pd.DataFrame(columns=cols_h)}
    try:
        prof = np.asarray(profilo_24, dtype=float).ravel()
    except (TypeError, ValueError):
        return dict(vuoto)
    if prof.shape[0] != 24 or np.isnan(prof).any():
        return dict(vuoto)
    prof = np.clip(prof, 0.0, 1.0)
    if mod_mensile is None:
        mod = np.ones(12)
    else:
        try:
            mod = np.asarray(mod_mensile, dtype=float).ravel()
        except (TypeError, ValueError):
            return dict(vuoto)
        if mod.shape[0] != 12 or np.isnan(mod).any():
            return dict(vuoto)
        mod = np.clip(mod, 0.0, None)
    try:
        p = prezzi.astype(float).dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0:
        return dict(vuoto)
    try:
        pot = max(0.0, float(potenza_mw))
    except (TypeError, ValueError):
        pot = 0.0
    try:
        tar = max(0.0, float(tariffa_picco_eur_kw_anno))
    except (TypeError, ValueError):
        tar = 0.0
    out = dict(vuoto)
    out["ore"] = len(p)
    out["potenza_mw"] = round(pot, 4)
    try:
        fasce = p.index.map(fascia_oraria)
    except Exception:
        return out
    try:
        mw_map = {"F1": max(0.0, float(mw_f1)), "F2": max(0.0, float(mw_f2)),
                  "F3": max(0.0, float(mw_f3))}
    except (TypeError, ValueError):
        mw_map = {"F1": 0.0, "F2": 0.0, "F3": 0.0}
    carico_e = fasce.map(mw_map).to_numpy(dtype=float)
    pr = p.to_numpy(dtype=float)
    ore_idx = p.index.hour.to_numpy()
    mesi_idx = p.index.month.to_numpy()
    nuovo = pot * prof[ore_idx] * mod[mesi_idx - 1]
    costo = nuovo * pr
    fattore_annuo = 8760.0 / len(p)
    energia = float(nuovo.sum())
    costo_tot = float(costo.sum())
    out["energia_mwh"] = round(energia, 2)
    out["energia_annua_mwh"] = round(energia * fattore_annuo, 2)
    out["costo_periodo_eur"] = round(costo_tot, 2)
    costo_annuo = costo_tot * fattore_annuo
    out["costo_annuo_eur"] = round(costo_annuo, 2)
    out["prezzo_medio_eur_mwh"] = (round(costo_tot / energia, 2)
                                   if energia > 0 else None)
    energia_e = float(carico_e.sum())
    costo_e = float((carico_e * pr).sum())
    pm_base = costo_e / energia_e if energia_e > 0 else None
    out["prezzo_medio_base_eur_mwh"] = round(pm_base, 2) if pm_base is not None else None
    if out["prezzo_medio_eur_mwh"] is not None and pm_base is not None and pm_base != 0:
        out["delta_eur_mwh"] = round(out["prezzo_medio_eur_mwh"] - pm_base, 2)
        out["delta_pct"] = round(100.0 * (out["prezzo_medio_eur_mwh"] - pm_base) / pm_base, 1)
    picco_e = float(carico_e.max()) if len(carico_e) else 0.0
    picco_n = float(nuovo.max()) if len(nuovo) else 0.0
    picco_t = float((carico_e + nuovo).max()) if len(nuovo) else 0.0
    incr = max(0.0, picco_t - picco_e)
    out["picco_esistente_mw"] = round(picco_e, 3)
    out["picco_nuovo_mw"] = round(picco_n, 3)
    out["picco_totale_mw"] = round(picco_t, 3)
    out["incremento_picco_mw"] = round(incr, 3)
    costo_pot = incr * 1000.0 * tar
    out["costo_potenza_annuo_eur"] = round(costo_pot, 2)
    out["costo_totale_annuo_eur"] = round(costo_annuo + costo_pot, 2)
    costo_f1 = float(costo[fasce == "F1"].sum())
    out["quota_costo_f1_pct"] = (round(100.0 * costo_f1 / costo_tot, 1)
                                 if costo_tot > 0 else None)
    # --- dettaglio mensile ---
    mesi = p.index.to_period("M").astype(str)
    righe = []
    for m in sorted(set(mesi)):
        idx = mesi == m
        em = float(nuovo[idx].sum())
        cm = float(costo[idx].sum())
        righe.append({"Mese": m,
                      "Energia (MWh)": round(em, 2),
                      "Costo (EUR)": round(cm, 2),
                      "Prezzo medio (€/MWh)": round(cm / em, 2) if em > 0 else None,
                      "Picco nuovo (MW)": round(float(nuovo[idx].max()), 3)})
    out["df_mesi"] = pd.DataFrame(righe, columns=cols_m)
    # --- dettaglio orario (profilo 24h) ---
    righe_h = []
    for h in range(24):
        idx = ore_idx == h
        eh = float(nuovo[idx].sum())
        ch = float(costo[idx].sum())
        righe_h.append({"Ora": h,
                        "Frazione profilo": round(float(prof[h]), 3),
                        "Energia (MWh)": round(eh, 2),
                        "Prezzo medio ora (€/MWh)": round(ch / eh, 2) if eh > 0 else None})
    out["df_ore"] = pd.DataFrame(righe_h, columns=cols_h)
    return out


def calcola_opzione_asiatica(forward, strike, anni, vol_pct, tasso_pct, tipo="call",
                            n_fixing=12, n_sim=20000, seed=7):
    """Prezzatura di un'opzione ASIATICA (payoff sulla MEDIA dei prezzi) sul forward dell'energia.

    Le opzioni energy si regolano quasi sempre sulla media (settlement mensile
    = media dei giornalieri): un'opzione asiatica replica questo payoff e costa
    meno di una vanilla europea sullo stesso sottostante.

    Metodo: geometrica asiatica con formula chiusa di Kemna-Vorst (esatta);
    aritmetica asiatica via Monte Carlo con VARIABILE DI CONTROLLO sulla
    geometrica (stesso browniano, prezzo esatto noto -> errore std ridotto).
    Il forward e' trattato come martingala (drift zero, modello Black-76).
    n_fixing=1 -> la media coincide con il fixing unico: il prezzo asiatico
    e' identico alla vanilla europea (errore MC = 0, sconto = 0).
    NaN-safe: input non validi (F/K<=0, T<0, vol<0, tasso<0, NaN, stringhe)
    -> dict neutro con nan e senza eccezioni. n_fixing<1 -> 1; n_sim<100 -> 100.
    Ritorna dict con: call_arith/put_arith (MC, €/MWh), call_geom/put_geom
    (Kemna-Vorst), err_std_call/err_std_put, vanilla_call/vanilla_put
    (da calcola_black76), sconto_call_pct/sconto_put_pct (vs vanilla),
    n_fixing, n_sim. Ipotesi: prezzo lognormale, vol/tassi costanti, fixing
    equispaziati da T/n a T.
    """
    neutro = {"call_arith": float("nan"), "put_arith": float("nan"),
              "call_geom": float("nan"), "put_geom": float("nan"),
              "err_std_call": float("nan"), "err_std_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "sconto_call_pct": float("nan"), "sconto_put_pct": float("nan"),
              "n_fixing": None, "n_sim": None}
    try:
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    try:
        n = max(1, int(n_fixing))
    except (TypeError, ValueError):
        return neutro
    try:
        nsim = int(n_sim)
    except (TypeError, ValueError):
        nsim = 20000
    nsim = max(100, nsim)
    df = float(np.exp(-r * T))
    vanilla = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vc = float(vanilla["call"]); vp = float(vanilla["put"])
    if n == 1:
        # Un solo fixing: la media coincide col prezzo finale -> vanilla esatta.
        return {"call_arith": vc, "put_arith": vp,
                "call_geom": vc, "put_geom": vp,
                "err_std_call": 0.0, "err_std_put": 0.0,
                "vanilla_call": vc, "vanilla_put": vp,
                "sconto_call_pct": 0.0, "sconto_put_pct": 0.0,
                "n_fixing": 1, "n_sim": nsim}
    if T == 0.0 or sig == 0.0:
        ic, ip = max(F - K, 0.0), max(K - F, 0.0)
        return {"call_arith": float(ic * df), "put_arith": float(ip * df),
                "call_geom": float(ic * df), "put_geom": float(ip * df),
                "err_std_call": 0.0, "err_std_put": 0.0,
                "vanilla_call": float(vanilla["call"]),
                "vanilla_put": float(vanilla["put"]),
                "sconto_call_pct": 0.0, "sconto_put_pct": 0.0,
                "n_fixing": n, "n_sim": nsim}
    # --- Kemna-Vorst: media GEOMETRICA (formula chiusa) ---
    t_i = T * np.arange(1, n + 1) / n
    tbar = float(t_i.mean())
    var_g = float(sig ** 2 * ((n + 1) * (2 * n + 1)) / (6.0 * n ** 2) * T)
    sig_a = float(np.sqrt(var_g / T))
    f_a = F * float(np.exp(-0.5 * sig ** 2 * tbar + 0.5 * var_g))
    sqt_a = sig_a * float(np.sqrt(T))
    d1g = (float(np.log(f_a / K)) + 0.5 * var_g) / sqt_a
    d2g = d1g - sqt_a
    cg = df * (f_a * float(norm.cdf(d1g)) - K * float(norm.cdf(d2g)))
    pg = df * (K * float(norm.cdf(-d2g)) - f_a * float(norm.cdf(-d1g)))
    # --- Monte Carlo: media ARITMETICA con controllo sulla geometrica ---
    rng = np.random.default_rng(int(seed))
    dt = T / n
    incr = rng.normal(0.0, 1.0, size=(nsim, n)) * float(np.sqrt(dt))
    w_t = np.cumsum(incr, axis=1)
    drift = -0.5 * sig ** 2 * t_i
    spot_t = F * np.exp(drift + sig * w_t)
    media_a = spot_t.mean(axis=1)
    media_g = np.exp(np.log(spot_t).mean(axis=1))
    pay_a_c = np.maximum(media_a - K, 0.0)
    pay_a_p = np.maximum(K - media_a, 0.0)
    pay_g_c = np.maximum(media_g - K, 0.0)
    pay_g_p = np.maximum(K - media_g, 0.0)
    adj_c = pay_a_c - pay_g_c
    adj_p = pay_a_p - pay_g_p
    ca = float(cg + df * adj_c.mean())
    pa = float(pg + df * adj_p.mean())
    err_c = float(df * adj_c.std(ddof=1) / np.sqrt(nsim))
    err_p = float(df * adj_p.std(ddof=1) / np.sqrt(nsim))
    vc = float(vanilla["call"]); vp = float(vanilla["put"])
    sc = float(100.0 * (vc - ca) / vc) if vc and np.isfinite(vc) and vc > 0 else 0.0
    sp = float(100.0 * (vp - pa) / vp) if vp and np.isfinite(vp) and vp > 0 else 0.0
    return {"call_arith": ca, "put_arith": pa,
            "call_geom": float(cg), "put_geom": float(pg),
            "err_std_call": err_c, "err_std_put": err_p,
            "vanilla_call": vc, "vanilla_put": vp,
            "sconto_call_pct": sc, "sconto_put_pct": sp,
            "n_fixing": n, "n_sim": nsim}


def calcola_strategia_opzionaria(tipo, forward, anni, vol_pct, tasso_pct,
                                 k_call_pct=10.0, k_put_pct=10.0, n_punti=400):
    """Payoff a scadenza di strategie opzionarie COMBINATE sul forward dell'energia.

    Cinque strutture standard, tutte europee con premi Black-76 (vedi
    calcola_black76) e strike espressi come offset % dal forward F:
      straddle           : long call ATM + long put ATM  (scommessa sulla volatilita')
      strangle           : long call Kc=F*(1+c%) + long put Kp=F*(1-p%) (volatilita', piu' economica)
      butterfly          : long call Kp + short 2x call F + long call Kc (scommessa su prezzo stabile)
      collar_consumatore : long call Kc + short put Kp (protezione dal rialzo per chi compra energia)
      collar_produttore  : long put Kp + short call Kc (protezione dal ribasso per chi vende energia)
    Il collar e' la copertura classica del procurement energy: la vendita
    dell'opzione opposta finanzia (in tutto o in parte) l'acquisto della
    protezione -> premio netto spesso vicino a zero ("zero-cost collar").

    P&L a scadenza per MWh: somma dei payoff delle gambe (segno + per long,
    - per short, moltiplicatore per la butterfly) MENO il premio netto pagato
    (negativo = credito incassato). Payoff valutato su una griglia di prezzi
    a scadenza che include sempre F e tutti gli strike; i breakeven sono i
    punti dove il P&L totale cambia segno (interpolazione lineare).
    NaN-safe: tipo sconosciuto o input non validi (F<=0, T<0, vol<0, tasso<0,
    offset<0, Kp<=0, NaN, stringhe) -> dict con valido=False e nan, nessuna
    eccezione. Ipotesi: opzioni europee, vol/tassi costanti, payoff valutato
    solo a scadenza (niente mark-to-market intermedio, niente early exercise).
    Ritorna dict con: valido, tipo, legs (lista dict con tipo/lato/strike/
    moltiplicatore/premio/premio_segno/delta/delta_segno), premio_netto_mwh
    (+ = costo, - = credito), delta_netto (per MWh), spot_x, payoff_tot,
    payoff_legs (coppie etichetta/lista), breakeven (lista), max_profit,
    max_loss (sulla griglia), forward."""
    neutro = {"valido": False, "tipo": None, "legs": [],
              "premio_netto_mwh": float("nan"), "delta_netto": float("nan"),
              "spot_x": None, "payoff_tot": None, "payoff_legs": [],
              "breakeven": [], "max_profit": float("nan"),
              "max_loss": float("nan"), "forward": float("nan")}
    TIPI = ("straddle", "strangle", "butterfly", "collar_consumatore",
            "collar_produttore")
    try:
        F = float(forward); T = float(anni)
        sig = float(vol_pct); r = float(tasso_pct)
        kc_off = float(k_call_pct); kp_off = float(k_put_pct)
        n = int(n_punti)
    except (TypeError, ValueError):
        return neutro
    if tipo not in TIPI:
        return neutro
    if not all(np.isfinite(v) for v in (F, T, sig, r, kc_off, kp_off)):
        return neutro
    if F <= 0 or T < 0 or sig < 0 or r < 0 or kc_off < 0 or kp_off < 0:
        return neutro
    n = max(50, min(2000, n))

    Kc = float(F * (1.0 + kc_off / 100.0))
    Kp = float(F * (1.0 - kp_off / 100.0))
    if not np.isfinite(Kc) or not np.isfinite(Kp) or Kp <= 0:
        return neutro

    if tipo == "straddle":
        spec = [("call", "long", F, 1), ("put", "long", F, 1)]
    elif tipo == "strangle":
        spec = [("call", "long", Kc, 1), ("put", "long", Kp, 1)]
    elif tipo == "butterfly":
        spec = [("call", "long", Kp, 1), ("call", "short", F, 2), ("call", "long", Kc, 1)]
    elif tipo == "collar_consumatore":
        spec = [("call", "long", Kc, 1), ("put", "short", Kp, 1)]
    else:  # collar_produttore
        spec = [("put", "long", Kp, 1), ("call", "short", Kc, 1)]

    legs = []
    for tleg, lato, K, mult in spec:
        pr = calcola_black76(F, K, anni, vol_pct, tasso_pct)
        prem = float(pr[tleg])
        delta = float(pr["delta_call"] if tleg == "call" else pr["delta_put"])
        if not (np.isfinite(prem) and np.isfinite(delta)):
            return neutro
        segno = 1.0 if lato == "long" else -1.0
        legs.append({"tipo": tleg, "lato": lato, "strike": float(K),
                     "moltiplicatore": int(mult), "premio": prem,
                     "premio_segno": float(segno * prem * mult),
                     "delta": delta,
                     "delta_segno": float(segno * delta * mult)})

    premio_netto = float(sum(l["premio_segno"] for l in legs))
    delta_netto = float(sum(l["delta_segno"] for l in legs))
    strikes = sorted({l["strike"] for l in legs})
    lo = max(0.01, min(strikes) * 0.3)
    hi = max(strikes) * 1.8
    x = np.linspace(lo, hi, n)
    x = np.array(sorted(set(np.concatenate([x, np.array(strikes + [F])]))))

    payoff_legs = []
    for l in legs:
        segno = 1.0 if l["lato"] == "long" else -1.0
        if l["tipo"] == "call":
            pay = np.maximum(x - l["strike"], 0.0)
        else:
            pay = np.maximum(l["strike"] - x, 0.0)
        payoff_legs.append((f"{l['lato']} {l['tipo']} K={l['strike']:.1f}",
                            segno * float(l["moltiplicatore"]) * pay))
    y = sum(p[1] for p in payoff_legs) - premio_netto

    be = []
    for i in range(len(x) - 1):
        if y[i] == 0.0:
            be.append(float(x[i]))
        elif y[i] * y[i + 1] < 0:
            frac = float(y[i] / (y[i] - y[i + 1]))
            be.append(float(x[i] + frac * (x[i + 1] - x[i])))
    be_u = []
    for b in be:
        if not be_u or abs(b - be_u[-1]) > 1e-6:
            be_u.append(b)
    if len(be_u) > 6:
        be_u = []  # payoff degenere (piatto a zero ovunque): nessun BE significativo

    return {"valido": True, "tipo": tipo, "legs": legs,
            "premio_netto_mwh": premio_netto, "delta_netto": delta_netto,
            "spot_x": [float(v) for v in x],
            "payoff_tot": [float(v) for v in y],
            "payoff_legs": [(lab, [float(v) for v in arr]) for lab, arr in payoff_legs],
            "breakeven": be_u, "max_profit": float(np.max(y)),
            "max_loss": float(np.min(y)), "forward": float(F)}


def _prezzo_berm_tree(F, K, T, sig, r, tipo, n_esercizi, n_steps):
    """Motore binomiale CRR sul FORWARD (martingala risk-neutral: p=(1-d)/(u-d)).

    Ritorna (premio_bermudiana, premio_europeo): l'europea usa lo stesso albero
    senza esercizio anticipato (solo a scadenza). Date di esercizio: k*T/n_esercizi
    (k=1..n_esercizi), mappate sullo step piu' vicino.
    Convenzione di liquidazione: CASH all'esercizio — esercitando alla data t si
    incassa subito l'intrinseco max(F_t-K,0) / max(K-F_t,0) (non scontato), come
    nei contratti fisici energy (paghi K, ritiri la commodity). Con questa
    convenzione la put ha in genere un early exercise premium > 0; la call ha
    premio extra solo se deep ITM con tassi alti (valore temporale del cash).
    Assume input gia' validati: F>0, K>0, T>0, sig>0, r>=0, n_esercizi>=1, n_steps>=10."""
    dt = T / n_steps
    u = float(np.exp(sig * np.sqrt(dt)))
    d = 1.0 / u
    p = (1.0 - d) / (u - d)
    df_step = float(np.exp(-r * dt))
    ex_steps = sorted({min(n_steps, max(0, int(round(k * n_steps / n_esercizi))))
                       for k in range(1, n_esercizi + 1)})
    ex_steps[-1] = n_steps  # l'ultima data coincide sempre con la scadenza
    ex_set = set(ex_steps)
    is_call = (tipo == "call")
    # payoff a scadenza
    Vb = np.empty(n_steps + 1)
    Ve = np.empty(n_steps + 1)
    for j in range(n_steps + 1):
        s = F * (u ** j) * (d ** (n_steps - j))
        pay = max(s - K, 0.0) if is_call else max(K - s, 0.0)
        Vb[j] = pay
        Ve[j] = pay
    # induzione all'indietro
    for i in range(n_steps - 1, -1, -1):
        for j in range(i + 1):
            cont_b = df_step * (p * Vb[j + 1] + (1.0 - p) * Vb[j])
            cont_e = df_step * (p * Ve[j + 1] + (1.0 - p) * Ve[j])
            Ve[j] = cont_e
            if i in ex_set:
                s = F * (u ** j) * (d ** (i - j))
                intr = max(s - K, 0.0) if is_call else max(K - s, 0.0)
                Vb[j] = cont_b if cont_b >= intr else intr
            else:
                Vb[j] = cont_b
    return float(Vb[0]), float(Ve[0])


def calcola_bermudiana(tipo, forward, strike, anni, vol_pct, tasso_pct,
                       n_esercizi=4, n_steps=400):
    """Premio di un'opzione BERMUDIANA sul forward dell'energia (albero binomiale CRR).

    La Bermudiana si puo' esercitare solo in date discrete (es. mensili o
    trimestrali): e' il modello naturale per opzioni su periodi di consegna
    energetici e per contratti storage/swing semplificati. Pricing con albero
    binomiale CRR sul forward (martingala risk-neutral, p=(1-d)/(u-d)),
    esercizio anticipato solo agli step corrispondenti alle date k*T/n_esercizi.
    Ritorna anche il premio EUROPEO sullo stesso albero: la differenza e'
    il valore dell'esercizio anticipato (early exercise premium).
    Note: l'esercizio e' cash-settled (intrinseco incassato subito alla data di
    esercizio). La put ha in genere un early exercise premium > 0; la call ha
    premio extra solo se deep ITM con tassi alti. Casi limite: T=0 -> intrinseco;
    vol=0 -> bermudiana = intrinseco (esercizio immediato), europea scontata.
    NaN-safe: input non validi -> dict neutro con nan e senza eccezioni.
    Ritorna dict con: premio, premio_europeo, premio_early (€/MWh),
    premio_early_pct (%), delta (bump centrale), intrinseco, valido,
    n_esercizi, n_steps, date_esercizio (anni)."""
    neutro = {"premio": float("nan"), "premio_europeo": float("nan"),
              "premio_early": float("nan"), "premio_early_pct": float("nan"),
              "delta": float("nan"), "intrinseco": float("nan"),
              "valido": False, "n_esercizi": 0, "n_steps": 0,
              "date_esercizio": []}
    try:
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        ne = int(round(float(n_esercizi))); ns = int(round(float(n_steps)))
        tp = str(tipo).strip().lower()
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0 or ne < 1:
        return neutro
    ns = min(max(ns, 10), 2000)
    out = dict(neutro)
    out.update({"valido": True, "n_esercizi": ne, "n_steps": ns,
                "date_esercizio": [round(k * T / ne, 6) for k in range(1, ne + 1)]})
    is_call = (tp == "call")
    intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    out["intrinseco"] = float(intr)
    df = float(np.exp(-r * T))
    if T == 0.0:
        out.update({"premio": float(intr), "premio_europeo": float(intr),
                    "premio_early": 0.0, "premio_early_pct": 0.0,
                    "delta": float(1.0 if (is_call and F > K) else (-1.0 if (not is_call and F < K) else 0.0))})
        return out
    if sig == 0.0:
        # senza vol: esercizio immediato se in-the-money (cash settlement)
        out.update({"premio": float(intr), "premio_europeo": float(intr * df),
                    "premio_early": float(intr * (1.0 - df)),
                    "delta": float(1.0 if (is_call and F > K) else (-1.0 if (not is_call and F < K) else 0.0))})
        out["premio_early_pct"] = float(100.0 * out["premio_early"] / out["premio"]) \
            if out["premio"] > 0 else 0.0
        return out
    pb, pe = _prezzo_berm_tree(F, K, T, sig, r, tp, ne, ns)
    early = max(pb - pe, 0.0)  # tolleranza numerica: mai negativo
    h = 0.01
    pb_up, _ = _prezzo_berm_tree(F * (1.0 + h), K, T, sig, r, tp, ne, ns)
    pb_dn, _ = _prezzo_berm_tree(F * (1.0 - h), K, T, sig, r, tp, ne, ns)
    delta = (pb_up - pb_dn) / (2.0 * F * h)
    out.update({"premio": float(pb), "premio_europeo": float(pe),
                "premio_early": float(early), "delta": float(delta)})
    out["premio_early_pct"] = float(100.0 * early / pb) if pb > 0 else 0.0
    return out


def _ko_rr_barriera(tipo, direzione, F, K, H, T, sig, r):
    """Termine knock-out di Reiner-Rubinstein (1991) in forma Black-76.

    Sostituzione S=F (forward), b=0 (costo di carry nullo): il forward e'
    una martingala risk-neutral, quindi le formule RR diventano il pricing
    Black-76 con barriera a monitoraggio continuo. Componenti A/B/C/D
    standard con rebate=0; la tabella dei casi segue Reiner-Rubinstein/Haug.
    Casi degeneri: put down con H>K e call up con H<K valgono esattamente 0
    (la barriera scatterebbe prima che l'opzione possa mai andare ITM)."""
    phi = 1.0 if tipo == "call" else -1.0
    eta = 1.0 if direzione == "down" else -1.0
    b = 0.0
    mu = (b - 0.5 * sig * sig) / (sig * sig)
    sT = sig * np.sqrt(T)
    df = np.exp(-r * T)
    x1 = np.log(F / K) / sT + (1 + mu) * sT
    x2 = np.log(F / H) / sT + (1 + mu) * sT
    y1 = np.log(H * H / (F * K)) / sT + (1 + mu) * sT
    y2 = np.log(H / F) / sT + (1 + mu) * sT
    sterm = F * np.exp((b - r) * T)
    n = norm.cdf
    A = phi * sterm * n(phi * x1) - phi * K * df * n(phi * x1 - phi * sT)
    B = phi * sterm * n(phi * x2) - phi * K * df * n(phi * x2 - phi * sT)
    C = (phi * sterm * (H / F) ** (2 * (mu + 1)) * n(eta * y1)
         - phi * K * df * (H / F) ** (2 * mu) * n(eta * y1 - eta * sT))
    D = (phi * sterm * (H / F) ** (2 * (mu + 1)) * n(eta * y2)
         - phi * K * df * (H / F) ** (2 * mu) * n(eta * y2 - eta * sT))
    if direzione == "down":  # H < F
        if tipo == "call":
            return A - C if K >= H else B - D
        return A - B + C - D if K >= H else 0.0
    # up: H > F
    if tipo == "call":
        return A - B + C - D if K <= H else 0.0
    return A - C if K <= H else B - D


def _prob_knock_barriera(direzione, F, H, T, sig):
    """Probabilita' risk-neutral di first-passage alla barriera (formula chiusa).

    Il log-forward ha drift risk-neutral nu=-sig^2/2 (martingala). Formula di
    riflessione: P(hit)=N((-|d|+/-nu*T)/(sig*sqrt(T)))+exp(2*nu*d/sig^2)*
    N((-|d|-/+nu*T)/(sig*sqrt(T))) con d=ln(H/F) con segno."""
    if sig <= 0 or T <= 0:
        if direzione == "down":
            return 1.0 if F <= H else 0.0
        return 1.0 if F >= H else 0.0
    sT = sig * np.sqrt(T)
    nu = -0.5 * sig * sig
    d = float(np.log(H / F))
    n = norm.cdf
    if direzione == "down":  # d < 0
        return float(n((d - nu * T) / sT)
                     + np.exp(2 * nu * d / (sig * sig)) * n((d + nu * T) / sT))
    return float(n((-d + nu * T) / sT)
                 + np.exp(2 * nu * d / (sig * sig)) * n((-d - nu * T) / sT))


def calcola_barriera(tipo, struttura, direzione, barriera, forward, strike,
                     anni, vol_pct, tasso_pct):
    """Premio di un'opzione con BARRIERA sul forward dell'energia (Reiner-Rubinstein).

    Knock-out: l'opzione si spegne se il forward tocca la barriera H prima di
    T; knock-in: si accende solo al tocco. Pricing analitico a monitoraggio
    continuo in forma Black-76 (forward come martingala risk-neutral, b=0);
    knock-in = vanilla - knock-out per parita' in/out. Ritorna anche la
    probabilita' risk-neutral di knock (first-passage) e il delta via bump.
    Casi limite: T=0 o vol=0 -> knock deterministico (intrinseco scontato se
    non knockato); barriera dal lato sbagliato del forward -> knock immediato
    (KO=0, KI=vanilla). Casi degeneri: put down con H>K e call up con H<K
    valgono 0. NaN-safe: input non validi -> dict neutro con nan.
    Ritorna dict con: premio_ko, premio_ki, premio_vanilla, sconto_ko_pct,
    prob_knock, delta (della struttura scelta), intrinseco, valido, regime
    ('regolare'/'reverse'), lato_barriera_ok."""
    neutro = {"premio_ko": float("nan"), "premio_ki": float("nan"),
              "premio_vanilla": float("nan"), "sconto_ko_pct": float("nan"),
              "prob_knock": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "valido": False,
              "regime": "", "lato_barriera_ok": False}
    try:
        tp = str(tipo).strip().lower()
        st_ = str(struttura).strip().lower()
        dr = str(direzione).strip().lower()
        H = float(barriera); F = float(forward); K = float(strike)
        T = float(anni); sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (H, F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put") or st_ not in ("knock-out", "knock-in") \
            or dr not in ("down", "up"):
        return neutro
    if H <= 0 or F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    is_call = (tp == "call")
    if is_call:
        regolare = (dr == "down" and H <= K) or (dr == "up" and H >= K)
    else:
        regolare = (dr == "down" and H >= K) or (dr == "up" and H <= K)
    out = dict(neutro)
    out.update({"valido": True, "regime": "regolare" if regolare else "reverse"})
    intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    out["intrinseco"] = float(intr)
    van = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vanilla = float(van["call"] if is_call else van["put"])
    out["premio_vanilla"] = vanilla
    lato_ok = (dr == "down" and H < F) or (dr == "up" and H > F)
    out["lato_barriera_ok"] = bool(lato_ok)
    if not lato_ok:
        # barriera dal lato sbagliato: knock immediato
        out.update({"premio_ko": 0.0, "premio_ki": vanilla, "prob_knock": 1.0,
                    "sconto_ko_pct": 100.0 if vanilla > 0 else 0.0, "delta": 0.0})
        return out
    if T == 0.0 or sig == 0.0:
        knocked = (F <= H) if dr == "down" else (F >= H)
        df = float(np.exp(-r * T))
        ko = 0.0 if knocked else intr * df
        ki = intr * df if knocked else 0.0
        out.update({"premio_ko": float(ko), "premio_ki": float(ki),
                    "prob_knock": 1.0 if knocked else 0.0, "delta": 0.0})
        out["sconto_ko_pct"] = float(100.0 * (1.0 - ko / vanilla)) if vanilla > 0 else 0.0
        return out
    ko = _ko_rr_barriera(tp, dr, F, K, H, T, sig, r)
    ko = float(min(max(ko, 0.0), vanilla))  # tolleranza numerica
    ki = float(max(vanilla - ko, 0.0))
    out["premio_ko"] = ko
    out["premio_ki"] = ki
    out["sconto_ko_pct"] = float(100.0 * (1.0 - ko / vanilla)) if vanilla > 0 else 0.0
    out["prob_knock"] = float(min(max(_prob_knock_barriera(dr, F, H, T, sig), 0.0), 1.0))

    def _premio_f(fx):
        if not ((dr == "down" and H < fx) or (dr == "up" and H > fx)):
            kk = 0.0
        else:
            vv0 = calcola_black76(fx, K, T, sig * 100.0, r * 100.0)
            vv0 = float(vv0["call"] if is_call else vv0["put"])
            kk = min(max(_ko_rr_barriera(tp, dr, fx, K, H, T, sig, r), 0.0), vv0)
        vv = calcola_black76(fx, K, T, sig * 100.0, r * 100.0)
        vv = float(vv["call"] if is_call else vv["put"])
        return kk if st_ == "knock-out" else max(vv - kk, 0.0)

    h = 0.01
    out["delta"] = float((_premio_f(F * (1 + h)) - _premio_f(F * (1 - h))) / (2 * F * h))
    return out


def calcola_lookback(tipo, strike_type, forward, strike, anni, vol_pct, tasso_pct,
                     n_fixing=30, n_paths=20000, seed=42):
    """Premio di un'opzione LOOKBACK sul forward dell'energia (Monte Carlo Black-76).

    Strike FISSO: la call paga max(max_fix - K, 0), la put paga max(K - min_fix, 0).
    Strike FLOTTANTE: la call paga max(S_T - min_fix, 0), la put paga
    max(max_fix - S_T, 0) — lo strike e' il minimo/massimo realizzato.
    Pricing Monte Carlo con seed fisso (deterministico, coerente con i grafici
    seedati della dashboard) e variabili antitetiche; dinamica risk-neutral
    driftless sul forward, sconto al tasso risk-free. Le date di fixing sono
    t = T*i/n per i = 1..n (esclude t = 0): con n_fixing = 1 lo strike fisso
    coincide ESATTAMENTE con la vanilla Black-76 e lo strike flottante vale 0
    (ancora di coerenza usata nei test).
    Casi limite: T = 0 o vol = 0 -> deterministico (intrinseco scontato per lo
    strike fisso, 0 per lo strike flottante). NaN-safe: input non validi ->
    dict neutro con valido = False, nessuna eccezione.
    Ritorna dict con: premio, premio_vanilla (strike fisso; nan se flottante),
    extra_vs_vanilla, prob_esercizio, delta (via bump sul forward, stesso seed),
    intrinseco, valido."""


    neutro = {"premio": float("nan"), "premio_vanilla": float("nan"),
              "extra_vs_vanilla": float("nan"), "prob_esercizio": float("nan"),
              "delta": float("nan"), "intrinseco": float("nan"),
              "valido": False}
    try:
        tp = str(tipo).strip().lower()
        st_ = str(strike_type).strip().lower()
        F = float(forward); K = float(strike); T = float(anni)
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        nfx = int(n_fixing); npt = int(n_paths); sd = int(seed)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if tp not in ("call", "put") or st_ not in ("fisso", "flottante"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    if nfx < 1 or npt < 100:
        return neutro
    is_call = (tp == "call")
    fisso = (st_ == "fisso")
    df = float(np.exp(-r * T))
    van = calcola_black76(F, K, T, sig * 100.0, r * 100.0)
    vanilla = float(van["call"] if is_call else van["put"])
    out = dict(neutro)
    out.update({"valido": True, "premio_vanilla": vanilla})
    if fisso:
        intr = max(F - K, 0.0) if is_call else max(K - F, 0.0)
    else:
        intr = 0.0
    out["intrinseco"] = float(intr)

    def _prezzo(ff):
        if T == 0.0 or sig == 0.0:
            if fisso:
                pay = max(ff - K, 0.0) if is_call else max(K - ff, 0.0)
            else:
                pay = 0.0
            return float(pay * df), (1.0 if pay > 0 else 0.0)
        rng = np.random.default_rng(sd)
        nh = npt // 2
        zh = rng.standard_normal((nh, nfx))
        z = np.vstack([zh, -zh])  # antitetiche: (2*nh, nfx)
        dt = T / nfx
        drift = -0.5 * sig * sig * dt
        vola = sig * float(np.sqrt(dt))
        s = np.exp(np.log(ff) + np.cumsum(drift + vola * z, axis=1))
        s_min = s.min(axis=1)
        s_max = s.max(axis=1)
        s_t = s[:, -1]
        if fisso:
            pay = np.maximum(s_max - K, 0.0) if is_call else np.maximum(K - s_min, 0.0)
        else:
            pay = np.maximum(s_t - s_min, 0.0) if is_call else np.maximum(s_max - s_t, 0.0)
        return float(df * pay.mean()), float((pay > 0).mean())

    p0, pr0 = _prezzo(F)
    out["premio"] = p0
    out["prob_esercizio"] = pr0
    out["extra_vs_vanilla"] = float(p0 - vanilla) if fisso else float("nan")
    h = 0.01
    p_up, _ = _prezzo(F * (1 + h))
    p_dn, _ = _prezzo(F * (1 - h))
    out["delta"] = float((p_up - p_dn) / (2 * F * h))
    return out


def calcola_composta(comp_tipo, sott_tipo, forward, k_composto, k_sottostante,
                     mesi_composto, mesi_sottostante, vol_pct, tasso_pct,
                     n_paths=20000, seed=42):
    """Premio di un'opzione COMPOSTA (opzione su opzione) sul forward energetico.

    La composta scade a t1 e paga max(+- (V(F(t1), K2, T2-t1) - K1), 0), dove
    V e' il valore Black-76 dell'opzione SOTTOSTANTE (call o put) di strike K2
    e scadenza T2 >= t1. Nell'energia serve a comprare oggi il DIRITTO di
    decidere in futuro se attivare una copertura: es. call su call = a t1
    decidi se pagare K1 per ottenere una call con scadenza T2 (estensione
    dell'hedge condizionata al prezzo di mercato a t1).
    Pricing Monte Carlo con seed fisso e antitetiche: simulato F(t1) con
    dinamica driftless Black-76, l'opzione sottostante e' prezzata in forma
    chiusa vettoriale su ogni path, payoff scontato al tasso risk-free.
    Ancore esatte: K1 = 0 -> la call composta coincide con la vanilla
    sottostante; t1 = 0 -> max(+-(C0 - K1), 0); vol = 0 -> deterministico;
    parita' composta put-call: put su call = K1*df - call su call.
    F_star = prezzo forward critico a t1 (esercizio ottimale sopra/sotto),
    cercato con brentq; nan se inesistente. NaN-safe: input non validi ->
    dict neutro con valido = False.
    Ritorna dict con: premio, premio_sottostante (vanilla a T2), prob_esercizio,
    delta (via bump sul forward, stesso seed), f_star, intrinseco, valido."""
    from scipy.stats import norm as _norm
    from scipy.optimize import brentq as _brentq

    neutro = {"premio": float("nan"), "premio_sottostante": float("nan"),
              "prob_esercizio": float("nan"), "delta": float("nan"),
              "f_star": float("nan"), "intrinseco": float("nan"),
              "valido": False}
    try:
        ct = str(comp_tipo).strip().lower()
        st_ = str(sott_tipo).strip().lower()
        F = float(forward); K1 = float(k_composto); K2 = float(k_sottostante)
        t1 = float(mesi_composto) / 12.0; T2 = float(mesi_sottostante) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        npt = int(n_paths); sd = int(seed)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K1, K2, t1, T2, sig, r)):
        return neutro
    if ct not in ("call", "put") or st_ not in ("call", "put"):
        return neutro
    if F <= 0 or K1 < 0 or K2 <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0 or npt < 100:
        return neutro
    is_call = (ct == "call")
    sott_call = (st_ == "call")
    df1 = float(np.exp(-r * t1))
    Trem = T2 - t1

    def _b76(Fv, Kv, Tv, cp):
        # Black-76 vettoriale su forward Fv; cp True=call, False=put
        Fv = np.asarray(Fv, dtype=float)
        if Tv <= 0.0 or sig <= 0.0:
            intr = np.maximum(Fv - Kv, 0.0) if cp else np.maximum(Kv - Fv, 0.0)
            return np.exp(-r * Tv) * intr
        sqt = sig * np.sqrt(Tv)
        d1 = (np.log(Fv / Kv) + 0.5 * sig * sig * Tv) / sqt
        d2 = d1 - sqt
        dff = np.exp(-r * Tv)
        if cp:
            return dff * (Fv * _norm.cdf(d1) - Kv * _norm.cdf(d2))
        return dff * (Kv * _norm.cdf(-d2) - Fv * _norm.cdf(-d1))

    def _prezzo(ff, seed_loc):
        V0 = float(_b76(ff, K2, T2, sott_call))
        if t1 == 0.0 or sig == 0.0:
            # deterministico: F(t1) = F
            V1 = float(_b76(ff, K2, Trem, sott_call))
            pay = max(V1 - K1, 0.0) if is_call else max(K1 - V1, 0.0)
            return float(pay * df1), (1.0 if pay > 0 else 0.0), V0
        rng = np.random.default_rng(seed_loc)
        nh = npt // 2
        zh = rng.standard_normal(nh)
        z = np.concatenate([zh, -zh])  # antitetiche
        F1 = ff * np.exp(-0.5 * sig * sig * t1 + sig * np.sqrt(t1) * z)
        V1 = _b76(F1, K2, Trem, sott_call)
        pay = np.maximum(V1 - K1, 0.0) if is_call else np.maximum(K1 - V1, 0.0)
        return float(df1 * pay.mean()), float((pay > 0).mean()), V0

    p0, pr0, V0 = _prezzo(F, sd)
    out = dict(neutro)
    out.update({"valido": True, "premio": p0, "prob_esercizio": pr0,
                "premio_sottostante": V0,
                "intrinseco": float(max(V0 - K1, 0.0) if is_call else max(K1 - V0, 0.0))})
    h = 0.01
    p_up, _, _ = _prezzo(F * (1 + h), sd)
    p_dn, _, _ = _prezzo(F * (1 - h), sd)
    out["delta"] = float((p_up - p_dn) / (2 * F * h))

    # F_star: prezzo forward critico a t1 (esercizio ottimale)
    if t1 > 0.0 and Trem >= 0.0:
        def _V1(x):
            return float(_b76(x, K2, Trem, sott_call)) - K1
        try:
            if is_call and sott_call and K1 == 0.0:
                out["f_star"] = 0.0
            else:
                hi = F * np.exp(10 * sig * np.sqrt(max(t1, 1e-9)) + 5)
                out["f_star"] = float(_brentq(_V1, 1e-8, hi, maxiter=200))
        except Exception:
            out["f_star"] = float("nan")
    return out


def calcola_digitale(payoff, tipo, forward, strike, mesi, vol_pct, tasso_pct):
    """Premio di un'opzione DIGITALE (binaria) sul forward energetico, Black-76 forma chiusa.

    La digitale paga un importo FISSO se a scadenza la condizione e' vera,
    zero altrimenti — niente gamma progressiva: o tutto o niente.
    - cash-or-nothing call: 1 EUR/MWh se F_T > K, 0 altrimenti (put: se F_T < K)
    - asset-or-nothing call: F_T se F_T > K, 0 altrimenti (put: F_T se F_T < K)
    Nell'energia servono nei contratti di fornitura con trigger di prezzo
    (es. bonus/malus forfettario se il prezzo supera una soglia), nelle
    clausole cap con payout secco e per coprire eventi prezzo discreti.
    Formule Black-76 (driftless sul forward):
      cash call = df * N(d2) · cash put = df * N(-d2)
      asset call = df * F * N(d1) · asset put = df * F * N(-d1)
      d1 = (ln(F/K) + 0.5*sig^2*T) / (sig*sqrt(T)); d2 = d1 - sig*sqrt(T)
    Ancore esatte: parita' call+put cash = df, call+put asset = df*F;
    vol = 0 o T = 0 -> valore attualizzato del payout deterministico;
    K -> 0: cash call -> df, asset call -> df*F. NaN-safe: input non validi
    (tipo/payoff sconosciuti, F <= 0, K <= 0, mesi < 0, sig < 0, r < 0)
    -> dict neutro con valido = False.
    Ritorna dict con: premio, premio_vanilla (stessa call/put Black-76),
    prob_itm (probabilita' risk-neutral di finire in the money = N(+-d2)),
    delta (bump sul forward), intrinseco (valore del payout a F=K? no:
    valore digitale a scadenza se esercitata OGGI: cash 1/0, asset F/0),
    limite_sup (df per cash, df*F per asset), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio": float("nan"), "premio_vanilla": float("nan"),
              "prob_itm": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "limite_sup": float("nan"),
              "valido": False}
    try:
        pf = str(payoff).strip().lower()
        tp = str(tipo).strip().lower()
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r)):
        return neutro
    if pf not in ("cash", "asset") or tp not in ("call", "put"):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    is_call = (tp == "call")
    df = float(np.exp(-r * T))
    limite = df if pf == "cash" else df * F

    def _premio(ff):
        # premio digitale valutato al forward ff
        if T <= 0.0 or sig <= 0.0:
            itm = (ff > K) if is_call else (ff < K)
            at = (ff == K)
            unit = 0.5 if at else (1.0 if itm else 0.0)
            return df * unit if pf == "cash" else df * ff * unit
        sqt = sig * np.sqrt(T)
        d1 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        if pf == "cash":
            return df * (_norm.cdf(d2) if is_call else _norm.cdf(-d2))
        return df * ff * (_norm.cdf(d1) if is_call else _norm.cdf(-d1))

    def _vanilla(ff):
        # premio call/put vanilla Black-76 di confronto
        if T <= 0.0 or sig <= 0.0:
            intr = max(ff - K, 0.0) if is_call else max(K - ff, 0.0)
            return df * intr
        sqt = sig * np.sqrt(T)
        d1 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        if is_call:
            return df * (ff * _norm.cdf(d1) - K * _norm.cdf(d2))
        return df * (K * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    def _prob(ff):
        # prob. risk-neutral di finire ITM
        if T <= 0.0 or sig <= 0.0:
            return 0.5 if ff == K else (1.0 if (ff > K) == is_call else 0.0)
        sqt = sig * np.sqrt(T)
        d2 = (np.log(ff / K) + 0.5 * sig * sig * T) / sqt - sqt
        return float(_norm.cdf(d2) if is_call else _norm.cdf(-d2))

    out = dict(neutro)
    out.update({"valido": True, "premio": float(_premio(F)),
                "premio_vanilla": float(_vanilla(F)),
                "prob_itm": _prob(F),
                "limite_sup": float(limite)})
    if pf == "cash":
        out["intrinseco"] = 1.0 if (F > K) == is_call else 0.0
    else:
        out["intrinseco"] = float(F) if (F > K) == is_call else 0.0
    h = 0.01
    out["delta"] = float((_premio(F * (1 + h)) - _premio(F * (1 - h))) / (2 * F * h))
    return out

def calcola_chooser(forward, strike, mesi_scelta, mesi_scadenza, vol_pct, tasso_pct):
    """Premio di un'opzione CHOOSER semplice sul forward energetico (forma chiusa di Rubinstein).

    La chooser scade a T2 ma a una data di SCELTA t1 <= T2 il detentore decide
    se tenerla come call o come put (stesso strike K, stessa scadenza T2):
    valore a t1 = max(C(t1), P(t1)), dove C/P sono i valori Black-76 con vita
    residua T2-t1. Nell'energia serve a comprare oggi l'optionalita' sulla
    DIREZIONE del prezzo prima di un evento noto a data certa (asta di
    capacita', decisione regolatoria, stagione meteo): a t1, se il forward
    supera K si prende la call, altrimenti la put. Costa meno di uno straddle
    perche' a t1 se ne esercita una sola gamba invece di pagarle due oggi.
    Formule (Rubinstein 1991, forward driftless, r = risk-free):
      chooser = C(F, K, T2) + exp(-r*(T2-t1)) * P(F, K, t1)
    con C/P = call/put Black-76 (vedi calcola_black76). Intuizione: il primo
    termine e' il valore atteso della call a T2; il secondo e' l'extra dato
    dalla possibilita' di ripiegare sulla put (per parita' C-P = df*(F-K), a
    t1 si sceglie la call sse F(t1) > K, quindi la prob. risk-neutral di
    scegliere la call e' N(d2(F, K, t1))).
    Ancore esatte: t1 = 0 -> max(call, put) a T2 (scelta immediata); t1 = T2 ->
    call + put = straddle (a scadenza una gamba vale zero e l'altra |F-K|);
    vol = 0 -> df(T2)*|F-K| (deterministico); il premio e' sempre compreso tra
    max(call, put) e straddle, e cresce con la data di scelta t1.
    NaN-safe: input non validi (F <= 0, K <= 0, mesi < 0, t1 > T2, vol/tasso
    < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio, call, put (vanilla Black-76 a T2), straddle,
    risparmio_vs_straddle, prob_scelta_call, delta (bump sul forward),
    intrinseco (df*|F-K|), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio": float("nan"), "call": float("nan"), "put": float("nan"),
              "straddle": float("nan"), "risparmio_vs_straddle": float("nan"),
              "prob_scelta_call": float("nan"), "delta": float("nan"),
              "intrinseco": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike)
        t1 = float(mesi_scelta) / 12.0; T2 = float(mesi_scadenza) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, t1, T2, sig, r)):
        return neutro
    if F <= 0 or K <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0:
        return neutro

    def _b76(ff, kk, tt, cp):
        # Black-76 scalare; cp True = call, False = put
        dff = float(np.exp(-r * tt))
        if tt <= 0.0 or sig <= 0.0:
            intr = max(ff - kk, 0.0) if cp else max(kk - ff, 0.0)
            return dff * intr
        sqt = sig * np.sqrt(tt)
        d1 = (np.log(ff / kk) + 0.5 * sig * sig * tt) / sqt
        d2 = d1 - sqt
        if cp:
            return dff * (ff * _norm.cdf(d1) - kk * _norm.cdf(d2))
        return dff * (kk * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    def _premio(ff):
        cc = _b76(ff, K, T2, True)
        pp = _b76(ff, K, t1, False)
        return cc + float(np.exp(-r * (T2 - t1))) * pp

    C = _b76(F, K, T2, True)
    P = _b76(F, K, T2, False)
    straddle = C + P
    premio = _premio(F)
    if t1 > 0.0 and sig > 0.0:
        sqt1 = sig * np.sqrt(t1)
        d2t1 = (np.log(F / K) + 0.5 * sig * sig * t1) / sqt1 - sqt1
        prob_c = float(_norm.cdf(d2t1))
    else:
        prob_c = 0.5 if F == K else (1.0 if F > K else 0.0)
    out = dict(neutro)
    out.update({"valido": True, "premio": float(premio), "call": float(C),
                "put": float(P), "straddle": float(straddle),
                "risparmio_vs_straddle": float(straddle - premio),
                "prob_scelta_call": prob_c,
                "intrinseco": float(np.exp(-r * T2) * abs(F - K))})
    h = 0.01
    out["delta"] = float((_premio(F * (1 + h)) - _premio(F * (1 - h))) / (2 * F * h))
    return out


def calcola_forward_start(forward, alfa_pct, mesi_inizio, mesi_scadenza, vol_pct, tasso_pct):
    """Premio di un'opzione FORWARD START europea sul forward energetico (forma chiusa).

    La forward start scade a T2 ma la sua vita inizia a una data futura t1
    (0 <= t1 <= T2): a t1 lo strike viene fissato in modo proporzionale al
    prezzo di mercato, K = alfa * F(t1) (alfa = moneyness, tipicamente 100% =
    ATM). Da t1 a T2 e' una vanilla europea Black-76 con strike fisso alfa *
    F(t1). Nell'energia serve a comprare oggi un'assicurazione sul prezzo
    FUTURO senza fissare lo strike a livelli correnti: es. un consumatore
    che a gennaio vuole proteggere il Q4 ma non vuole ancorare lo strike
    al forward di oggi, o un produttore che vuole una floor che parta
    at-the-money solo dopo l'estate. Costa meno della vanilla con strike
    fisso alfa * F(0) perche' rinuncia all'optionalita' sul periodo [0, t1]
    (il premio decresce con t1).
    Formula (forward driftless, vol costante, r = risk-free, tau = T2 - t1):
      d1* = (-ln(alfa) + 0.5*sig^2*tau) / (sig*sqrt(tau)); d2* = d1* - sig*sqrt(tau)
      call_fs = df(T2) * F * (N(d1*) - alfa*N(d2*))
      put_fs  = df(T2) * F * (alfa*N(-d2*) - N(-d1*))
    Derivazione: condizionando a F(t1), il payoff atteso e' il prezzo
    Black-76 di una vanilla con forward F(t1) e strike alfa*F(t1), cioe'
    F(t1)*(N(d1*) - alfa*N(d2*)); prendendo l'attesa su F(t1) (martingala,
    E[F(t1)] = F, indipendenza degli incrementi) si ottiene la forma chiusa.
    Ancore esatte: t1 = 0 -> vanilla Black-76 con strike alfa*F(0);
    t1 = T2 -> premio 0 (nessuna vita residua); vol = 0 -> deterministico
    df(T2)*F*max(1-alfa,0) per la call, df(T2)*F*max(alfa-1,0) per la put;
    parita' call-put esatta: call_fs - put_fs = df(T2)*F*(1-alfa);
    call_fs <= vanilla call con strike alfa*F (concavita' in F);
    prob. risk-neutral di finire ITM: call -> N(d2*), put -> N(-d2*);
    delta analitica: call -> df(T2)*(N(d1*) - alfa*N(d2*)) (coincide con
    premio/F), put -> df(T2)*(alfa*N(-d2*) - N(-d1*)) (positiva: lo strike
    scala con F, quindi la put forward start cresce con il forward).
    NaN-safe: input non validi (F <= 0, alfa <= 0, t1 < 0, T2 <= 0,
    t1 > T2, vol/tasso < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_call, premio_put, vanilla_call, vanilla_put
    (vanilla Black-76 a T2 con strike alfa*F di confronto), diff_vs_vanilla
    (vanilla - fs) per call e put, parita_diff (scostamento dalla parita'
    esatta, ~0), prob_itm_call/put, delta_call/put, intrinseco_vol0_call/put,
    strike_atteso (alfa*F), valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_call": float("nan"), "premio_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "diff_vs_vanilla_call": float("nan"),
              "diff_vs_vanilla_put": float("nan"),
              "parita_diff": float("nan"),
              "prob_itm_call": float("nan"), "prob_itm_put": float("nan"),
              "delta_call": float("nan"), "delta_put": float("nan"),
              "intrinseco_vol0_call": float("nan"),
              "intrinseco_vol0_put": float("nan"),
              "strike_atteso": float("nan"), "valido": False}
    try:
        F = float(forward); alfa = float(alfa_pct) / 100.0
        t1 = float(mesi_inizio) / 12.0; T2 = float(mesi_scadenza) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, alfa, t1, T2, sig, r)):
        return neutro
    if F <= 0 or alfa <= 0 or t1 < 0 or T2 <= 0 or t1 > T2:
        return neutro
    if sig < 0 or r < 0:
        return neutro

    df2 = float(np.exp(-r * T2))
    tau = T2 - t1

    def _b76(ff, kk, tt, cp):
        # Black-76 scalare; cp True = call, False = put
        dff = float(np.exp(-r * tt))
        if tt <= 0.0 or sig <= 0.0:
            intr = max(ff - kk, 0.0) if cp else max(kk - ff, 0.0)
            return dff * intr
        sqt = sig * np.sqrt(tt)
        d1 = (np.log(ff / kk) + 0.5 * sig * sig * tt) / sqt
        d2 = d1 - sqt
        if cp:
            return dff * (ff * _norm.cdf(d1) - kk * _norm.cdf(d2))
        return dff * (kk * _norm.cdf(-d2) - ff * _norm.cdf(-d1))

    K = alfa * F
    van_c = _b76(F, K, T2, True)
    van_p = _b76(F, K, T2, False)

    if sig <= 0.0:
        # deterministico: F(t1) = F, strike = alfa*F
        pc = df2 * F * max(1.0 - alfa, 0.0)
        pp = df2 * F * max(alfa - 1.0, 0.0)
        prob_c = 1.0 if alfa < 1.0 else (0.5 if alfa == 1.0 else 0.0)
        dc = df2 if alfa < 1.0 else 0.0
        dp = df2 if alfa > 1.0 else 0.0
    elif tau <= 0.0:
        # t1 = T2 con vol > 0: opzione morta, nessun valore temporale
        pc = pp = 0.0
        prob_c = 1.0 if alfa < 1.0 else (0.5 if alfa == 1.0 else 0.0)
        dc = df2 * (1.0 - alfa) if alfa < 1.0 else 0.0
        dp = df2 * (alfa - 1.0) if alfa > 1.0 else 0.0
    else:
        sqtau = sig * np.sqrt(tau)
        d1s = (-np.log(alfa) + 0.5 * sig * sig * tau) / sqtau
        d2s = d1s - sqtau
        nd1 = float(_norm.cdf(d1s)); nd2 = float(_norm.cdf(d2s))
        nmd1 = 1.0 - nd1; nmd2 = 1.0 - nd2
        pc = df2 * F * (nd1 - alfa * nd2)
        pp = df2 * F * (alfa * nmd2 - nmd1)
        prob_c = float(_norm.cdf(d2s))
        dc = df2 * (nd1 - alfa * nd2)
        dp = df2 * (alfa * nmd2 - nmd1)
    prob_p = 1.0 - prob_c

    out = dict(neutro)
    out.update({"valido": True, "premio_call": float(pc), "premio_put": float(pp),
                "vanilla_call": float(van_c), "vanilla_put": float(van_p),
                "diff_vs_vanilla_call": float(van_c - pc),
                "diff_vs_vanilla_put": float(van_p - pp),
                "parita_diff": float((pc - pp) - df2 * F * (1.0 - alfa)),
                "prob_itm_call": float(prob_c), "prob_itm_put": float(prob_p),
                "delta_call": float(dc), "delta_put": float(dp),
                "intrinseco_vol0_call": float(df2 * F * max(1.0 - alfa, 0.0)),
                "intrinseco_vol0_put": float(df2 * F * max(alfa - 1.0, 0.0)),
                "strike_atteso": float(K)})
    return out


def calcola_quanto(forward, strike, mesi, vol_sott_pct, vol_cambio_pct, corr, tasso_pct, cambio=1.0):
    """Premio di un'opzione QUANTO europea sul forward energetico (forma chiusa).

    La QUANTO e' un'opzione su un sottostante denominato in VALUTA ESTERA il
    cui payoff viene convertito in valuta domestica a un TASSO DI CAMBIO
    FISSO X (niente rischio cambio sul payout). Nell'energia e' lo strumento
    standard dei prodotti cross-border e dei quanto "temperatura x prezzo":
    es. un'opzione sul forward power tedesco (EUR) regolata in CHF a cambio
    fisso, oppure un'opzione sul prezzo con sottostante indice climatico.
    Il pricing corregge il forward con il fattore quanto
      Fq = F * exp(-rho * sigS * sigX * T)
    (rho = correlazione sottostante/cambio, sigS = vol sottostante,
    sigX = vol cambio): se sottostante e cambio si muovono insieme
    (rho > 0), il forward quanto scende e la call vale meno della vanilla.
    Formule Black-76 sul forward corretto:
      d1 = (ln(Fq/K) + 0.5*sigS^2*T) / (sigS*sqrt(T)); d2 = d1 - sigS*sqrt(T)
      call = X * df * (Fq*N(d1) - K*N(d2))
      put  = X * df * (K*N(-d2) - Fq*N(-d1))
    Derivazione: sotto la misura risk-neutral domestica il forward estero
    ha drift -rho*sigS*sigX (aggiustamento di cambio numeraire), quindi il
    suo valore atteso e' Fq; condizionando, il prezzo e' Black-76 sul
    forward corretto con cambio fisso X.
    Ancore esatte: rho = 0 o sigX = 0 -> vanilla Black-76 su F (x X);
    sigS = 0 o T = 0 -> X*df*max(+- (Fq-K), 0) con Fq = F;
    parita' call-put esatta: call - put = X*df*(Fq - K);
    prob. risk-neutral di finire ITM: call -> N(d2), put -> N(-d2);
    delta sul forward estero: call -> X*df*exp(-rho*sigS*sigX*T)*N(d1),
    put -> X*df*exp(-rho*sigS*sigX*T)*(N(d1) - 1).
    NaN-safe: input non validi (F <= 0, K <= 0, T < 0, vol < 0, |rho| > 1,
    X <= 0, r < 0, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_call, premio_put, vanilla_call, vanilla_put
    (Black-76 con rho = 0 di confronto), diff_vs_vanilla_call/put,
    parita_diff (~0), fattore_quanto (exp(-rho*sigS*sigX*T)),
    forward_quanto (Fq), prob_itm_call/put, delta_call/put (sul forward
    estero, in valuta domestica per unita' di F), intrinseco_vol0_call/put,
    valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_call": float("nan"), "premio_put": float("nan"),
              "vanilla_call": float("nan"), "vanilla_put": float("nan"),
              "diff_vs_vanilla_call": float("nan"),
              "diff_vs_vanilla_put": float("nan"),
              "parita_diff": float("nan"),
              "fattore_quanto": float("nan"), "forward_quanto": float("nan"),
              "prob_itm_call": float("nan"), "prob_itm_put": float("nan"),
              "delta_call": float("nan"), "delta_put": float("nan"),
              "intrinseco_vol0_call": float("nan"),
              "intrinseco_vol0_put": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sigS = float(vol_sott_pct) / 100.0; sigX = float(vol_cambio_pct) / 100.0
        rho = float(corr); r = float(tasso_pct) / 100.0; X = float(cambio)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sigS, sigX, rho, r, X)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or X <= 0:
        return neutro
    if sigS < 0 or sigX < 0 or r < 0 or abs(rho) > 1:
        return neutro

    df = float(np.exp(-r * T))
    adj = float(np.exp(-rho * sigS * sigX * T))
    Fq = F * adj

    def _van(ff):
        # vanilla Black-76 sul forward ff (confronto: rho = 0 -> ff = F)
        if T <= 0.0 or sigS <= 0.0:
            intr_c = max(ff - K, 0.0); intr_p = max(K - ff, 0.0)
            return X * df * intr_c, X * df * intr_p
        sqt = sigS * np.sqrt(T)
        d1v = (np.log(ff / K) + 0.5 * sigS * sigS * T) / sqt
        d2v = d1v - sqt
        vc = X * df * (ff * _norm.cdf(d1v) - K * _norm.cdf(d2v))
        vp = X * df * (K * _norm.cdf(-d2v) - ff * _norm.cdf(-d1v))
        return vc, vp

    van_c, van_p = _van(F)

    if T <= 0.0 or sigS <= 0.0:
        # deterministico: Fq = F (adj = 1 se sigS = 0)
        pc = X * df * max(Fq - K, 0.0)
        pp = X * df * max(K - Fq, 0.0)
        prob_c = 0.5 if Fq == K else (1.0 if Fq > K else 0.0)
        dc = X * df * adj if Fq > K else 0.0
        dp = -X * df * adj if Fq < K else 0.0
    else:
        sqt = sigS * np.sqrt(T)
        d1 = (np.log(Fq / K) + 0.5 * sigS * sigS * T) / sqt
        d2 = d1 - sqt
        nd1 = float(_norm.cdf(d1)); nd2 = float(_norm.cdf(d2))
        nmd1 = 1.0 - nd1; nmd2 = 1.0 - nd2
        pc = X * df * (Fq * nd1 - K * nd2)
        pp = X * df * (K * nmd2 - Fq * nmd1)
        prob_c = float(_norm.cdf(d2))
        dc = X * df * adj * nd1
        dp = X * df * adj * (nd1 - 1.0)
    prob_p = 1.0 - prob_c

    out = dict(neutro)
    out.update({"valido": True, "premio_call": float(pc), "premio_put": float(pp),
                "vanilla_call": float(van_c), "vanilla_put": float(van_p),
                "diff_vs_vanilla_call": float(van_c - pc),
                "diff_vs_vanilla_put": float(van_p - pp),
                "parita_diff": float((pc - pp) - X * df * (Fq - K)),
                "fattore_quanto": float(adj), "forward_quanto": float(Fq),
                "prob_itm_call": float(prob_c), "prob_itm_put": float(prob_p),
                "delta_call": float(dc), "delta_put": float(dp),
                "intrinseco_vol0_call": float(X * df * max(F - K, 0.0)),
                "intrinseco_vol0_put": float(X * df * max(K - F, 0.0))})
    return out


def calcola_rainbow(s1, s2, strike, mesi, vol1_pct, vol2_pct, corr, tasso_pct, tipo="call_max"):
    """Premio di un'opzione RAINBOW europea su due forward energetici (formula chiusa di Stulz 1982).

    La RAINBOW e' un'opzione sul MIGLIORE (best-of, max) o sul PEGGIORE
    (worst-of, min) tra due sottostanti: call sul max = max(max(S1,S2)-K,0),
    put sul max, call sul min, put sul min. Nell'energia e' lo strumento
    naturale di due problemi ricorrenti: (1) la capacita' di
    interconnessione/transito, che vale il diritto di vendere sul mercato
    col prezzo piu' alto (best-of tra due hub); (2) il fuel switching, dove
    il costo e' il combustibile piu' economico (worst-of tra due fuel).
    Il driver chiave, oltre alle vol, e' la CORRELAZIONE: se i due prezzi si
    muovono insieme il best-of vale poco piu' della vanilla migliore, se si
    muovono per conto loro il premio esplode.
    Formule (convenzione forward: S1, S2 sono prezzi forward, quindi
    martingale; df = exp(-r*T)):
      sig^2 = v1^2+v2^2-2*rho*v1*v2
      y1 = (ln(S1/K)-v1^2*T/2)/(v1*sqrt(T))          [stile d2]
      y2 = (ln(S2/K)-v2^2*T/2)/(v2*sqrt(T))
      d   = (ln(S1/S2)+sig^2*T/2)/(sig*sqrt(T))      (soglia sotto Q1)
      d2s = (ln(S2/S1)+sig^2*T/2)/(sig*sqrt(T))
      e1  = (ln(S1/S2)-(v1^2-v2^2)*T/2)/(sig*sqrt(T)) (soglia sotto Q)
      e2  = -e1
      r1 = (v1-rho*v2)/sig;  r2 = (v2-rho*v1)/sig
      M(a,b;r) = CDF normale bivariata standard
      E[max] = S1*N(d)+S2*N(d2s)
      call_max = df*(S1*M(y1+v1*sqrt(T),d;r1)+S2*M(y2+v2*sqrt(T),d2s;r2)
                     -K*(M(y1,e1;r1)+M(y2,e2;r2)))
      put_max  = call_max - df*(E[max]-K)            (parita' esatta)
      call_min = BS_call(S1)+BS_call(S2)-call_max    (max+min = S1+S2)
      put_min  = BS_put(S1)+BS_put(S2)-put_max
      E[min]   = S1+S2-E[max]
    Delta analitici con derivate complete dei termini bivariati (la
    scomposizione asset-or-nothing/cash-or-nothing NON si semplifica perche'
    i due pezzi vivono sotto misure diverse, Q1/Q2 vs Q):
      dE[max]/dS1 = N(d)+phi(d)/(sig*sqrt(T))-S2*phi(d2s)/(S1*sig*sqrt(T))
      dput_max = dcall_max - df*dE[max]/dS   (dalla parita')
      dcall_min = dBS - dcall_max;  dput_min = dcall_min - df*(1-dE[max]/dS)
    Casi degeneri esatti: T=0 -> intrinseco; v1=v2=0 -> df*intrinseco;
    sig~0 (rho=+-1 e v1=v2) -> vanilla Black-76 sul max/min; v1=0 o v2=0 ->
    formule chiuse col sottostante deterministico.
    NaN-safe: input non validi -> dict neutro con valido=False.
    Ritorna dict con: premio, delta_s1, delta_s2, fwd_maxmin (E[max]/E[min]),
    intrinseco, vanilla_s1, vanilla_s2 (Black-76 di confronto),
    extra_vs_vanilla (premio - max delle vanille), parita_diff (~0), valido.
    Verifiche: cross-check Monte Carlo con antitetiche su 5 set di parametri,
    ancore esatte T=0/vol=0/S2->0->vanilla, parita', identita' min, delta vs
    bump, bound di arbitraggio call_max <= somma vanille
    (vedi hidden_files/test_rainbow_2026-09-30_1940.py)."""
    from scipy.stats import multivariate_normal as _mvn
    from scipy.stats import norm as _norm

    def _bvn(a, b, r):
        rr = min(max(float(r), -1.0 + 1e-9), 1.0 - 1e-9)
        return float(_mvn.cdf([float(a), float(b)], mean=[0.0, 0.0],
                              cov=[[1.0, rr], [rr, 1.0]]))

    def _bs(F, K, T, v, r):
        """Black-76 sul forward: (call, put, delta_call, delta_put, d1, d2)."""
        df_ = float(np.exp(-r * T))
        ic = max(F - K, 0.0)
        ip = max(K - F, 0.0)
        if T <= 0.0 or v <= 0.0:
            dc = df_ if F > K else 0.0
            dp = -df_ if F < K else 0.0
            return df_ * ic, df_ * ip, dc, dp, float("nan"), float("nan")
        sqt = v * np.sqrt(T)
        d1 = (np.log(F / K) + 0.5 * v * v * T) / sqt
        d2 = d1 - sqt
        c = df_ * (F * float(_norm.cdf(d1)) - K * float(_norm.cdf(d2)))
        p = df_ * (K * float(_norm.cdf(-d2)) - F * float(_norm.cdf(-d1)))
        return (c, p, df_ * float(_norm.cdf(d1)),
                -df_ * float(_norm.cdf(-d1)), d1, d2)

    neutro = {"premio": float("nan"), "delta_s1": float("nan"),
              "delta_s2": float("nan"), "fwd_maxmin": float("nan"),
              "intrinseco": float("nan"), "vanilla_s1": float("nan"),
              "vanilla_s2": float("nan"), "extra_vs_vanilla": float("nan"),
              "parita_diff": float("nan"), "valido": False}
    try:
        S1 = float(s1)
        S2 = float(s2)
        K = float(strike)
        T = float(mesi) / 12.0
        v1 = float(vol1_pct) / 100.0
        v2 = float(vol2_pct) / 100.0
        rho = float(corr)
        r = float(tasso_pct) / 100.0
        tipo = str(tipo)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (S1, S2, K, T, v1, v2, rho, r)):
        return neutro
    if (S1 <= 0 or S2 <= 0 or K <= 0 or T < 0 or v1 < 0 or v2 < 0
            or abs(rho) > 1 or r < 0
            or tipo not in ("call_max", "put_max", "call_min", "put_min")):
        return neutro

    df = float(np.exp(-r * T))
    M0 = max(S1, S2)
    m0 = min(S1, S2)
    is_max = tipo.endswith("max")
    is_call = tipo.startswith("call")
    base = M0 if is_max else m0
    intr = max(base - K, 0.0) if is_call else max(K - base, 0.0)

    c1, p1, dc1, dp1, _, _ = _bs(S1, K, T, v1, r)
    c2, p2, dc2, dp2, _, _ = _bs(S2, K, T, v2, r)

    cmax = pmax = cmin = pmin = float("nan")
    Emax = Emin = float("nan")
    d1_cmax = d2_cmax = d1_pmax = d2_pmax = float("nan")
    d1_cmin = d2_cmin = d1_pmin = d2_pmin = float("nan")

    if T == 0.0:
        cmax = max(M0 - K, 0.0)
        pmax = max(K - M0, 0.0)
        cmin = max(m0 - K, 0.0)
        pmin = max(K - m0, 0.0)
        Emax, Emin = M0, m0
        b1 = 1.0 if S1 >= S2 else 0.0
        b2 = 1.0 - b1
        w1 = 1.0 if S1 <= S2 else 0.0
        w2 = 1.0 - w1
        d1_cmax = b1 if S1 > K else 0.0
        d2_cmax = b2 if S2 > K else 0.0
        d1_pmax = -b1 if S1 < K else 0.0
        d2_pmax = -b2 if S2 < K else 0.0
        d1_cmin = w1 if S1 > K else 0.0
        d2_cmin = w2 if S2 > K else 0.0
        d1_pmin = -w1 if S1 < K else 0.0
        d2_pmin = -w2 if S2 < K else 0.0
    elif v1 == 0.0 and v2 == 0.0:
        cmax = df * max(M0 - K, 0.0)
        pmax = df * max(K - M0, 0.0)
        cmin = df * max(m0 - K, 0.0)
        pmin = df * max(K - m0, 0.0)
        Emax, Emin = M0, m0
        b1 = 1.0 if S1 >= S2 else 0.0
        b2 = 1.0 - b1
        w1 = 1.0 if S1 <= S2 else 0.0
        w2 = 1.0 - w1
        d1_cmax = df * b1 if S1 > K else 0.0
        d2_cmax = df * b2 if S2 > K else 0.0
        d1_pmax = -df * b1 if S1 < K else 0.0
        d2_pmax = -df * b2 if S2 < K else 0.0
        d1_cmin = df * w1 if S1 > K else 0.0
        d2_cmin = df * w2 if S2 > K else 0.0
        d1_pmin = -df * w1 if S1 < K else 0.0
        d2_pmin = -df * w2 if S2 < K else 0.0
    else:
        sig2 = v1 * v1 + v2 * v2 - 2.0 * rho * v1 * v2
        sig = float(np.sqrt(max(sig2, 0.0)))
        if sig < 1e-12:
            # rho = +-1 e v1 = v2: i due forward si muovono identici ->
            # max/min e' un singolo lognormale sul max/min iniziale.
            v = 0.5 * (v1 + v2)
            cc, pp, dcc, dpp, _, _ = _bs(M0, K, T, v, r)
            cmax, pmax = cc, pp
            Emax = M0
            i1 = 1.0 if S1 >= S2 else 0.0
            i2 = 1.0 - i1
            d1_cmax, d2_cmax = dcc * i1, dcc * i2
            d1_pmax, d2_pmax = dcc * i1 - df * i1, dcc * i2 - df * i2
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            d1_cmin = dc1 - d1_cmax
            d2_cmin = dc2 - d2_cmax
            d1_pmin = d1_cmin - df * (1.0 - i1)
            d2_pmin = d2_cmin - df * (1.0 - i2)
        elif v1 == 0.0 or v2 == 0.0:
            # Un sottostante deterministico (Sd), l'altro lognormale (Ss).
            if v1 == 0.0:
                Sd, Ss, vs, swap = S1, S2, v2, False
            else:
                Sd, Ss, vs, swap = S2, S1, v1, True
            ks = max(Sd, K)
            bs_ks = _bs(Ss, ks, T, vs, r)
            bs_sd = _bs(Ss, Sd, T, vs, r)
            cmax = df * max(Sd - K, 0.0) + bs_ks[0]
            Emax = Sd + bs_sd[0] / df
            pmax = cmax - df * (Emax - K)
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            nd2_sd = float(_norm.cdf(bs_sd[5]))
            nd1_sd = float(_norm.cdf(bs_sd[4]))
            dd_cmax = df * (1.0 - nd2_sd) if Sd >= K else 0.0
            ds_cmax = bs_ks[2]
            ed_d = 1.0 - nd2_sd
            ed_s = nd1_sd
            dd_pmax = dd_cmax - df * ed_d
            ds_pmax = ds_cmax - df * ed_s
            if not swap:
                d1_cmax, d2_cmax = dd_cmax, ds_cmax
                d1_pmax, d2_pmax = dd_pmax, ds_pmax
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - ed_d)
                d2_pmin = d2_cmin - df * (1.0 - ed_s)
            else:
                d2_cmax, d1_cmax = dd_cmax, ds_cmax
                d2_pmax, d1_pmax = dd_pmax, ds_pmax
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - ed_s)
                d2_pmin = d2_cmin - df * (1.0 - ed_d)
        else:
            sqT = float(np.sqrt(T))
            sqt1 = v1 * sqT
            sqt2 = v2 * sqT
            sqtS = sig * sqT
            y1 = (float(np.log(S1 / K)) - 0.5 * v1 * v1 * T) / sqt1
            y2 = (float(np.log(S2 / K)) - 0.5 * v2 * v2 * T) / sqt2
            d_ = (float(np.log(S1 / S2)) + 0.5 * sig * sig * T) / sqtS
            d2s = (float(np.log(S2 / S1)) + 0.5 * sig * sig * T) / sqtS
            e1 = (float(np.log(S1 / S2)) - 0.5 * (v1 * v1 - v2 * v2) * T) / sqtS
            e2 = -e1
            r1 = (v1 - rho * v2) / sig
            r2 = (v2 - rho * v1) / sig
            Ma = _bvn(y1 + sqt1, d_, r1)
            Mb = _bvn(y2 + sqt2, d2s, r2)
            Mq1 = _bvn(y1, e1, r1)
            Mq2 = _bvn(y2, e2, r2)
            nd = float(_norm.cdf(d_))
            nd2s = float(_norm.cdf(d2s))
            Emax = S1 * nd + S2 * nd2s
            cmax = df * (S1 * Ma + S2 * Mb - K * (Mq1 + Mq2))
            pmax = cmax - df * (Emax - K)
            cmin = c1 + c2 - cmax
            pmin = p1 + p2 - pmax
            Emin = S1 + S2 - Emax
            s1q = float(np.sqrt(max(1.0 - r1 * r1, 1e-24)))
            s2q = float(np.sqrt(max(1.0 - r2 * r2, 1e-24)))
            ph = _norm.pdf
            N = _norm.cdf
            if s1q > 1e-4 and s2q > 1e-4:
                dMa_dS1 = (ph(y1 + sqt1) * N((d_ - r1 * (y1 + sqt1)) / s1q) / (S1 * sqt1)
                           + ph(d_) * N((y1 + sqt1 - r1 * d_) / s1q) / (S1 * sqtS))
                dMq1_dS1 = (ph(y1) * N((e1 - r1 * y1) / s1q) / (S1 * sqt1)
                            + ph(e1) * N((y1 - r1 * e1) / s1q) / (S1 * sqtS))
                dT1dS1 = df * (Ma + S1 * dMa_dS1 - K * dMq1_dS1)
                dMa_dS2 = ph(d_) * N((y1 + sqt1 - r1 * d_) / s1q) * (-1.0 / (S2 * sqtS))
                dMq1_dS2 = ph(e1) * N((y1 - r1 * e1) / s1q) * (-1.0 / (S2 * sqtS))
                dT1dS2 = df * (S1 * dMa_dS2 - K * dMq1_dS2)
                dMb_dS2 = (ph(y2 + sqt2) * N((d2s - r2 * (y2 + sqt2)) / s2q) / (S2 * sqt2)
                           + ph(d2s) * N((y2 + sqt2 - r2 * d2s) / s2q) / (S2 * sqtS))
                dMq2_dS2 = (ph(y2) * N((e2 - r2 * y2) / s2q) / (S2 * sqt2)
                            + ph(e2) * N((y2 - r2 * e2) / s2q) / (S2 * sqtS))
                dT2dS2 = df * (Mb + S2 * dMb_dS2 - K * dMq2_dS2)
                dMb_dS1 = ph(d2s) * N((y2 + sqt2 - r2 * d2s) / s2q) * (-1.0 / (S1 * sqtS))
                dMq2_dS1 = ph(e2) * N((y2 - r2 * e2) / s2q) * (-1.0 / (S1 * sqtS))
                dT2dS1 = df * (S2 * dMb_dS1 - K * dMq2_dS1)
                dE_dS1 = nd + ph(d_) / sqtS - S2 * ph(d2s) / (S1 * sqtS)
                dE_dS2 = nd2s + ph(d2s) / sqtS - S1 * ph(d_) / (S2 * sqtS)
                d1_cmax = dT1dS1 + dT2dS1
                d2_cmax = dT1dS2 + dT2dS2
                d1_pmax = d1_cmax - df * dE_dS1
                d2_pmax = d2_cmax - df * dE_dS2
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - dE_dS1)
                d2_pmin = d2_cmin - df * (1.0 - dE_dS2)
            if not (np.isfinite(d1_cmax) and np.isfinite(d2_cmax)):
                # |rho| -> 1: i delta analitici sono instabili -> bump
                # sui prezzi (esatti) del ramo generale.
                def _px_max(Sa, Sb):
                    sqt1_ = v1 * sqT
                    sqt2_ = v2 * sqT
                    sqtS_ = sig * sqT
                    y1_ = (float(np.log(Sa / K)) - 0.5 * v1 * v1 * T) / sqt1_
                    y2_ = (float(np.log(Sb / K)) - 0.5 * v2 * v2 * T) / sqt2_
                    d__ = (float(np.log(Sa / Sb)) + 0.5 * sig * sig * T) / sqtS_
                    d2s_ = (float(np.log(Sb / Sa)) + 0.5 * sig * sig * T) / sqtS_
                    e1_ = (float(np.log(Sa / Sb)) - 0.5 * (v1 * v1 - v2 * v2) * T) / sqtS_
                    Ma_ = _bvn(y1_ + sqt1_, d__, r1)
                    Mb_ = _bvn(y2_ + sqt2_, d2s_, r2)
                    Mq1_ = _bvn(y1_, e1_, r1)
                    Mq2_ = _bvn(y2_, -e1_, r2)
                    Emax_ = Sa * float(_norm.cdf(d__)) + Sb * float(_norm.cdf(d2s_))
                    cmax_ = df * (Sa * Ma_ + Sb * Mb_ - K * (Mq1_ + Mq2_))
                    return cmax_, cmax_ - df * (Emax_ - K), Emax_
                h1 = 1e-4 * S1
                h2 = 1e-4 * S2
                c_up, p_up, _ = _px_max(S1 + h1, S2)
                c_dn, p_dn, _ = _px_max(S1 - h1, S2)
                d1_cmax = (c_up - c_dn) / (2.0 * h1)
                d1_pmax = (p_up - p_dn) / (2.0 * h1)
                c_up, p_up, _ = _px_max(S1, S2 + h2)
                c_dn, p_dn, _ = _px_max(S1, S2 - h2)
                d2_cmax = (c_up - c_dn) / (2.0 * h2)
                d2_pmax = (p_up - p_dn) / (2.0 * h2)
                dE_dS1 = (d1_cmax - d1_pmax) / df
                dE_dS2 = (d2_cmax - d2_pmax) / df
                d1_cmin = dc1 - d1_cmax
                d2_cmin = dc2 - d2_cmax
                d1_pmin = d1_cmin - df * (1.0 - dE_dS1)
                d2_pmin = d2_cmin - df * (1.0 - dE_dS2)

    out = dict(neutro)
    premia = {"call_max": cmax, "put_max": pmax,
              "call_min": cmin, "put_min": pmin}
    deltas = {"call_max": (d1_cmax, d2_cmax), "put_max": (d1_pmax, d2_pmax),
              "call_min": (d1_cmin, d2_cmin), "put_min": (d1_pmin, d2_pmin)}
    d1r, d2r = deltas[tipo]
    premio = premia[tipo]
    vs1 = c1 if is_call else p1
    vs2 = c2 if is_call else p2
    if is_max:
        par = (cmax - pmax) - df * (Emax - K)
        fwd = Emax
    else:
        par = (cmin - pmin) - df * (Emin - K)
        fwd = Emin
    out.update({"valido": True, "premio": float(premio),
                "delta_s1": float(d1r), "delta_s2": float(d2r),
                "fwd_maxmin": float(fwd), "intrinseco": float(intr),
                "vanilla_s1": float(vs1), "vanilla_s2": float(vs2),
                "extra_vs_vanilla": float(premio - max(vs1, vs2)),
                "parita_diff": float(par)})
    return out


# Zone supportate dal tab Spread transfrontaliero: codice ENTSO-E (live)
# e parametri del mock deterministico (demo). Offset/profili riflettono
# differenze tipiche reali: DE-LU piu' volatile con duck curve solare,
# FR piu' piatta (nucleare baseload), IT-NORD con picco serale e premio
# di congestione strutturale vs CH.
ZONE_XB = {
    "🇩🇪 Germania/Lussemburgo (DE-LU)": {"codice": "DE_LU", "seed": 21,
                                         "base": -4.0, "vol": 1.35,
                                         "duck": -14.0, "picco_serale": 0.0},
    "🇫🇷 Francia (FR)": {"codice": "FR", "seed": 33,
                         "base": -2.0, "vol": 0.80,
                         "duck": 0.0, "picco_serale": 4.0},
    "🇮🇹 Italia Nord (IT-NORD)": {"codice": "IT_North", "seed": 55,
                                 "base": 8.0, "vol": 1.10,
                                 "duck": 0.0, "picco_serale": 22.0},
}


def generate_mock_zona(start_date, end_date, zona):
    """Mock deterministico di una seconda zona di prezzo per lo spread transfrontaliero.

    Stesso profilo giornaliero/stagionalita' di generate_mock_hourly ma con
    seed, base, volatilita' e forma diversi per zona (vedi ZONE_XB): la
    correlazione imperfetta tra le due serie genera spread realistici con
    episodi di congestione. Deterministico: stesso input -> stessa serie.
    Zona sconosciuta -> serie vuota (valido=False a valle)."""
    cfg = ZONE_XB.get(zona)
    if cfg is None:
        return pd.Series(dtype=float, name="Prezzo Spot (€/MWh)")
    rng = np.random.default_rng(cfg["seed"])
    idx = pd.date_range(
        start=pd.Timestamp(start_date),
        end=pd.Timestamp(end_date) + pd.Timedelta(days=1) - pd.Timedelta(hours=1),
        freq="h", tz="Europe/Zurich",
    )
    ore = idx.hour.to_numpy()
    wd = idx.weekday.to_numpy()
    profilo_giornaliero = 25 * np.sin(2 * np.pi * (ore - 6) / 24) + 18 * np.sin(4 * np.pi * (ore - 9) / 24)
    # Duck curve tedesca: crollo dei prezzi a meta' giornata per il solare
    duck = np.where((ore >= 10) & (ore <= 15), cfg["duck"] * np.sin(np.pi * (ore - 10) / 5.0), 0.0)
    # Picco serale accentuato (es. domanda italiana 19-21)
    picco = np.where((ore >= 18) & (ore <= 21), cfg["picco_serale"], 0.0)
    sconto_weekend = np.where(wd < 5, 12.0, -18.0)
    trend = np.linspace(0, 15, len(idx))
    rumore = rng.normal(0, 9 * cfg["vol"], len(idx))
    spike = np.where(rng.random(len(idx)) < 0.008, rng.uniform(60, 160, len(idx)), 0.0)
    prezzi = np.clip(95 + cfg["base"] + profilo_giornaliero + duck + picco
                     + sconto_weekend + trend + rumore + spike, 5, None)
    s = pd.Series(prezzi, index=idx, name="Prezzo Spot (€/MWh)")
    s.index.name = "Data e Ora"
    return s


def calcola_spread_xb(pa, pb, capacita_mw=1.0):
    """Statistiche dello spread transfrontaliero tra due serie orarie.

    spread = pb - pa: con capacita' di interconnessione A->B, ogni ora con
    spread > 0 rende spread * capacita' € (arbitraggio perfetto, senza
    costi di transito/allocazione e senza vincoli di nomina). Il valore
    totale e' la somma dei max(spread, 0) — stima "intrinsic" della
    capacita', cioe' il floor sotto cui un'opzione best-of (tab rainbow)
    non puo' mai scendere.

    Le due serie vengono allineate per timestamp (inner join); le coppie
    con NaN vengono scartate. Se restano meno di 2 ore valide -> valido=False.
    Ritorna dict con KPI, serie dello spread allineata e profilo orario medio."""
    out = {"valido": False}
    try:
        cap = float(capacita_mw)
        if not np.isfinite(cap) or cap <= 0:
            return out
        a = pd.to_numeric(pa, errors="coerce")
        b = pd.to_numeric(pb, errors="coerce")
        df = pd.concat({"a": a, "b": b}, axis=1).dropna()
        if len(df) < 2:
            return out
        spread = (df["b"] - df["a"]).to_numpy(dtype=float)
        if not np.all(np.isfinite(spread)):
            return out
        pos = np.maximum(spread, 0.0)
        valore_tot = float(pos.sum()) * cap  # €: spread €/MWh * cap MW * 1h
        giorni = max(1, int((df.index.max() - df.index.min()).total_seconds() // 86400) + 1)
        ore_idx = df.index.hour.to_numpy()
        prof = np.array([spread[ore_idx == h].mean() if (ore_idx == h).any() else np.nan
                         for h in range(24)])
        out.update({
            "valido": True,
            "n_ore": int(len(spread)),
            "spread_medio": float(spread.mean()),
            "spread_max": float(spread.max()),
            "spread_min": float(spread.min()),
            "pct_ore_positive": float(100.0 * (spread > 0).mean()),
            "valore_totale_eur": valore_tot,
            "valore_giorno_eur": valore_tot / giorni,
            "valore_mw_giorno": valore_tot / cap / giorni,
            "correlazione": float(np.corrcoef(df["a"].to_numpy(), df["b"].to_numpy())[0, 1]),
            "serie_spread": pd.Series(spread, index=df.index, name="Spread (€/MWh)"),
            "profilo_orario": prof,
        })
    except Exception:
        return {"valido": False}
    return out


def generate_mock_gas(start_date, end_date):
    """Serie GIORNALIERA sintetica del prezzo gas TTF (€/MWh termico).

    Base ~38 €/MWh con premio invernale (+14 a gennaio) e sconto estivo
    (-14 a luglio), trend e spike casuali (seed fisso). Deterministica:
    stesso input -> stessa serie. ENTSO-E non pubblica prezzi gas, quindi
    la tab 'Stoccaggio gas' usa sempre questo mock (dichiarato nel banner).
    Se start > end -> serie vuota."""
    rng = np.random.default_rng(1234)
    idx = pd.date_range(start=pd.Timestamp(start_date), end=pd.Timestamp(end_date),
                        freq="D", tz="Europe/Zurich")
    if len(idx) == 0:
        return pd.Series(dtype=float, name="Prezzo Gas TTF (€/MWh)")
    doy = idx.dayofyear.to_numpy()
    stag = 14.0 * np.cos(2 * np.pi * (doy - 15) / 365.25)
    trend = np.linspace(0, 6, len(idx))
    rumore = rng.normal(0, 2.5, len(idx))
    spike = np.where(rng.random(len(idx)) < 0.02, rng.uniform(8, 25, len(idx)), 0.0)
    prezzi = np.clip(38 + stag + trend + rumore + spike, 12, None)
    s = pd.Series(prezzi, index=idx, name="Prezzo Gas TTF (€/MWh)")
    s.index.name = "Giorno"
    return s


def calcola_stoccaggio_gas(prezzi_gas, capacita_gwh, inj_rate_gwh_g, wd_rate_gwh_g,
                           costo_inj_eur_mwh=0.4, costo_wd_eur_mwh=0.4,
                           inv_iniziale_pct=50.0, inv_finale_pct=50.0,
                           solo_valore=False):
    """Valore INTRINSECO di uno stoccaggio gas (ottimizzazione LP esatta).

    Massimizza, su prezzi giornalieri noti (perfect foresight),
      sum_d [ wd_d * (P_d - c_wd) - inj_d * (P_d + c_inj) ]
    con vincoli: 0 <= inj_d <= tasso_iniezione, 0 <= wd_d <= tasso_erogazione,
    giacenza S_d = S0 + cumsum(inj - wd) in [0, capacita'], S_N = giacenza finale
    target. Risolto con programmazione lineare (scipy HiGHS): l'ottimo e'
    esatto, non euristico.

    Il valore intrinseco e' il FLOOR del valore dello stoccaggio: la
    flessibilita' di ribilanciare le nomine in corso d'opera (valore
    ESTRINSECO) vale >= 0 e si prezza con modelli stocastici.

    Parametri prezzi_gas: Series (qualsiasi frequenza: viene ricampionata a
    media giornaliera). capacita_gwh: working gas. Tassi in GWh/giorno.
    Costi variabili in €/MWh. Giacenze in % della capacita'.

    Se giacenza finale != iniziale, il valore include il costo/ricavo forzato
    del riempimento/svuotamento netto (es. obbligo di riempimento).

    Ritorna dict: valido, valore_intrinseco_eur, valore_per_gwh_eur,
    cicli_equivalenti, energia_iniettata_gwh, energia_prelevata_gwh,
    prezzo_medio_acquisto, prezzo_medio_vendita, spread_medio_catturato,
    pnl_mensile (DataFrame), serie inventario/iniezioni/prelievi.
    Meno di 2 giorni validi, capacita' o tassi non positivi -> valido=False.
    solo_valore=True: percorso veloce (solo valido/n_giorni/
    valore_intrinseco_eur, niente DataFrame) per il Monte Carlo.
    """
    out = {"valido": False}
    try:
        from scipy.optimize import linprog as _linprog
        from scipy import sparse as _sparse
        p = pd.to_numeric(prezzi_gas, errors="coerce")
        if not isinstance(p, pd.Series):
            p = pd.Series(p)
        p = p.resample("D").mean().dropna()
        n = len(p)
        if n < 2:
            return out
        cap = float(capacita_gwh)
        ri = float(inj_rate_gwh_g)
        rw = float(wd_rate_gwh_g)
        ci = float(costo_inj_eur_mwh)
        cw = float(costo_wd_eur_mwh)
        if not all(np.isfinite([cap, ri, rw, ci, cw])) or cap <= 0 or ri <= 0 or rw <= 0:
            return out
        if ci < 0 or cw < 0:
            return out
        s0 = cap * float(np.clip(inv_iniziale_pct, 0.0, 100.0)) / 100.0
        st_ = cap * float(np.clip(inv_finale_pct, 0.0, 100.0)) / 100.0
        P = p.to_numpy(dtype=float)
        if not np.all(np.isfinite(P)):
            return out
        # x = [inj_0..inj_{n-1}, wd_0..wd_{n-1}]; minimizza c^T x
        # Matrici sparse: ~5x piu' veloci di quelle dense su questo LP
        # (critico per il Monte Carlo dello stoccaggio estrinseco).
        c = np.concatenate([P + ci, -(P - cw)])
        L = _sparse.tril(_sparse.csr_matrix(np.ones((n, n))))
        A_ub = _sparse.vstack([_sparse.hstack([L, -L]),
                               _sparse.hstack([-L, L])]).tocsr()
        b_ub = np.concatenate([np.full(n, cap - s0), np.full(n, s0)])
        A_eq = _sparse.csr_matrix(np.concatenate([np.ones(n), -np.ones(n)]).reshape(1, -1))
        b_eq = np.array([st_ - s0])
        bounds = [(0.0, ri)] * n + [(0.0, rw)] * n
        res = _linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                       bounds=bounds, method="highs")
        if not res.success:
            return out
        inj = np.clip(res.x[:n], 0.0, None)
        wd = np.clip(res.x[n:], 0.0, None)
        inv = s0 + np.cumsum(inj - wd)
        valore = float(-res.fun)
        if valore < 0 and valore > -1e-6:
            valore = 0.0
        if solo_valore:
            # Percorso veloce per il Monte Carlo: solo l'ottimo, niente DataFrame
            out.update({"valido": True, "n_giorni": int(n),
                        "valore_intrinseco_eur": valore})
            return out
        e_inj = float(inj.sum())
        e_wd = float(wd.sum())
        pa = float((inj * P).sum() / e_inj) if e_inj > 0 else float("nan")
        pv = float((wd * P).sum() / e_wd) if e_wd > 0 else float("nan")
        pnl_g = wd * (P - cw) - inj * (P + ci)
        df_g = pd.DataFrame({"iniezione_gwh": np.round(inj, 3),
                             "prelievo_gwh": np.round(wd, 3),
                             "giacenza_gwh": np.round(inv, 3),
                             "prezzo_eur_mwh": np.round(P, 2),
                             "pnl_eur": np.round(pnl_g, 2)},
                            index=p.index)
        mese = df_g.index.strftime("%Y-%m")
        pnl_m = (df_g.assign(_m=mese).groupby("_m")
                 .agg(iniezione_gwh=("iniezione_gwh", "sum"),
                      prelievo_gwh=("prelievo_gwh", "sum"),
                      pnl_eur=("pnl_eur", "sum")).reset_index()
                 .rename(columns={"_m": "mese"}))
        out.update({
            "valido": True,
            "n_giorni": int(n),
            "valore_intrinseco_eur": valore,
            "valore_per_gwh_eur": valore / cap,
            "cicli_equivalenti": e_wd / cap,
            "energia_iniettata_gwh": e_inj,
            "energia_prelevata_gwh": e_wd,
            "prezzo_medio_acquisto": pa,
            "prezzo_medio_vendita": pv,
            "spread_medio_catturato": (pv - pa) if np.isfinite(pa) and np.isfinite(pv) else float("nan"),
            "giacenza_iniziale_gwh": float(s0),
            "giacenza_finale_gwh": float(st_),
            "pnl_mensile": pnl_m,
            "serie_giornaliera": df_g,
        })
    except Exception:
        return {"valido": False}
    return out


@st.cache_data(show_spinner=False)
def calcola_stoccaggio_estrinseco(prezzi_gas, capacita_gwh, inj_rate_gwh_g, wd_rate_gwh_g,
                                  costo_inj_eur_mwh=0.4, costo_wd_eur_mwh=0.4,
                                  inv_iniziale_pct=50.0, inv_finale_pct=50.0,
                                  n_scenari=100, vol_annua_pct=35.0,
                                  mean_reversion_giorni=30.0, seed=1234):
    """Valore ESTRINSECO di uno stoccaggio gas (Monte Carlo su prezzi stocastici).

    Il tab 'Stoccaggio gas' calcola il valore INTRINSECO: floor deterministico
    sotto perfect foresight. Nella realta' i prezzi futuri sono incerti e lo
    stoccaggio puo' ribilanciare le nomine in corso d'opera: questa
    opzionalita' operativa vale >= 0 e qui viene prezzata con Monte Carlo.

    Per ogni scenario si simula un percorso giornaliero del prezzo gas:
    GBM lognormale con mean reversion alla curva base deterministica
    (deviazioni AR(1): X_t = phi*X_{t-1} + sigma_d*z_t, phi = exp(-1/mr)),
    seed fisso -> completamente riproducibile. Su ciascun percorso si
    ricalcola il valore intrinseco ottimale con la stessa LP esatta; il valore
    estrinseco e' la MEDIA dei valori ottimali per scenario.

    Per convessita' del valore LP nei prezzi, E[V(P)] >= V(E[P]): a meno del
    rumore di simulazione l'estrinseco e' sempre >= dell'intrinseco.
    La differenza e' il premio di flessibilita' operativa (numero da portare
    alle aste di capacita' e alle due diligence).

    Parametri prezzi_*/capacita'/tassi/costi/giacenze come in
    calcola_stoccaggio_gas. n_scenari: percorsi simulati (20-300 consigliati).
    vol_annua_pct: volatilita' logaritmica annua dei prezzi gas.
    mean_reversion_giorni: scala temporale di rientro delle deviazioni.
    Ritorna dict: valido, n_giorni, n_scenari, vol_annua_pct,
    valore_intrinseco_eur, valore_estrinseco_eur, p10_eur, p90_eur, std_eur,
    premio_estrinseco_eur, premio_pct, valori_eur (lista). Input non validi
    (meno di 2 giorni, capacita'/tassi non positivi, vol negativa) ->
    {"valido": False}.
    """
    out = {"valido": False}
    try:
        base = calcola_stoccaggio_gas(prezzi_gas, capacita_gwh, inj_rate_gwh_g,
                                      wd_rate_gwh_g, costo_inj_eur_mwh,
                                      costo_wd_eur_mwh, inv_iniziale_pct,
                                      inv_finale_pct)
        if not base.get("valido"):
            return out
        p = pd.to_numeric(prezzi_gas, errors="coerce")
        if not isinstance(p, pd.Series):
            p = pd.Series(p)
        p = p.resample("D").mean().dropna().clip(lower=0.5)
        n = len(p)
        if n < 2:
            return out
        nsc = max(1, int(n_scenari))
        vol = float(vol_annua_pct) / 100.0
        mr = max(1.0, float(mean_reversion_giorni))
        if not np.isfinite(vol) or vol < 0 or not np.isfinite(mr):
            return out
        phi = float(np.exp(-1.0 / mr))
        sig_d = vol / np.sqrt(365.0)
        rng = np.random.default_rng(int(seed))
        logb = np.log(p.to_numpy())
        intr = float(base["valore_intrinseco_eur"])
        # Deviazioni log-prezzo AR(1) stazionarie a media zero
        z = rng.standard_normal((nsc, n))
        xs = np.empty((nsc, n))
        x = np.zeros(nsc)
        for t in range(n):
            x = phi * x + sig_d * z[:, t]
            xs[:, t] = x
        valori = np.empty(nsc)
        for i in range(nsc):
            ps = pd.Series(np.exp(logb + xs[i]), index=p.index)
            r = calcola_stoccaggio_gas(ps, capacita_gwh, inj_rate_gwh_g,
                                       wd_rate_gwh_g, costo_inj_eur_mwh,
                                       costo_wd_eur_mwh, inv_iniziale_pct,
                                       inv_finale_pct, solo_valore=True)
            valori[i] = float(r["valore_intrinseco_eur"]) if r.get("valido") else float("nan")
        ok = valori[np.isfinite(valori)]
        if len(ok) == 0:
            return out
        estr = float(ok.mean())
        premio = estr - intr
        out.update({
            "valido": True,
            "n_giorni": int(n),
            "n_scenari": int(nsc),
            "vol_annua_pct": float(vol_annua_pct),
            "valore_intrinseco_eur": intr,
            "valore_estrinseco_eur": estr,
            "p10_eur": float(np.percentile(ok, 10)),
            "p90_eur": float(np.percentile(ok, 90)),
            "std_eur": float(ok.std()),
            "premio_estrinseco_eur": float(premio),
            "premio_pct": float(100.0 * premio / intr) if intr > 0 else float("nan"),
            "valori_eur": [float(v) for v in ok],
        })
    except Exception:
        return {"valido": False}
    return out


def ottimizza_ricarica_ev(prezzi_24, energia_kwh, potenza_kw, ora_arrivo=17,
                          ora_partenza=7, efficienza_pct=92.0, capacita_kwh=None,
                          soc_iniziale_pct=20.0):
    """Piano di ricarica ottimale di un veicolo elettrico sui prezzi orari.

    Dato il profilo di 24 prezzi orari (€/MWh) e una finestra di sosta
    [ora_arrivo, ora_partenza) — che puo' attraversare la mezzanotte —
    trova il piano di ricarica a costo minimo: alloca la potenza sulle ore
    piu' economiche della finestra. Con costi lineari e vincoli di sola
    potenza/energia (nessuna dinamica di stato oltre il SoC finale) il
    greedy sulle ore ordinate per prezzo e' l'ottimo esatto, non
    un'approssimazione.
    Confronta con la baseline "ricarica immediata" (attacca la spina
    all'arrivo e carica a potenza massima finche' non e' pieno): il
    risparmio e' il valore economico dello smart charging, la metrica che
    un energy analyst usa per dimensionare tariffe ToU o wallbox
    intelligenti per flotte aziendali.
    Parametri: prezzi_24 sequenza di 24 prezzi orari €/MWh; energia_kwh
    energia da immettere in batteria; potenza_kw potenza max del
    caricatore; ora_arrivo/ora_partenza interi 0-23 (se uguali = 24h);
    efficienza_pct rendimento di ricarica (l'energia prelevata dalla rete
    e' energia_kwh/efficienza); capacita_kwh e soc_iniziale_pct opzionali
    per il vincolo di capienza della batteria.
    Ritorna dict con: schedario (lista di 24 potenze kW), costo_ottimale,
    costo_immediata, risparmio_eur, risparmio_pct, prezzo_medio_ott
    (€/MWh), prezzo_medio_finestra (€/MWh), ore_ricarica, energia_rete_kwh,
    valido, motivo. NaN-safe: input non validi -> dict neutro con
    valido=False."""
    neutro = {"schedario": [0.0] * 24, "costo_ottimale": float("nan"),
              "costo_immediata": float("nan"), "risparmio_eur": float("nan"),
              "risparmio_pct": float("nan"), "prezzo_medio_ott": float("nan"),
              "prezzo_medio_finestra": float("nan"), "ore_ricarica": 0,
              "energia_rete_kwh": float("nan"), "valido": False,
              "motivo": "input non validi"}
    try:
        pr = [float(x) for x in list(prezzi_24)[:24]]
        en = float(energia_kwh)
        pw = float(potenza_kw)
        ha = int(ora_arrivo) % 24
        hp = int(ora_partenza) % 24
        eff = float(efficienza_pct) / 100.0
    except (TypeError, ValueError):
        return neutro
    if len(pr) != 24 or not all(np.isfinite(p) for p in pr):
        return neutro
    if not all(np.isfinite(v) for v in (en, pw, eff)):
        return neutro
    if en <= 0 or pw <= 0 or not 0.0 < eff <= 1.0:
        return dict(neutro, motivo="energia e potenza devono essere > 0, efficienza in (0,100]")
    if capacita_kwh is not None:
        try:
            cap = float(capacita_kwh)
            soc0 = float(soc_iniziale_pct)
        except (TypeError, ValueError):
            return dict(neutro, motivo="capacita'/SoC non numerici")
        if not (np.isfinite(cap) and np.isfinite(soc0)) or cap <= 0:
            return dict(neutro, motivo="capacita' batteria non valida")
        spazio = cap * max(0.0, 1.0 - soc0 / 100.0)
        if en > spazio + 1e-9:
            return dict(neutro, motivo=f"l'energia richiesta ({en:.1f} kWh) supera lo spazio in batteria ({spazio:.1f} kWh)")
    ore_finestra = []
    h = ha
    while True:
        ore_finestra.append(h)
        h = (h + 1) % 24
        if h == hp:
            break
    energia_rete = en / eff
    if len(ore_finestra) * pw < energia_rete - 1e-9:
        return dict(neutro, motivo="finestra troppo corta: servono piu' ore o piu' potenza")
    # Ottimo: ore della finestra ordinate per prezzo crescente (stabile per ora)
    ordine_ott = sorted(ore_finestra, key=lambda hh: (pr[hh], hh))
    sched = [0.0] * 24
    residuo = energia_rete
    for hh in ordine_ott:
        q = min(pw, residuo)
        sched[hh] = q
        residuo -= q
        if residuo <= 1e-9:
            break
    # Baseline: ricarica immediata dall'arrivo a potenza massima
    sched_naive = [0.0] * 24
    residuo = energia_rete
    for hh in ore_finestra:
        q = min(pw, residuo)
        sched_naive[hh] = q
        residuo -= q
        if residuo <= 1e-9:
            break
    costo_ott = sum(sched[hh] * pr[hh] for hh in ore_finestra) / 1000.0
    costo_nav = sum(sched_naive[hh] * pr[hh] for hh in ore_finestra) / 1000.0
    risparmio = costo_nav - costo_ott
    out = dict(neutro)
    out.update({"schedario": sched, "costo_ottimale": float(costo_ott),
                "costo_immediata": float(costo_nav),
                "risparmio_eur": float(risparmio),
                "risparmio_pct": float(100.0 * risparmio / costo_nav) if costo_nav > 0 else 0.0,
                "prezzo_medio_ott": float(costo_ott / en * 1000.0),
                "prezzo_medio_finestra": float(sum(pr[hh] for hh in ore_finestra) / len(ore_finestra)),
                "ore_ricarica": int(sum(1 for hh in ore_finestra if sched[hh] > 1e-9)),
                "energia_rete_kwh": float(energia_rete),
                "valido": True, "motivo": ""})
    return out


def calcola_americana(forward, strike, mesi, vol_pct, tasso_pct, n_step=200):
    """Premio di un'opzione AMERICANA su forward energetico (albero binomiale CRR).

    L'opzione AMERICANA puo' essere esercitata in QUALSIASI momento prima della
    scadenza (non solo a scadenza come l'europea): il suo prezzo incorpora la
    flessibilita' di "uscire" quando conviene. E' il modello naturale delle
    opzionalita' FISICHE dell'energy (una centrale che si accende/spegne ogni
    giorno, uno stoccaggio, un tolling con esercizio giornaliero): la
    differenza americana - europea e' l'EARLY-EXERCISE PREMIUM, cioe' quanto
    vale poter decidere prima della scadenza.
    Albero CRR sul forward (misura T-forward: il forward ha drift nullo):
      dt = T/N; u = exp(sig*sqrt(dt)); d = 1/u
      p = (1-d)/(u-d) (prob. risk-neutral); df_step = exp(-r*dt)
    Backward induction con esercizio anticipato a ogni nodo:
      V = max(intrinseco, df_step*(p*V_up + (1-p)*V_down))
    Convenzione di esercizio STILE FUTURES (come le opzioni su futures
    power/gas di EEX/ICE): l'esercizio consegna CASH pari all'intrinseco
    (F_t - K per la call). Per questo, con tasso r > 0, l'esercizio
    anticipato puo' essere ottimale ANCHE per la call deep ITM (si incassa
    subito l'intrinseco e lo si mette a frutto); con r = 0 l'americana
    coincide con l'europea. E' diverso dalle opzioni su forward OTC, dove
    l'esercizio consegna un contratto forward (e l'americana = europea).
    Sullo stesso albero si calcola anche l'europea (senza max) e il
    riferimento Black-76 in forma chiusa.
    Ancore esatte: (1) con r = 0, americana = europea sullo stesso albero
    (nessun interesse da incassare anticipando: check a tolleranza
    stretta); (2) parita' call-put europea ESATTA sull'albero:
    C - P = df*(F - K); (3) T = 0 o vol = 0 -> americana = intrinseco NON
    scontato (se ITM conviene esercitare subito), europea = df*intrinseco;
    (4) put americana deep ITM ~= intrinseco (esercizio immediato
    ottimale); (5) europea su albero -> Black-76 per N -> infinito
    (convergenza CRR, verifica nel tab).
    NaN-safe: input non validi (F <= 0, K <= 0, T < 0, vol < 0, r < 0,
    n_step < 1 o > 2000, NaN, stringhe) -> dict neutro con valido = False.
    Ritorna dict con: premio_am_call/put, premio_eu_call/put (stesso albero),
    bs_call/bs_put (Black-76 di riferimento), early_premium_call/put,
    parita_diff (~0), delta_am_call/put (dall'albero, al nodo radice),
    esercizio_immediato_call/put (bool: alla radice conviene esercitare ora),
    intrinseco_call/put, valido."""
    from scipy.stats import norm as _norm

    neutro = {"premio_am_call": float("nan"), "premio_am_put": float("nan"),
              "premio_eu_call": float("nan"), "premio_eu_put": float("nan"),
              "bs_call": float("nan"), "bs_put": float("nan"),
              "early_premium_call": float("nan"),
              "early_premium_put": float("nan"),
              "parita_diff": float("nan"),
              "delta_am_call": float("nan"), "delta_am_put": float("nan"),
              "esercizio_immediato_call": False,
              "esercizio_immediato_put": False,
              "intrinseco_call": float("nan"),
              "intrinseco_put": float("nan"), "valido": False}
    try:
        F = float(forward); K = float(strike); T = float(mesi) / 12.0
        sig = float(vol_pct) / 100.0; r = float(tasso_pct) / 100.0
        Ns = float(n_step)
    except (TypeError, ValueError):
        return neutro
    if not all(np.isfinite(v) for v in (F, K, T, sig, r, Ns)):
        return neutro
    if F <= 0 or K <= 0 or T < 0 or sig < 0 or r < 0:
        return neutro
    if not Ns.is_integer() or not 1 <= Ns <= 2000:
        return neutro
    N = int(Ns)

    df = float(np.exp(-r * T))
    intr_c = max(F - K, 0.0)
    intr_p = max(K - F, 0.0)

    def _bs():
        # Black-76 di riferimento (forma chiusa)
        if T <= 0.0 or sig <= 0.0:
            return df * intr_c, df * intr_p
        sqt = sig * np.sqrt(T)
        d1 = (np.log(F / K) + 0.5 * sig * sig * T) / sqt
        d2 = d1 - sqt
        c = df * (F * _norm.cdf(d1) - K * _norm.cdf(d2))
        p_ = df * (K * _norm.cdf(-d2) - F * _norm.cdf(-d1))
        return float(c), float(p_)

    bs_c, bs_p = _bs()

    if T <= 0.0 or sig <= 0.0:
        # deterministico: l'americana ITM si esercita subito (non scontata)
        out = dict(neutro)
        out.update({"valido": True, "premio_am_call": float(intr_c),
                    "premio_am_put": float(intr_p),
                    "premio_eu_call": float(bs_c), "premio_eu_put": float(bs_p),
                    "bs_call": float(bs_c), "bs_put": float(bs_p),
                    "early_premium_call": float(intr_c - bs_c),
                    "early_premium_put": float(intr_p - bs_p),
                    "parita_diff": float((bs_c - bs_p) - df * (F - K)),
                    "delta_am_call": 1.0 if F > K else 0.0,
                    "delta_am_put": -1.0 if F < K else 0.0,
                    "esercizio_immediato_call": bool(intr_c > 0),
                    "esercizio_immediato_put": bool(intr_p > 0),
                    "intrinseco_call": float(intr_c),
                    "intrinseco_put": float(intr_p)})
        return out

    dt = T / N
    u = float(np.exp(sig * np.sqrt(dt)))
    d = 1.0 / u
    disc = float(np.exp(-r * dt))
    p = (1.0 - d) / (u - d)

    j = np.arange(N + 1, dtype=float)
    ST = F * np.power(u, j) * np.power(d, N - j)
    Vc = np.maximum(ST - K, 0.0)   # americana call ai nodi terminali
    Vp = np.maximum(K - ST, 0.0)   # americana put ai nodi terminali
    Ec = Vc.copy()                 # europea call (stesso albero)
    Ep = Vp.copy()                 # europea put (stesso albero)
    STn = ST.copy()
    cont_c0 = cont_p0 = None
    Vc1 = Vp1 = ST1 = None
    for i in range(N, 0, -1):
        if i == 1:
            # valori americani (con esercizio) e sottostante al passo 1:
            # servono per delta ed esercizio-immediato alla radice
            Vc1 = Vc.copy(); Vp1 = Vp.copy(); ST1 = STn.copy()
        STn = STn[:-1] * u          # S(i,j) = S(i+1,j)/d = S(i+1,j)*u
        intr_c_i = np.maximum(STn - K, 0.0)
        intr_p_i = np.maximum(K - STn, 0.0)
        cont_c = disc * (p * Vc[1:] + (1.0 - p) * Vc[:-1])
        cont_p = disc * (p * Vp[1:] + (1.0 - p) * Vp[:-1])
        if i == 1:
            cont_c0 = float(cont_c[0]); cont_p0 = float(cont_p[0])
        Vc = np.maximum(intr_c_i, cont_c)
        Vp = np.maximum(intr_p_i, cont_p)
        Ec = disc * (p * Ec[1:] + (1.0 - p) * Ec[:-1])
        Ep = disc * (p * Ep[1:] + (1.0 - p) * Ep[:-1])

    am_c = float(Vc[0]); am_p = float(Vp[0])
    eu_c = float(Ec[0]); eu_p = float(Ep[0])
    dST = float(ST1[1] - ST1[0])
    delta_c = float((Vc1[1] - Vc1[0]) / dST) if dST > 0 else 0.0
    delta_p = float((Vp1[1] - Vp1[0]) / dST) if dST > 0 else 0.0

    out = dict(neutro)
    out.update({"valido": True, "premio_am_call": am_c, "premio_am_put": am_p,
                "premio_eu_call": eu_c, "premio_eu_put": eu_p,
                "bs_call": bs_c, "bs_put": bs_p,
                "early_premium_call": float(am_c - eu_c),
                "early_premium_put": float(am_p - eu_p),
                "parita_diff": float((eu_c - eu_p) - df * (F - K)),
                "delta_am_call": delta_c, "delta_am_put": delta_p,
                "esercizio_immediato_call": bool(intr_c > 0 and intr_c >= cont_c0),
                "esercizio_immediato_put": bool(intr_p > 0 and intr_p >= cont_p0),
                "intrinseco_call": float(intr_c),
                "intrinseco_put": float(intr_p)})
    return out


def render_kpi(title, value, col):
    col.markdown(f"<div class='metric-container'><div class='metric-label'>{title}</div><div class='metric-val'>{value}</div></div>", unsafe_allow_html=True)

def calcola_qualita_dati(prezzi, soglia_z=4.0, run_piatta_ore=6):
    """Audit di qualita' dei dati della serie oraria dei prezzi.

    Domanda operativa: "posso fidarmi dei numeri che vedo negli altri
    tab?" — controlla l'integrita' della serie oraria prima di qualsiasi
    analisi: ore mancanti rispetto alla griglia oraria attesa, timestamp
    duplicati (es. ora ambigua del cambio DST), valori NaN, sequenze di
    valori identici ("dato congelato"), outlier statistici e prezzi
    negativi.

    - soglia_z: soglia di z-score robusto (mediana/MAD) oltre la quale un
      valore e' outlier;
    - run_piatta_ore: lunghezza minima (ore) di una sequenza di valori
      identici per segnalarla come episodio "congelato" sospetto;
    - score 0-100: 100 meno penalita' pesate per gravita' (ore mancanti
      fino a -30, duplicati -10, NaN fino a -15, episodi congelati fino
      a -15, outlier fino a -10); verdetto 🟢 >= 90, 🟡 70-89, 🔴 < 70.

    NaN-safe: serie vuota, indice non-datetime o valori non numerici ->
    errore pulito; indice tz-aware reso naive (convenzione degli altri
    tab); indice non ordinato -> ordinato e segnalato. I prezzi negativi
    sono solo informativi (legittimi sullo spot europeo).

    Ritorna dict con 'errore', 'valido', 'score', 'verdetto', 'n_attese',
    'n_effettive', 'copertura_pct', 'n_mancanti', 'n_duplicati', 'n_nan',
    'non_ordinato', 'n_episodi_piatti', 'n_outlier', 'n_negativi',
    'df_problemi' (Tipo, Inizio, Fine, Ore, Dettaglio), 'df_mensile'
    (Mese, Attese, Effettive, Copertura %), 'df_outlier' (Timestamp,
    Prezzo, z-score).
    """
    colonne_prob = ["Tipo", "Inizio", "Fine", "Ore", "Dettaglio"]
    col_mese = ["Mese", "Attese", "Effettive", "Copertura %"]
    col_out = ["Timestamp", "Prezzo (\u20ac/MWh)", "z-score"]
    vuoto = {"errore": None, "valido": False, "score": None,
             "verdetto": None, "n_attese": 0, "n_effettive": 0,
             "copertura_pct": None, "n_mancanti": 0, "n_duplicati": 0,
             "n_nan": 0, "non_ordinato": False, "n_episodi_piatti": 0,
             "n_outlier": 0, "n_negativi": 0,
             "df_problemi": pd.DataFrame(columns=colonne_prob),
             "df_mensile": pd.DataFrame(columns=col_mese),
             "df_outlier": pd.DataFrame(columns=col_out)}

    def _err(msg):
        out = dict(vuoto)
        out["df_problemi"] = pd.DataFrame(columns=colonne_prob)
        out["df_mensile"] = pd.DataFrame(columns=col_mese)
        out["df_outlier"] = pd.DataFrame(columns=col_out)
        out["errore"] = msg
        return out

    try:
        soglia_z = float(soglia_z)
        run_piatta_ore = int(run_piatta_ore)
    except (TypeError, ValueError):
        return _err("Parametri non validi: soglia_z e run_piatta_ore "
                    "devono essere numerici.")
    if soglia_z <= 0 or run_piatta_ore < 2:
        return _err("Parametri non validi: soglia_z > 0 e "
                    "run_piatta_ore >= 2.")

    if prezzi is None or len(prezzi) == 0:
        return _err("Serie prezzi vuota: niente da analizzare.")
    try:
        p = pd.Series(prezzi)
    except Exception:
        return _err("Input non interpretabile come serie di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("L'indice della serie deve essere di tipo data/ora.")
    vals = pd.to_numeric(p.values, errors="coerce")
    if np.isnan(vals).all():
        return _err("Nessun valore numerico nella serie prezzi.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    s = pd.Series(vals, index=idx)

    non_ordinato = not s.index.is_monotonic_increasing
    if non_ordinato:
        s = s.sort_index()

    n_nan = int(s.isna().sum())
    ts_dup = sorted(set(s.index[s.index.duplicated(keep=False)]))
    n_duplicati = len(ts_dup)

    atteso = pd.date_range(s.index.min(), s.index.max(), freq="h")
    presenti = set(s.index)
    mancanti = [t for t in atteso if t not in presenti]
    n_mancanti = len(mancanti)

    problemi = []
    if mancanti:
        ini = prec = mancanti[0]
        coda = mancanti[1:] + [None]
        for t in coda:
            if t is None or t != prec + pd.Timedelta(hours=1):
                n_ore = int((prec - ini).total_seconds() // 3600) + 1
                problemi.append(("Ore mancanti", ini, prec, n_ore,
                                 f"{n_ore} ore consecutive senza dato"))
                if t is None:
                    break
                ini = t
            prec = t
    for t in ts_dup:
        problemi.append(("Timestamp duplicato", t, t, 1,
                         "stesso timestamp piu' volte (es. ora ambigua "
                         "del cambio DST)"))

    sv = s.dropna()
    n_episodi_piatti = 0
    if len(sv) >= run_piatta_ore:
        grp = (sv != sv.shift()).cumsum()
        for _, g in sv.groupby(grp):
            if len(g) >= run_piatta_ore:
                n_episodi_piatti += 1
                problemi.append(("Valore congelato", g.index[0],
                                 g.index[-1], len(g),
                                 f"{g.iloc[0]:,.2f} \u20ac/MWh invariato "
                                 f"per {len(g)} ore"))

    n_outlier = 0
    df_out = pd.DataFrame(columns=col_out)
    svu = sv[~sv.index.duplicated(keep="first")]
    if len(svu) >= 4:
        med = float(svu.median())
        mad = float((svu - med).abs().median())
        if mad > 0:
            z = (svu - med).abs() / (1.4826 * mad)
            zo = z[z > soglia_z].sort_values(ascending=False)
            n_outlier = len(zo)
            if n_outlier:
                df_out = pd.DataFrame({
                    "Timestamp": list(zo.index),
                    "Prezzo (\u20ac/MWh)": [float(svu.loc[t])
                                            for t in zo.index],
                    "z-score": [round(float(v), 2) for v in zo.values],
                }).head(50)

    n_negativi = int((sv < 0).sum())

    validi = set(sv.index) & set(atteso)
    n_attese = len(atteso)
    n_effettive = len(validi)
    copertura_pct = round(100.0 * n_effettive / n_attese, 2) \
        if n_attese else None

    righe_mese = []
    if n_attese:
        att_m = pd.Series(1, index=atteso).resample("MS").sum()
        eff_m = pd.Series(1,
                          index=pd.DatetimeIndex(sorted(validi))).resample(
                              "MS").sum() if validi else pd.Series(
                                  dtype=float)
        for mese in att_m.index:
            a = int(att_m.loc[mese])
            e = int(eff_m.loc[mese]) if mese in eff_m.index else 0
            righe_mese.append({"Mese": mese.strftime("%Y-%m"),
                               "Attese": a, "Effettive": e,
                               "Copertura %": round(100.0 * e / a, 2)
                               if a else None})
    df_mensile = pd.DataFrame(righe_mese, columns=col_mese)

    pct_manc = 100.0 * n_mancanti / n_attese if n_attese else 0.0
    pct_nan = 100.0 * n_nan / len(s) if len(s) else 0.0
    penalita = (min(30.0, 2.0 * pct_manc)
                + (10.0 if n_duplicati else 0.0)
                + min(15.0, pct_nan)
                + min(15.0, 3.0 * n_episodi_piatti)
                + min(10.0, float(n_outlier)))
    score = round(max(0.0, 100.0 - penalita), 1)
    if score >= 90:
        verdetto = "\U0001f7e2 ottima"
    elif score >= 70:
        verdetto = "\U0001f7e1 accettabile"
    else:
        verdetto = "\U0001f534 critica"

    df_problemi = pd.DataFrame(problemi, columns=colonne_prob)
    if not df_problemi.empty:
        df_problemi = df_problemi.sort_values("Inizio").reset_index(
            drop=True)

    out = dict(vuoto)
    out.update({"valido": True, "score": score, "verdetto": verdetto,
                "n_attese": n_attese, "n_effettive": n_effettive,
                "copertura_pct": copertura_pct, "n_mancanti": n_mancanti,
                "n_duplicati": n_duplicati, "n_nan": n_nan,
                "non_ordinato": bool(non_ordinato),
                "n_episodi_piatti": n_episodi_piatti,
                "n_outlier": n_outlier, "n_negativi": n_negativi,
                "df_problemi": df_problemi, "df_mensile": df_mensile,
                "df_outlier": df_out})
    return out


def calcola_beta_gas_power(prezzi_orari, prezzi_gas, profilo="base", finestra=90, min_giorni=30):
    """Beta cross-commodity dello spot elettrico sul gas TTF (OLS giornaliera).

    Domanda operativa: "quando il TTF si muove di 1 €/MWh, di quanto si muove
    mediamente lo spot elettrico?" — la beta e' l'hedge ratio gas-to-power per
    coprire l'esposizione elettrica con future sul gas.

    - prezzi_orari: Series oraria dei prezzi elettrici (€/MWh, indice datetime;
      tz-aware reso naive come negli altri tab);
    - prezzi_gas: Series GIORNALIERA del prezzo gas (€/MWh termico, indice
      datetime);
    - profilo: "base" (media 0-23 di tutti i giorni) o "peak" (media ore 8-20
      dei soli giorni lun-ven);
    - finestra: ampiezza (giorni) della beta rolling; min_giorni: osservazioni
      minime per stimare la regressione.

    Regressione OLS in forma chiusa: power_giorno = alpha + beta * gas_giorno
    (nessuna dipendenza esterna). Ritorna dict con 'errore', 'valido', 'beta',
    'alpha', 'r2', 'correlazione', 'n_giorni', 'std_residui', 'gas_medio',
    'power_medio', 'df_rolling' (Fine finestra, Beta, R²), 'df_scatter'
    (Giorno, Gas (€/MWh), Power (€/MWh)), 'df_scenari' (Variazione gas,
    Gas (€/MWh), Δ prezzo (€/MWh), Prezzo atteso (€/MWh)).

    NaN-safe: serie vuote, indici non-datetime, gas costante (varianza nulla),
    giorni comuni < min_giorni -> errore pulito, mai eccezioni.
    """
    col_roll = ["Fine finestra", "Beta", "R²"]
    col_sc = ["Giorno", "Gas (€/MWh)", "Power (€/MWh)"]
    col_scen = ["Variazione gas", "Gas (€/MWh)", "Δ prezzo (€/MWh)",
                "Prezzo atteso (€/MWh)"]
    vuoto = {"errore": None, "valido": False, "beta": None, "alpha": None,
             "r2": None, "correlazione": None, "n_giorni": 0,
             "std_residui": None, "gas_medio": None, "power_medio": None,
             "df_rolling": pd.DataFrame(columns=col_roll),
             "df_scatter": pd.DataFrame(columns=col_sc),
             "df_scenari": pd.DataFrame(columns=col_scen)}

    def _err(msg):
        out = dict(vuoto)
        out["df_rolling"] = pd.DataFrame(columns=col_roll)
        out["df_scatter"] = pd.DataFrame(columns=col_sc)
        out["df_scenari"] = pd.DataFrame(columns=col_scen)
        out["errore"] = msg
        return out

    try:
        finestra = int(finestra)
        min_giorni = int(min_giorni)
    except (TypeError, ValueError):
        return _err("Parametri non validi: finestra e min_giorni devono essere interi.")
    if min_giorni < 10 or finestra < min_giorni:
        return _err("Parametri non validi: servono min_giorni >= 10 e finestra >= min_giorni.")
    if profilo not in ("base", "peak"):
        return _err("Profilo non valido: 'base' o 'peak'.")

    if prezzi_orari is None or len(prezzi_orari) == 0:
        return _err("Serie prezzi elettrici vuota.")
    if prezzi_gas is None or len(prezzi_gas) == 0:
        return _err("Serie prezzi gas vuota.")
    try:
        p = pd.Series(prezzi_orari)
        g = pd.Series(prezzi_gas)
    except Exception:
        return _err("Input non interpretabili come serie.")
    if not isinstance(p.index, pd.DatetimeIndex) or not isinstance(g.index, pd.DatetimeIndex):
        return _err("Gli indici di entrambe le serie devono essere di tipo data/ora.")
    pv = pd.to_numeric(p.values, errors="coerce")
    gv = pd.to_numeric(g.values, errors="coerce")
    if np.isnan(pv).all():
        return _err("Nessun valore numerico nella serie elettrica.")
    if np.isnan(gv).all():
        return _err("Nessun valore numerico nella serie gas.")
    idx_p = p.index.tz_localize(None) if p.index.tz is not None else p.index
    idx_g = g.index.tz_localize(None) if g.index.tz is not None else g.index
    s_p = pd.Series(pv, index=idx_p).dropna()
    s_g = pd.Series(gv, index=idx_g).dropna()
    if s_p.empty or s_g.empty:
        return _err("Serie vuote dopo la pulizia dei NaN.")

    ore = s_p.index.hour
    giorni = s_p.index.normalize()
    if profilo == "base":
        power_d = s_p.groupby(giorni).mean()
    else:
        dow = s_p.index.dayofweek
        mask_peak = (ore >= 8) & (ore < 20) & (dow < 5)
        if not bool(mask_peak.any()):
            return _err("Nessuna ora peak (lun-ven 8-20) nella serie elettrica.")
        power_d = s_p[mask_peak].groupby(giorni[mask_peak]).mean()
    gas_d = s_g.groupby(s_g.index.normalize()).mean()
    df = pd.DataFrame({"gas": gas_d, "power": power_d}).dropna()
    if len(df) < min_giorni:
        return _err(f"Dati insufficienti: {len(df)} giorni comuni, servono almeno {min_giorni}.")
    if float(df["gas"].var()) <= 0:
        return _err("Prezzo gas costante sul periodo: regressione impossibile.")

    x = df["gas"].to_numpy()
    y = df["power"].to_numpy()

    def _ols(xx, yy):
        if len(xx) < 2 or float(np.var(xx)) <= 0:
            return None
        b = float(np.cov(xx, yy, ddof=0)[0, 1] / np.var(xx))
        a = float(np.mean(yy) - b * np.mean(xx))
        corr = float(np.corrcoef(xx, yy)[0, 1])
        return b, a, corr, corr * corr

    full = _ols(x, y)
    if full is None:
        return _err("Regressione impossibile sui dati disponibili.")
    beta, alpha, corr, r2 = full
    std_res = float(np.std(y - (alpha + beta * x)))
    gas_ref = float(x.mean())
    power_ref = float(y.mean())

    righe = []
    for i in range(min_giorni, len(df) + 1):
        sub = df.iloc[max(0, i - finestra):i]
        r = _ols(sub["gas"].to_numpy(), sub["power"].to_numpy())
        righe.append({"Fine finestra": df.index[i - 1].date(),
                      "Beta": round(r[0], 3) if r else None,
                      "R²": round(r[3], 3) if r else None})
    df_roll = pd.DataFrame(righe, columns=col_roll)

    df_sc = pd.DataFrame({"Giorno": df.index.date,
                          "Gas (€/MWh)": np.round(x, 2),
                          "Power (€/MWh)": np.round(y, 2)})

    scen = []
    for pct in (-30, -20, -10, 10, 20, 30):
        gas_sc = gas_ref * (1 + pct / 100.0)
        d_prezzo = beta * (gas_sc - gas_ref)
        scen.append({"Variazione gas": f"{pct:+d} %",
                     "Gas (€/MWh)": round(gas_sc, 2),
                     "Δ prezzo (€/MWh)": round(d_prezzo, 2),
                     "Prezzo atteso (€/MWh)": round(power_ref + d_prezzo, 2)})
    df_scen = pd.DataFrame(scen, columns=col_scen)

    return {"errore": None, "valido": True, "beta": beta, "alpha": alpha,
            "r2": r2, "correlazione": corr, "n_giorni": len(df),
            "std_residui": std_res, "gas_medio": gas_ref,
            "power_medio": power_ref, "df_rolling": df_roll,
            "df_scatter": df_sc, "df_scenari": df_scen}


def calcola_volatilita_termine(prezzi_orari, bucket="mese", min_giorni=10, min_bucket=2):
    """Struttura a termine della volatilita' realizzata dello spot (€/MWh).

    prezzi_orari: Series oraria in €/MWh. Gli spot possono essere 0 o negativi,
    quindi si lavora sulle VARIAZIONI GIORNALIERE del prezzo medio (€/MWh),
    non sui log-return (stessa convenzione del tab Volatilita').
    Metodo: media per giorno solare -> variazioni giornaliere -> per ogni bucket
    di consegna (mese di calendario o trimestre) vol annua = std(ddof=1) delle
    variazioni x sqrt(252). Slope = regressione OLS in forma chiusa della vol
    sui bucket in ordine cronologico (€/MWh per bucket): slope < 0 =
    backwardation della vol (stress concentrato a breve termine), slope > 0 =
    contango (incertezza che cresce a termine).
    A cosa serve: input n.1 per prezzare le opzioni (tab structuring) e per
    scegliere le scadenze delle coperture — mesi ad alta vol storica hanno
    premi attesi piu' alti.
    NaN-safe: serie vuota / indice non-datetime / variazioni insufficienti ->
    errore pulito; bucket con < min_giorni giorni saltato (n_esclusi);
    prezzi costanti -> vol 0, valido.
    Ritorna dict con errore/valido/bucket/tabella/front/media/slope/
    slope_rel/bucket_max/bucket_min/rapporto/verdetto/serie_variazioni.
    """
    cols = ["Bucket", "Giorni", "Prezzo medio (€/MWh)", "Vol annua (€/MWh)",
            "Vol annua (% prezzo)"]
    vuoto = pd.DataFrame({c: [] for c in cols})

    def _err(msg):
        return {"errore": msg, "valido": False, "bucket": str(bucket),
                "tabella": vuoto, "n_bucket": 0, "n_esclusi": 0,
                "giorni_totali": 0, "front": None, "media": None,
                "slope": None, "slope_rel": None, "bucket_max": None,
                "bucket_min": None, "rapporto": None, "verdetto": msg,
                "serie_variazioni": pd.Series(dtype=float)}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        min_giorni = int(min_giorni)
        min_bucket = int(min_bucket)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: controlla gli input.")
    if min_giorni < 2:
        return _err("min_giorni deve essere almeno 2.")
    if min_bucket < 2:
        return _err("min_bucket deve essere almeno 2.")
    freq = {"mese": "M", "month": "M", "trimestre": "Q",
            "quarter": "Q"}.get(str(bucket).strip().lower())
    if freq is None:
        return _err("bucket non valido: usa 'mese' o 'trimestre'.")

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 48:
        return _err("Serie troppo corta: servono almeno 48 ore di prezzi.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    giornaliera = p.groupby(idxn.date).mean()
    if len(giornaliera) < 3:
        return _err("Servono almeno 3 giorni di prezzi per le variazioni.")
    var = giornaliera.diff().dropna()
    per_g = pd.DatetimeIndex(pd.to_datetime(giornaliera.index)).to_period(freq)
    per_v = pd.DatetimeIndex(pd.to_datetime(var.index)).to_period(freq)

    righe, esclusi = [], 0
    for per in sorted(set(per_v)):
        mg = per_g == per
        mv = per_v == per
        gg = int(mg.sum())
        chg = var.iloc[mv].dropna()
        if gg < min_giorni or len(chg) < 2:
            esclusi += 1
            continue
        v = float(chg.std(ddof=1)) * (252.0 ** 0.5)
        pm = float(giornaliera.iloc[mg].mean())
        vpct = (v / abs(pm) * 100.0) if pm != 0 else float("nan")
        righe.append({"Bucket": str(per), "Giorni": gg,
                      "Prezzo medio (€/MWh)": round(pm, 2),
                      "Vol annua (€/MWh)": round(v, 2),
                      "Vol annua (% prezzo)": (round(vpct, 1) if vpct == vpct else None),
                      "_vol": v})

    if not righe:
        return _err(f"Nessun bucket con almeno {min_giorni} giorni: "
                    "serie troppo corta o parametro troppo alto.")

    vols = np.array([r["_vol"] for r in righe])
    media = float(vols.mean())
    slope = None
    if len(vols) >= min_bucket:
        x = np.arange(len(vols), dtype=float)
        vx = float(np.var(x))
        slope = float(np.cov(x, vols, ddof=0)[0, 1] / vx) if vx > 0 else 0.0
    slope_rel = (slope / media) if (slope is not None and media > 0) else None
    imax, imin = int(vols.argmax()), int(vols.argmin())
    rapporto = float(vols[imax] / vols[imin]) if vols[imin] > 0 else None

    if len(righe) < min_bucket:
        valido = False
        verdetto = (f"⚪ Struttura non stimabile: {len(righe)} bucket validi, "
                    f"ne servono almeno {min_bucket} per la pendenza.")
    else:
        valido = True
        thr = 0.05 * media
        if slope < -thr:
            verdetto = ("🔴 Backwardation della vol: lo stress e' concentrato a "
                        "breve termine — opzioni e coperture corte piu' care.")
        elif slope > thr:
            verdetto = ("🟢 Contango della vol: l'incertezza cresce a termine — "
                        "occhio alle scadenze lunghe.")
        else:
            verdetto = "🟡 Struttura piatta: la vol e' simile su tutti i bucket."

    tabella = pd.DataFrame([{k: r[k] for k in cols} for r in righe], columns=cols)
    return {"errore": None, "valido": valido, "bucket": str(bucket),
            "tabella": tabella, "n_bucket": len(righe), "n_esclusi": esclusi,
            "giorni_totali": int(len(giornaliera)), "front": float(vols[0]),
            "media": media, "slope": slope, "slope_rel": slope_rel,
            "bucket_max": righe[imax]["Bucket"], "bucket_min": righe[imin]["Bucket"],
            "rapporto": rapporto, "verdetto": verdetto,
            "serie_variazioni": var}


def calcola_indice_stress(prezzi_orari, soglia=70.0, pesi=None):
    """Indice di stress di mercato giornaliero (0-100): un numero unico che
    dice quanto il mercato e' sotto stress ogni giorno.

    4 componenti, normalizzate min-max sul periodo analizzato (0 = minimo
    osservato, 1 = massimo osservato), poi media pesata x 100:
      1. Livello prezzo    — media giornaliera (prezzi alti = stress), w 0.35
      2. Range intraday    — (max-min)/|media|, con pavimento a 5 €/MWh per
         non far esplodere il rapporto quando la media e' ~0, w 0.25
      3. Shock giornaliero — |variazione della media vs giorno prima|, w 0.25
      4. Ore negative      — quota di ore con prezzo < 0 (stress da eccesso
         di rinnovabili / domanda debole), w 0.15
    Classi: SSI < 30 calmo, < 50 tensionato, < 70 stressato, >= 70 crisi.
    A cosa serve: termometro unico per il TEMPO delle coperture (SSI alto =
    si fissa prima, si paga volentieri il premio delle opzioni), storicizza le
    crisi per confrontare "quanto e' grave oggi" col passato; le componenti
    spiegano sempre il perche' del punteggio, niente black box.
    NaN-safe: serie vuota / indice non-datetime / < 72 ore -> errore pulito;
    prezzi costanti -> tutte le componenti a 0 -> SSI 0 (calmo); tz-aware reso
    naive; soglia fuori 0-100 o pesi non validi -> errore.
    Ritorna dict con errore/valido/serie/tabella/ultimo/medio/massimo/
    sopra_soglia/pct_crisi/n_giorni/mensile/pesi/verdetto.
    """
    PESI_DEF = (0.35, 0.25, 0.25, 0.15)
    COLS_PT = ["Livello prezzo (pt)", "Range intraday (pt)",
               "Shock giornaliero (pt)", "Ore negative (pt)"]

    def _vuoto():
        return pd.DataFrame({"Data": [], "SSI": [], "Classe": [],
                             **{c: [] for c in COLS_PT}})

    def _err(msg):
        return {"errore": msg, "valido": False, "serie": _vuoto(),
                "tabella": _vuoto(), "ultimo": None, "medio": None,
                "massimo": None, "sopra_soglia": 0, "pct_crisi": 0.0,
                "n_giorni": 0,
                "mensile": pd.DataFrame({"Mese": [], "SSI medio": []}),
                "pesi": PESI_DEF, "verdetto": msg}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        soglia = float(soglia)
    except (TypeError, ValueError):
        return _err("soglia non numerica: usa un valore 0-100.")
    if not (0.0 <= soglia <= 100.0):
        return _err("soglia fuori range: usa un valore 0-100.")
    if pesi is None:
        w = PESI_DEF
    else:
        try:
            w = tuple(float(x) for x in pesi)
        except (TypeError, ValueError):
            return _err("pesi non numerici: servono 4 valori >= 0.")
        if len(w) != 4 or any(x < 0 for x in w) or sum(w) <= 0:
            return _err("pesi non validi: servono 4 valori >= 0 con somma > 0.")
        tot = sum(w)
        w = tuple(x / tot for x in w)

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 72:
        return _err("Serie troppo corta: servono almeno 72 ore di prezzi.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    giorni = idxn.date
    g = p.groupby(giorni)
    media = g.mean()
    rng = (g.max() - g.min()) / media.abs().clip(lower=5.0)
    shock = media.diff().abs().fillna(0.0)
    neg = (p < 0).groupby(giorni).mean()

    def _mm(s):
        lo, hi = float(s.min()), float(s.max())
        if hi > lo:
            return (s - lo) / (hi - lo)
        return pd.Series(0.0, index=s.index)

    comp = pd.DataFrame({"Livello prezzo": _mm(media),
                         "Range intraday": _mm(rng),
                         "Shock giornaliero": _mm(shock),
                         "Ore negative": _mm(neg)})
    pts = comp.mul(w, axis=1) * 100.0
    ssi = pts.sum(axis=1).round(1)

    def _classe(v):
        if v < 30.0:
            return "🟢 Calmo"
        if v < 50.0:
            return "🟡 Tensionato"
        if v < 70.0:
            return "🟠 Stressato"
        return "🔴 Crisi"

    classi = [_classe(v) for v in ssi.to_numpy()]
    serie = pd.DataFrame({"Data": pd.to_datetime(ssi.index),
                          "SSI": ssi.to_numpy(), "Classe": classi})
    for i, c in enumerate(COLS_PT):
        serie[c] = pts.iloc[:, i].to_numpy().round(1)

    tabella = serie.sort_values("SSI", ascending=False).head(20).reset_index(drop=True)
    mens = serie.groupby(serie["Data"].dt.to_period("M"))["SSI"].mean().round(1)
    mensile = pd.DataFrame({"Mese": [str(m) for m in mens.index],
                            "SSI medio": mens.to_numpy()})

    ultimo_ssi = float(ssi.iloc[-1])
    ultimo_data = str(ssi.index[-1])
    massimo_idx = int(ssi.to_numpy().argmax())
    sopra = int((ssi.to_numpy() >= soglia).sum())
    crisi = float(np.mean([c == "🔴 Crisi" for c in classi])) * 100.0

    if ultimo_ssi >= soglia:
        verdetto = (f"🚨 Mercato in tensione l'ultimo giorno ({ultimo_data}): "
                    f"SSI {ultimo_ssi:.1f} sopra la soglia {soglia:.0f}.")
    else:
        verdetto = (f"Mercato sotto controllo l'ultimo giorno ({ultimo_data}): "
                    f"SSI {ultimo_ssi:.1f} sotto la soglia {soglia:.0f}.")

    return {"errore": None, "valido": True, "serie": serie, "tabella": tabella,
            "ultimo": {"data": ultimo_data, "ssi": ultimo_ssi,
                       "classe": _classe(ultimo_ssi)},
            "medio": float(ssi.mean()),
            "massimo": {"data": str(ssi.index[massimo_idx]),
                        "valore": float(ssi.iloc[massimo_idx])},
            "sopra_soglia": sopra, "pct_crisi": round(crisi, 1),
            "n_giorni": int(len(ssi)), "mensile": mensile, "pesi": w,
            "verdetto": verdetto}


def _fascia_aeegsi(h, wd):
    """Fascia AEEGSI F1/F2/F3 da ora (0-23) e weekday (0=lun..6=dom)."""
    if wd == 6:
        return "F3"
    if wd == 5:
        return "F2" if 7 <= h < 23 else "F3"
    if 8 <= h < 19:
        return "F1"
    if (7 <= h < 8) or (19 <= h < 23):
        return "F2"
    return "F3"


def _stat_circolari(ore, pesi):
    """Media e dispersione circolari su 24h. Ritorna (baricentro_ore, dispersione_ore, quota_centro_pct)."""
    theta = 2.0 * np.pi * np.asarray(ore, dtype=float) / 24.0
    w = np.asarray(pesi, dtype=float)
    sw = float(w.sum())
    if sw <= 0.0:
        return None, None, None
    s = float((w * np.sin(theta)).sum())
    c = float((w * np.cos(theta)).sum())
    ang = np.arctan2(s, c)
    bary = float((ang / (2.0 * np.pi) * 24.0) % 24.0)
    rl = float(np.hypot(s, c) / sw)  # lunghezza risultante 0..1
    disp = float(np.sqrt(max(0.0, -2.0 * np.log(min(rl, 1.0)))) * 24.0 / (2.0 * np.pi)) if rl > 0 else None
    d = np.minimum(np.abs(np.asarray(ore, dtype=float) - bary), 24.0 - np.abs(np.asarray(ore, dtype=float) - bary))
    quota = float(w[d <= 2.0].sum() / sw * 100.0)
    return bary, disp, quota


def calcola_baricentro_costo(prezzi, mw_f1, mw_f2, mw_f3):
    """Baricentro del costo: l'ora del giorno in cui si concentra la spesa.

    Il costo orario e' prezzo spot x MW della fascia F1/F2/F3 (stessa logica
    della tab Top ore di costo). Il baricentro e' la media ponderata
    CIRCOLARE delle ore 0-23 (pesi = costi orari non negativi): con una media
    aritmetica banale le ore 0 e 23 falserebbero il risultato, con quella
    circolare no. La dispersione e' la deviazione standard circolare in ore;
    la quota entro ±2h dice quanta spesa sta davvero vicino al baricentro.

    Differenza dagli altri tab: Top ore di costo classifica le ore piu' care
    GIA' accadute (le prime 10 possono cadere tutte nello stesso giorno);
    Ora di punta prende l'ora piu' costosa di OGNI giorno; qui la domanda e'
    'attorno a che ora ruota mediamente la mia bolletta?' — un unico numero
    (es. 17:36) + dispersione, utile per la demand response ricorrente e per
    verificare se il profilo si e' spostato (baricentro mensile).

    Le ore con costo negativo (prezzi negativi) sono escluse dai pesi e
    conteggiate a parte; se il costo totale non positivo non si calcola nulla.

    NaN-safe: serie vuota / indice non datetime / tutti i MW a zero / nessun
    costo positivo -> errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'mwh_tot', 'costo_tot',
    'baricentro_ore', 'baricentro_txt' ('HH:MM'), 'dispersione_ore',
    'quota_centro_pct' (quota di costo entro ±2h dal baricentro),
    'ore_negative' / 'quota_neg_pct' (ore a costo negativo escluse dai pesi),
    'per_ora' (DataFrame 24 righe: Ora, Ore osservate, Costo (€), Quota %) e
    'mensile' (DataFrame: Mese, Baricentro, Dispersione (±h), Quota ±2h (%), Costo (€))."""
    cols_o = ["Ora", "Ore osservate", "Costo (€)", "Quota %"]
    cols_m = ["Mese", "Baricentro", "Dispersione (±h)", "Quota ±2h (%)", "Costo (€)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "mwh_tot": 0.0, "costo_tot": None,
             "baricentro_ore": None, "baricentro_txt": None,
             "dispersione_ore": None, "quota_centro_pct": None,
             "ore_negative": 0, "quota_neg_pct": 0.0,
             "per_ora": pd.DataFrame(columns=cols_o),
             "mensile": pd.DataFrame(columns=cols_m)}
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return dict(vuoto)
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        out = dict(vuoto)
        out["errore"] = "Imposta una potenza maggiore di zero in almeno una fascia."
        return out
    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])
    costo = p.to_numpy(dtype=float) * mw
    w = np.maximum(costo, 0.0)
    if w.sum() <= 0.0:
        out = dict(vuoto)
        out["errore"] = "Costo totale non positivo: baricentro non calcolabile."
        return out
    bary, disp, quota_c = _stat_circolari(ore, w)
    n_ore = len(p)
    costo_tot = float(costo.sum())
    mwh_tot = float(mw.sum())
    neg = int((costo < 0.0).sum())
    ore_24, costo_24, n_24 = np.arange(24), np.zeros(24), np.zeros(24, dtype=int)
    for h in range(24):
        m = ore == h
        n_24[h] = int(m.sum())
        costo_24[h] = float(costo[m].sum())
    q24 = np.where(costo_tot > 0, np.maximum(costo_24, 0.0) / max(w.sum(), 1e-12) * 100.0, 0.0)
    per_ora = pd.DataFrame({"Ora": [f"{h:02d}:00" for h in ore_24],
                            "Ore osservate": n_24,
                            "Costo (€)": np.round(costo_24, 2),
                            "Quota %": np.round(q24, 2)})
    righe = []
    mesi = (p.index.tz_localize(None) if p.index.tz is not None else p.index).to_period("M")
    for mese, grp in pd.DataFrame({"c": costo, "o": ore}).groupby(mesi):
        cm, om = grp["c"].to_numpy(), grp["o"].to_numpy()
        wm = np.maximum(cm, 0.0)
        if wm.sum() <= 0.0:
            continue
        bm, dm, qm = _stat_circolari(om, wm)
        righe.append({"Mese": str(mese), "Baricentro": f"{int(bm):02d}:{int(round((bm % 1) * 60)):02d}",
                      "Dispersione (±h)": round(dm, 1) if dm is not None else None,
                      "Quota ±2h (%)": round(qm, 1), "Costo (€)": round(float(cm.sum()), 0)})
    bh = int(bary)
    bt = f"{bh:02d}:{int(round((bary - bh) * 60)):02d}"
    return {"errore": None, "valido": True, "n_ore": n_ore, "mwh_tot": mwh_tot,
            "costo_tot": costo_tot, "baricentro_ore": bary, "baricentro_txt": bt,
            "dispersione_ore": disp, "quota_centro_pct": quota_c,
            "ore_negative": neg, "quota_neg_pct": round(neg / n_ore * 100.0, 1),
            "per_ora": per_ora, "mensile": pd.DataFrame(righe, columns=cols_m)}


def calcola_penalita_reattiva(prezzi, mw_f1, mw_f2, mw_f3, cos_phi,
                            tariffa_t1=0.008, tariffa_t2=0.012,
                            soglia_t1=0.33, soglia_t2=0.75, cos_phi_obiettivo=0.95):
    """Penale per energia reattiva: quanto ti costa il basso fattore di potenza.

    Domanda operativa: 'quanto pago di penali per l'energia reattiva
    (kvarh) e quanto risparmierei rifasando a 0.95?'

    Logica: dalla potenza attiva oraria (MW della fascia F1/F2/F3, stessa
    logica della tab Baricentro del costo) e dal cos(phi) dichiarato si
    ricava l'energia reattiva oraria: Er = Ea * tan(acos(cos_phi)).
    Aggregazione mensile e penali a due scaglioni stile ARERA (soglie e
    tariffe configurabili perche' cambiano per livello di tensione e anno):
      - scaglione 1: reattiva oltre soglia_t1 (default 33%) e fino a
        soglia_t2 (default 75%) dell'attiva -> tariffa_t1 €/kvarh;
      - scaglione 2: reattiva oltre soglia_t2 dell'attiva -> tariffa_t2 €/kvarh.
    In piu' il 'risparmio rifasamento': penale ricalcolata con
    cos_phi_obiettivo (default 0.95) sullo stesso profilo.

    Differenza dagli altri tab: stima bolletta e riconciliazione fattura
    valorizzano la componente ENERGIA a spot; qui si misura una voce di
    costo INDIPENDENTE dal prezzo (dipende solo dal profilo e dal cos phi),
    che per un'utenza industriale mal rifasata puo' valere migliaia di euro
    l'anno e si elimina con un rifasatore da qualche centinaio di euro.

    NaN-safe: serie vuota / indice non datetime / tutti i MW a zero /
    cos_phi fuori (0, 1) -> errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'mwh_tot', 'kvarh_tot',
    'rapporto_medio_pct' (reattiva/attiva pesata sul periodo),
    'penale_tot' (€), 'penale_rifasata' (€ con cos_phi_obiettivo),
    'risparmio_rifasamento' (€), 'mesi_con_penale' (int), 'peggior_mese'
    (str 'YYYY-MM'), 'penale_peggiore' (€), 'tan_phi', 'tan_phi_obiettivo' e
    'mensile' (DataFrame: Mese, Attiva (kWh), Reattiva (kvarh),
    Rapporto %, Eccedenza t1 (kvarh), Eccedenza t2 (kvarh), Penale (€))."""
    cols_m = ["Mese", "Attiva (kWh)", "Reattiva (kvarh)", "Rapporto %",
              "Eccedenza t1 (kvarh)", "Eccedenza t2 (kvarh)", "Penale (€)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "mwh_tot": 0.0, "kvarh_tot": 0.0,
             "rapporto_medio_pct": None, "penale_tot": 0.0,
             "penale_rifasata": 0.0, "risparmio_rifasamento": 0.0,
             "mesi_con_penale": 0, "peggior_mese": None, "penale_peggiore": 0.0,
             "tan_phi": None, "tan_phi_obiettivo": None,
             "mensile": pd.DataFrame(columns=cols_m)}
    try:
        cp = float(cos_phi)
    except Exception:
        cp = float("nan")
    if not (0.0 < cp < 1.0):
        out = dict(vuoto)
        out["errore"] = "Il cos(phi) deve essere compreso tra 0 e 1 (esclusi)."
        return out
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return dict(vuoto)
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return dict(vuoto)
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        out = dict(vuoto)
        out["errore"] = "Imposta una potenza maggiore di zero in almeno una fascia."
        return out
    t1 = max(0.0, float(tariffa_t1 or 0.0))
    t2 = max(0.0, float(tariffa_t2 or 0.0))
    s1 = min(max(0.0, float(soglia_t1 or 0.0)), 5.0)
    s2 = min(max(0.0, float(soglia_t2 or 0.0)), 5.0)
    if s2 < s1:
        s1, s2 = s2, s1
    try:
        co = float(cos_phi_obiettivo)
    except Exception:
        co = 0.95
    co = min(max(co, 0.01), 0.9999)
    tan_phi = float(np.tan(np.arccos(cp)))
    tan_ob = float(np.tan(np.arccos(co)))
    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])
    ea_oraria = mw * 1000.0          # kWh per ora
    er_oraria = ea_oraria * tan_phi  # kvarh per ora
    mesi = (p.index.tz_localize(None) if p.index.tz is not None else p.index).to_period("M")

    def _penale_mese(ea, er):
        if ea <= 0.0 or er <= 0.0:
            return 0.0, 0.0, 0.0
        ecc2 = max(0.0, er - s2 * ea)
        ecc1 = max(0.0, min(er, s2 * ea) - s1 * ea)
        return ecc1, ecc2, ecc1 * t1 + ecc2 * t2

    righe = []
    for mese, idx in pd.DataFrame({"ea": ea_oraria, "er": er_oraria}).groupby(mesi).groups.items():
        g = pd.DataFrame({"ea": ea_oraria, "er": er_oraria}).iloc[idx]
        ea_m, er_m = float(g["ea"].sum()), float(g["er"].sum())
        ecc1, ecc2, pen = _penale_mese(ea_m, er_m)
        righe.append({"Mese": str(mese), "Attiva (kWh)": round(ea_m, 0),
                      "Reattiva (kvarh)": round(er_m, 0),
                      "Rapporto %": round(er_m / ea_m * 100.0, 1) if ea_m > 0 else 0.0,
                      "Eccedenza t1 (kvarh)": round(ecc1, 0),
                      "Eccedenza t2 (kvarh)": round(ecc2, 0),
                      "Penale (€)": round(pen, 2)})
    mensile = pd.DataFrame(righe, columns=cols_m)
    ea_tot, er_tot = float(ea_oraria.sum()), float(er_oraria.sum())
    penale_tot = float(mensile["Penale (€)"].sum()) if len(mensile) else 0.0
    # scenario rifasamento: stessa attiva, reattiva ridotta a tan(phi_obiettivo)
    er_ob = ea_oraria * tan_ob
    pen_ob = 0.0
    for mese, idx in pd.DataFrame({"ea": ea_oraria, "er": er_ob}).groupby(mesi).groups.items():
        g = pd.DataFrame({"ea": ea_oraria, "er": er_ob}).iloc[idx]
        pen_ob += _penale_mese(float(g["ea"].sum()), float(g["er"].sum()))[2]
    mesi_pen = mensile[mensile["Penale (€)"] > 0.0]
    peg_m, peg_v = (None, 0.0)
    if len(mesi_pen):
        riga = mesi_pen.loc[mesi_pen["Penale (€)"].idxmax()]
        peg_m, peg_v = str(riga["Mese"]), float(riga["Penale (€)"])
    return {"errore": None, "valido": True, "n_ore": len(p),
            "mwh_tot": ea_tot / 1000.0, "kvarh_tot": er_tot,
            "rapporto_medio_pct": round(er_tot / ea_tot * 100.0, 1) if ea_tot > 0 else 0.0,
            "penale_tot": round(penale_tot, 2),
            "penale_rifasata": round(pen_ob, 2),
            "risparmio_rifasamento": round(penale_tot - pen_ob, 2),
            "mesi_con_penale": int(len(mesi_pen)),
            "peggior_mese": peg_m, "penale_peggiore": round(peg_v, 2),
            "tan_phi": round(tan_phi, 4), "tan_phi_obiettivo": round(tan_ob, 4),
            "mensile": mensile}


def calcola_efficienza_fixing(prezzi_orari, prezzo_fissato):
    """Efficienza del fixing: quanto e' stato buono il tuo prezzo fissato (€/MWh)
    contro il mercato del periodo.

    Confronta il prezzo medio che hai fissato con la distribuzione dei prezzi
    orari del periodo:
      - % ore battute = quota di ore in cui il mercato e' stato uguale o piu'
        caro del tuo fixing (100% = l'hai sempre battuto);
      - sovracosto vs media di periodo, in €/MWh e in %;
      - distanza dal minimo di periodo (costo opportunita' del timing perfetto)
        e dal massimo di periodo.
    Verdetto per % ore battute: >=90 Eccellente, >=70 Buono, >=50 Nella norma,
    >=30 Caro, <30 Molto caro.
    A cosa serve: valuta ex-post le decisioni di fissazione — un fixing sotto
    la mediana batte il mercato piu' della meta' del tempo; la tabella mensile
    mostra in quali mesi il fixing ha reso di piu' o di meno, utile per il
    debriefing col fornitore.
    NaN-safe: serie vuota / indice non-datetime / < 24 ore / prezzo fissato
    non numerico o <= 0 -> errore pulito; tz-aware reso naive.
    Ritorna dict con errore/valido/prezzo_fissato/media/mediana/p10/p25/p50/
    p75/p90/min/max/n_ore/pct_battuto/sovracosto_eur/sovracosto_pct/dist_min/
    dist_max/verdetto/mensile.
    """
    def _vuoto_mens():
        return pd.DataFrame({"Mese": [], "Media €/MWh": [],
                             "Scarto vs fixing €/MWh": [],
                             "Ore battute %": []})

    def _err(msg):
        return {"errore": msg, "valido": False, "prezzo_fissato": None,
                "media": None, "mediana": None, "p10": None, "p25": None,
                "p50": None, "p75": None, "p90": None, "min": None,
                "max": None, "n_ore": 0, "pct_battuto": None,
                "sovracosto_eur": None, "sovracosto_pct": None,
                "dist_min": None, "dist_max": None, "verdetto": msg,
                "mensile": _vuoto_mens()}

    if not isinstance(prezzi_orari, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    if not isinstance(prezzi_orari.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    try:
        pf = float(prezzo_fissato)
    except (TypeError, ValueError):
        return _err("Prezzo fissato non numerico: inserisci un valore > 0.")
    if not pf > 0:
        return _err("Prezzo fissato non valido: inserisci un valore > 0.")

    p = pd.to_numeric(prezzi_orari, errors="coerce").dropna()
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    vals = p.to_numpy(dtype=float)
    q = np.percentile(vals, [10, 25, 50, 75, 90])

    media = float(vals.mean())
    pct_batt = float((vals >= pf).mean() * 100.0)
    sovr_eur = pf - media
    sovr_pct = (sovr_eur / media * 100.0) if abs(media) > 1e-9 else 0.0

    if pct_batt >= 90.0:
        verdetto = (f"🏆 Eccellente: hai battuto il mercato nel {pct_batt:.1f}% "
                    "delle ore — fixing quasi perfetto.")
    elif pct_batt >= 70.0:
        verdetto = (f"✅ Buono: hai battuto il mercato nel {pct_batt:.1f}% "
                    "delle ore.")
    elif pct_batt >= 50.0:
        verdetto = (f"➖ Nella norma: hai battuto il mercato nel "
                    f"{pct_batt:.1f}% delle ore.")
    elif pct_batt >= 30.0:
        verdetto = (f"⚠️ Caro: hai battuto il mercato solo nel "
                    f"{pct_batt:.1f}% delle ore.")
    else:
        verdetto = (f"🚨 Molto caro: hai battuto il mercato solo nel "
                    f"{pct_batt:.1f}% delle ore.")

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mesi = idxn.to_period("M")
    gm = p.groupby(mesi)
    mm = gm.mean()
    pbb = gm.apply(lambda s: float((s.to_numpy() >= pf).mean() * 100.0))
    mensile = pd.DataFrame(
        {"Mese": [str(m) for m in mm.index],
         "Media €/MWh": mm.to_numpy().round(2),
         "Scarto vs fixing €/MWh": (mm - pf).to_numpy().round(2),
         "Ore battute %": pbb.to_numpy().round(1)})

    return {"errore": None, "valido": True, "prezzo_fissato": pf,
            "media": round(media, 2), "mediana": round(float(np.median(vals)), 2),
            "p10": round(float(q[0]), 2), "p25": round(float(q[1]), 2),
            "p50": round(float(q[2]), 2), "p75": round(float(q[3]), 2),
            "p90": round(float(q[4]), 2),
            "min": round(float(vals.min()), 2),
            "max": round(float(vals.max()), 2),
            "n_ore": int(len(vals)), "pct_battuto": round(pct_batt, 1),
            "sovracosto_eur": round(sovr_eur, 2),
            "sovracosto_pct": round(sovr_pct, 1),
            "dist_min": round(pf - float(vals.min()), 2),
            "dist_max": round(float(vals.max()) - pf, 2),
            "verdetto": verdetto, "mensile": mensile}


def calcola_ottimizza_potenza(prezzi, mw_f1, mw_f2, mw_f3, p_contr_kw,
                              quota_kw_mese, penale_kw, fattore_picco=1.05):
    """Ottimizzazione della potenza impegnata (potenza contrattuale).

    Il distributore fattura la potenza in due voci: una QUOTA FISSA mensile
    proporzionale alla potenza impegnata (kW contrattuali x quota €/kW/mese)
    e una PENALE quando il picco reale supera la potenza impegnata
    (kW di superamento x penale €/kW, per mese). Troppa potenza impegnata =
    quota fissa sprecata; troppo poca = penali ricorrenti. Questa tab trova
    il punto di equilibrio.

    Il picco mensile e' stimato dal profilo orario MW F1/F2/F3 (stessa
    logica degli altri tab): picco_mese = max(MW orari del mese) x 1000 x
    fattore_picco. Il fattore_picco (default 1.05) approssima il picco
    quarto-orario, che la misura reale usa al posto del picco orario:
    alzalo se il tuo carico ha punte brevi e ripide.

    La scansione prova potenze candidate da 0.5 x picco_max a 1.3 x
    picco_max: per ogni candidata il costo totale = quota fissa + penali
    su tutti i mesi. I candidati includono anche i picchi mensili osservati
    (il costo e' lineare a tratti con spigoli proprio li': l'ottimo cade
    sempre su uno spigolo o su un estremo). Il risparmio annuo e' il
    risparmio sul periodo annualizzato (x 12 / n_mesi).

    NaN-safe: serie vuota / indice non-datetime / < 24 ore / MW tutti a
    zero / potenza contrattuale <= 0 / quota o penale negative /
    fattore_picco <= 0 -> errore pulito; tz-aware reso naive.

    Ritorna dict con errore/valido/n_ore/n_mesi/mwh_tot/picco_max_kw/
    p_contr_kw/potenza_ottima_kw/costo_attuale/costo_ottimo/
    risparmio_periodo/risparmio_annuo/mesi_superamento/categoria/
    verdetto/mensile/scansione.
    """
    cols_m = ["Mese", "Picco (kW)", "Quota fissa (€)", "Penale (€)", "Totale (€)"]
    cols_s = ["Potenza (kW)", "Quota fissa (€)", "Penali (€)", "Totale (€)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi": 0,
                "mwh_tot": 0.0, "picco_max_kw": None, "p_contr_kw": None,
                "potenza_ottima_kw": None, "costo_attuale": None,
                "costo_ottimo": None, "risparmio_periodo": None,
                "risparmio_annuo": None, "mesi_superamento": 0,
                "categoria": None, "verdetto": msg,
                "mensile": pd.DataFrame(columns=cols_m),
                "scansione": pd.DataFrame(columns=cols_s)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        p_contr = float(p_contr_kw)
        quota = float(quota_kw_mese)
        penale = float(penale_kw)
        fp = float(fattore_picco)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: potenza, quota, penale e fattore devono essere numeri.")
    if not p_contr > 0:
        return _err("Potenza contrattuale non valida: inserisci un valore > 0 kW.")
    if quota < 0:
        return _err("Quota potenza non valida: non puo' essere negativa.")
    if penale < 0:
        return _err("Penale di superamento non valida: non puo' essere negativa.")
    if not fp > 0:
        return _err("Fattore di picco non valido: inserisci un valore > 0.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)), "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])  # MW orari del profilo

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mesi = idxn.to_period("M")
    dfm = pd.DataFrame({"mw": mw}, index=idxn)
    picchi = []
    righe = []
    for mese, grp in dfm.groupby(mesi):
        pk = float(grp["mw"].max()) * 1000.0 * fp  # kW
        picchi.append(pk)
        qf = p_contr * quota
        pen = max(0.0, pk - p_contr) * penale
        righe.append({"Mese": str(mese), "Picco (kW)": round(pk, 0),
                      "Quota fissa (€)": round(qf, 2), "Penale (€)": round(pen, 2),
                      "Totale (€)": round(qf + pen, 2)})
    picchi = np.array(picchi)
    n_mesi = len(picchi)
    picco_max = float(picchi.max())

    def _costo_tot(pot):
        qf = pot * quota * n_mesi
        pen = float(np.maximum(0.0, picchi - pot).sum()) * penale
        return qf, pen, qf + pen

    lo, hi = 0.5 * picco_max, 1.3 * picco_max
    candidati = sorted(set([lo, hi, p_contr, picco_max] +
                           list(np.linspace(lo, hi, 41)) + list(picchi)))
    righe_s = []
    for cand in candidati:
        qf, pen, tot = _costo_tot(cand)
        righe_s.append({"Potenza (kW)": round(cand, 0), "Quota fissa (€)": round(qf, 2),
                        "Penali (€)": round(pen, 2), "Totale (€)": round(tot, 2)})
    scansione = pd.DataFrame(righe_s, columns=cols_s)
    i_best = int(np.argmin([r["Totale (€)"] for r in righe_s]))
    pot_ott = float(righe_s[i_best]["Potenza (kW)"])
    costo_ott = float(righe_s[i_best]["Totale (€)"])
    qf_a, pen_a, costo_att = _costo_tot(p_contr)
    mesi_sup = int((picchi > p_contr).sum())
    risp = costo_att - costo_ott
    risp_annuo = risp * 12.0 / n_mesi

    if pot_ott < 0.9 * p_contr:
        categoria = "sovradimensionata"
        verdetto = (f"📉 Potenza sovradimensionata: l'ottimo e' {pot_ott:,.0f} kW "
                    f"contro {p_contr:,.0f} kW impegnati — ridurla taglia la quota "
                    f"fissa di {risp_annuo:,.0f} €/anno senza penali.")
    elif pot_ott > 1.1 * p_contr:
        categoria = "sottodimensionata"
        verdetto = (f"📈 Potenza sottodimensionata: l'ottimo e' {pot_ott:,.0f} kW "
                    f"contro {p_contr:,.0f} kW impegnati — con {mesi_sup} mesi di "
                    f"superamento, alzare l'impegnata risparmia {risp_annuo:,.0f} €/anno.")
    else:
        categoria = "adeguata"
        verdetto = (f"✅ Potenza adeguata: {p_contr:,.0f} kW impegnati contro un ottimo "
                    f"di {pot_ott:,.0f} kW — margine di miglioramento solo {risp_annuo:,.0f} €/anno.")

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi": n_mesi, "mwh_tot": float(mw.sum()),
            "picco_max_kw": round(picco_max, 0), "p_contr_kw": round(p_contr, 0),
            "potenza_ottima_kw": round(pot_ott, 0),
            "costo_attuale": round(costo_att, 2), "costo_ottimo": round(costo_ott, 2),
            "risparmio_periodo": round(risp, 2), "risparmio_annuo": round(risp_annuo, 2),
            "mesi_superamento": mesi_sup, "categoria": categoria,
            "verdetto": verdetto,
            "mensile": pd.DataFrame(righe, columns=cols_m), "scansione": scansione}


def calcola_rollover_coperture(prezzi, mw=1.0, quota_copertura_pct=50.0,
                               mesi_anticipo=1, soglia_regime_pct=1.5):
    """Backtest del costo di rolling di una copertura forward mensile continua.

    Il desk compra ogni mese la consegna del mese successivo con una
    copertura a termine "rolling": a fine mese chiude la copertura in
    scadenza e apre quella nuova. Il ROLL di ogni mese e' la differenza tra
    il prezzo pagato per la nuova copertura e quello pagato per la vecchia:
      roll_i = strip_{i-k} - strip_{i-k-1}   (EUR/MWh, firmato: + = costo)
    Roll positivo = curva in CONTANGO (il rolling costa soldi); roll
    negativo = BACKWARDATION (il rolling guadagna).
    roll_yield_i = -roll_i / strip_{i-k-1} * 100  (+ = guadagno in backwardation)
    Regime: "contango" se roll_yield < -soglia, "backwardation" se
    roll_yield > soglia, altrimenti "piatto" (soglia in %).
    costo_eur_i = roll_i * MWh coperti del mese i (mw * ore_mese * quota/100).

    Con i soli spot storici il prezzo "pagato" e' approssimato con lo strip
    base implicito del mese di acquisto (media delle ore del mese): e' un
    proxy di backtest, NON la vera curva forward quotata. mesi_anticipo
    (1-3) sposta indietro la finestra di acquisto: con k=1 il prezzo per la
    consegna del mese i e' lo strip del mese i-1, con k=2 lo strip del
    mese i-2, ecc. Nota: con k>1 il roll cambia solo per la finestra
    storica usata (i differenziali strip_j - strip_{j-1} sono gli stessi).

    NaN-safe: serie vuota / indice non datetime / < 3 mesi / mw <= 0 /
    quota fuori [0,100] / anticipo fuori [1,3] / soglia negativa ->
    errore pulito; tz-aware reso naive; mesi con ore zero saltati.

    Ritorna dict con errore/valido/n_ore/n_mesi_totali/n_roll/mw/
    quota_copertura_pct/mesi_anticipo/totale_eur/roll_medio_eur_mwh/
    yield_medio_pct/mesi_contango/mesi_backwardation/mesi_piatti/
    costo_annuo_stimato/costo_fornitura/incidenza_pct/categoria/
    verdetto/mensile/sensibilita.
    """
    cols_m = ["Mese", "Strip (\u20ac/MWh)", "Roll (\u20ac/MWh)", "Roll yield (%)",
              "Regime", "MWh coperti", "Costo roll (\u20ac)"]
    cols_s = ["Quota copertura (%)", "Costo annuo stimato (\u20ac)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi_totali": 0,
                "n_roll": 0, "mw": None, "quota_copertura_pct": None,
                "mesi_anticipo": None, "totale_eur": None,
                "roll_medio_eur_mwh": None, "yield_medio_pct": None,
                "mesi_contango": 0, "mesi_backwardation": 0, "mesi_piatti": 0,
                "costo_annuo_stimato": None, "costo_fornitura": None,
                "incidenza_pct": None, "categoria": None, "verdetto": msg,
                "mensile": pd.DataFrame(columns=cols_m),
                "sensibilita": pd.DataFrame(columns=cols_s)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        mw_f = float(mw)
        quota = float(quota_copertura_pct)
        soglia = float(soglia_regime_pct)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: MW, quota e soglia devono essere numeri.")
    if not mw_f > 0:
        return _err("Potenza non valida: inserisci MW > 0.")
    if not 0.0 <= quota <= 100.0:
        return _err("Quota di copertura non valida: inserisci un valore tra 0 e 100.")
    try:
        k = int(mesi_anticipo)
    except (TypeError, ValueError):
        return _err("Anticipo non valido: mesi_anticipo deve essere intero tra 1 e 3.")
    if k not in (1, 2, 3):
        return _err("Anticipo non valido: mesi_anticipo deve essere 1, 2 o 3.")
    if not soglia >= 0:
        return _err("Soglia di regime non valida: non puo' essere negativa.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) == 0:
        return _err("Serie vuota: nessun dato disponibile.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index

    mesi = idxn.to_period("M")
    strip = {}
    ore_m = {}
    for m, grp in pd.Series(p.values, index=idxn).groupby(mesi):
        if len(grp) == 0:
            continue
        v = float(np.nanmean(grp.values))
        if np.isnan(v):
            continue
        strip[str(m)] = v
        ore_m[str(m)] = int(len(grp))
    mesi_ord = sorted(strip.keys())
    n_mesi = len(mesi_ord)
    if n_mesi < 3:
        return _err("Servono almeno 3 mesi di dati per simulare il rolling.")
    if n_mesi - k - 1 < 1:
        return _err(f"Con anticipo di {k} mesi servono almeno {k + 2} mesi di dati.")

    righe = []
    roll_vals, yield_vals, costi = [], [], []
    n_cont = n_back = n_flat = 0
    costo_fornitura = 0.0
    for pos in range(k + 1, n_mesi):
        m_del = mesi_ord[pos]          # mese di consegna coperto
        s_new = strip[mesi_ord[pos - k]]
        s_old = strip[mesi_ord[pos - k - 1]]
        roll = s_new - s_old
        yld = -roll / s_old * 100.0 if s_old != 0 else float("nan")
        if not np.isnan(yld) and yld < -soglia:
            regime = "contango"
            n_cont += 1
        elif not np.isnan(yld) and yld > soglia:
            regime = "backwardation"
            n_back += 1
        else:
            regime = "piatto"
            n_flat += 1
        mwh = mw_f * ore_m[m_del] * quota / 100.0
        costo = roll * mwh
        roll_vals.append(roll)
        yield_vals.append(yld)
        costi.append(costo)
        costo_fornitura += strip[m_del] * ore_m[m_del] * mw_f
        righe.append({"Mese": m_del, "Strip (\u20ac/MWh)": round(s_new, 2),
                      "Roll (\u20ac/MWh)": round(roll, 2),
                      "Roll yield (%)": round(yld, 2) if not np.isnan(yld) else None,
                      "Regime": regime, "MWh coperti": round(mwh, 1),
                      "Costo roll (\u20ac)": round(costo, 2)})

    roll_vals = np.array(roll_vals)
    n_roll = len(righe)
    totale = float(np.sum(costi))
    roll_medio = float(np.mean(roll_vals))
    yv = np.array([y for y in yield_vals if not np.isnan(y)])
    yield_medio = float(np.mean(yv)) if len(yv) else 0.0
    costo_annuo = totale / n_roll * 12.0
    incidenza = (abs(totale) / costo_fornitura * 100.0) if costo_fornitura > 0 else 0.0
    if totale > 0.005:
        categoria = "costo"
        verdetto = (f"Il rolling ti e' costato {totale:,.0f} \u20ac sul periodo "
                    f"({n_cont} mesi in contango, {n_back} in backwardation): la curva "
                    "prezza i mesi lontani piu' dei vicini. Valuta coperture piu' lunghe "
                    "o acquisti a pronti nei mesi di contango estremo.")
    elif totale < -0.005:
        categoria = "guadagno"
        verdetto = (f"Il rolling ti ha fatto guadagnare {abs(totale):,.0f} \u20ac sul periodo "
                    f"({n_back} mesi in backwardation, {n_cont} in contango): la curva "
                    "prezza i mesi lontani meno dei vicini. Mantieni il rolling mensile, "
                    "il mercato ti paga per farlo.")
    else:
        categoria = "neutro"
        verdetto = (f"Rolling quasi neutro ({totale:,.2f} \u20ac sul periodo, {n_flat} mesi "
                    "piatti): il costo del rolling non e' un driver in questo periodo.")

    sens_righe = []
    for q in range(0, 101, 10):
        c_ann = costo_annuo * q / quota if quota > 0 else 0.0
        sens_righe.append({"Quota copertura (%)": q,
                           "Costo annuo stimato (\u20ac)": round(c_ann, 0)})

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi_totali": n_mesi, "n_roll": n_roll, "mw": mw_f,
            "quota_copertura_pct": quota, "mesi_anticipo": k,
            "totale_eur": round(totale, 2),
            "roll_medio_eur_mwh": round(roll_medio, 2),
            "yield_medio_pct": round(yield_medio, 2),
            "mesi_contango": n_cont, "mesi_backwardation": n_back,
            "mesi_piatti": n_flat,
            "costo_annuo_stimato": round(costo_annuo, 0),
            "costo_fornitura": round(costo_fornitura, 0),
            "incidenza_pct": round(incidenza, 2),
            "categoria": categoria, "verdetto": verdetto,
            "mensile": pd.DataFrame(righe, columns=cols_m),
            "sensibilita": pd.DataFrame(sens_righe, columns=cols_s)}


def calcola_peak_shaving(prezzi, mw_f1, mw_f2, mw_f3, cap_mwh, pot_mw,
                         eff_pct=85.0, quota_eur_kw_mese=2.5,
                         potenza_attuale_kw=1000.0, degrado_eur_mwh=0.0,
                         capex_batteria_eur=0.0, n_soglie=21):
    """Peak shaving con batteria: taglia i picchi per abbassare la potenza impegnata.

    Domanda operativa: 'conviene una batteria per ridurre la quota fissa di
    potenza (EUR/kW/mese)?' Complemento operativo del tab 'Potenza impegnata'
    (tab146), che ottimizza la potenza contrattuale sul profilo esistente:
    qui si simula l'INTERVENTO fisico che abbassa i picchi mensili.

    Metodo (tutto deterministico a parita' di input, euristica giornaliera):
    - carico orario (kW) dal profilo MW per fascia F1/F2/F3 (via _fascia_aeegsi);
    - per ogni giorno e per ogni soglia T la batteria SCARICA nelle ore di
      carico piu' alto per portare il prelievo netto verso T (priorita' ai
      picchi, limiti di potenza e di energia, rendimento sqrt(eff) per lato),
      poi RICARICA nelle ore piu' economiche senza mai superare T (la
      ricarica non deve creare un nuovo picco: T e' il tetto contrattuale);
    - il SOC si propaga da un giorno all'altro (parte da batteria piena):
      se T e' troppo bassa rispetto al carico notturno la batteria non
      riesce a ricaricarsi, si esaurisce nei primi giorni e i picchi
      tornano al lordo: lo sweep penalizza onestamente queste soglie.
    Sweep di n_soglie soglie tra il 55% e il 100% del picco lordo massimo.
    Per ogni soglia:
      picchi netti mensili -> nuova potenza impegnata ottimale;
      risparmio quota = max(0, min(attuale, picco_lordo) - ottimale)
                        x quota x n_mesi  (alla batteria e' accreditata solo
                        la riduzione SOTTO il livello gia' ottenibile senza
                        batteria: senza batteria contratteresti il picco lordo);
      delta_energia = somma((netto - lordo)/1000 x prezzo_orario)
                      (negativo = risparmio: scarichi nelle ore care);
      degrado = MWh scaricati x degrado_eur_mwh;
      beneficio netto = risparmio quota - delta_energia - degrado,
      annualizzato x 12/n_mesi. Ottimo = soglia col massimo beneficio.

    NaN-safe: serie vuota / indice non datetime / MW tutti a zero /
    cap_mwh o pot_mw <= 0 / eff fuori (0, 100] / potenza attuale <= 0 ->
    errore pulito, DataFrame con le colonne giuste vuoti.

    Ritorna dict con 'errore', 'valido', 'n_ore', 'n_mesi', 'picco_lordo_kw',
    'soglia_ottima_kw', 'potenza_ottimale_kw', 'risparmio_annuo_netto',
    'quota_annua', 'delta_energia_annuo', 'degrado_annuo',
    'mwh_scaricati_annui', 'payback_anni' (None se capex <= 0 o
    beneficio <= 0), 'riduzione_picco_pct', 'categoria'
    ('conviene'/'non-conviene'/'inutile'), 'verdetto', 'sweep' (DataFrame)
    e 'mensile' (DataFrame alla soglia ottima).
    """
    cols_s = ["Soglia (kW)", "Risparmio annuo netto (\u20ac)",
              "Potenza ottimale (kW)", "Quota domanda (\u20ac/anno)",
              "Delta costo energia (\u20ac/anno)", "Degrado (\u20ac/anno)"]
    cols_m = ["Mese", "Picco lordo (kW)", "Picco netto (kW)", "Risparmio quota (\u20ac)"]
    vuoto = {"errore": "Dati insufficienti: nessuna ora valida nel periodo.",
             "valido": False, "n_ore": 0, "n_mesi": 0, "picco_lordo_kw": 0.0,
             "soglia_ottima_kw": None, "potenza_ottimale_kw": None,
             "risparmio_annuo_netto": 0.0, "quota_annua": 0.0,
             "delta_energia_annuo": 0.0, "degrado_annuo": 0.0,
             "mwh_scaricati_annui": 0.0, "payback_anni": None,
             "riduzione_picco_pct": 0.0, "categoria": "non-conviene",
             "verdetto": "",
             "sweep": pd.DataFrame(columns=cols_s),
             "mensile": pd.DataFrame(columns=cols_m)}

    def _err(msg):
        out = dict(vuoto)
        out["errore"] = msg
        return out

    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)),
              "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")
    try:
        cap_kwh = float(cap_mwh) * 1000.0
        pot_kw = float(pot_mw) * 1000.0
    except Exception:
        return _err("Capacita' e potenza della batteria devono essere numeri positivi.")
    if not (cap_kwh > 0.0 and pot_kw > 0.0):
        return _err("Capacita' e potenza della batteria devono essere maggiori di zero.")
    try:
        eff = float(eff_pct) / 100.0
    except Exception:
        eff = float("nan")
    if not (0.0 < eff <= 1.0):
        return _err("Il rendimento deve essere compreso tra 0 e 100% (escluso lo 0).")
    eff_side = float(np.sqrt(eff))
    quota = max(0.0, float(quota_eur_kw_mese or 0.0))
    try:
        p_att = float(potenza_attuale_kw)
    except Exception:
        p_att = float("nan")
    if not (p_att > 0.0):
        return _err("La potenza impegnata attuale deve essere maggiore di zero.")
    degr = max(0.0, float(degrado_eur_mwh or 0.0))
    try:
        capex = max(0.0, float(capex_batteria_eur or 0.0))
    except Exception:
        capex = 0.0
    try:
        n_thr = int(n_soglie)
    except Exception:
        n_thr = 21
    n_thr = max(5, min(61, n_thr))

    ore = idx.hour.to_numpy()
    wd = idx.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, d) for h, d in zip(ore, wd)])
    load_kw = np.array([mw_map[f] * 1000.0 for f in fasce])
    price = p.to_numpy(dtype=float)
    picco_lordo = float(load_kw.max())
    if picco_lordo <= 0.0:
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    giorni = idx.to_period("D").to_numpy()
    _, inv = np.unique(giorni, return_inverse=True)
    pos_giorni = [np.flatnonzero(inv == i) for i in range(int(inv.max()) + 1)]
    mesi = idx.to_period("M")
    n_mesi = int(mesi.nunique())
    ann = 12.0 / n_mesi if n_mesi > 0 else 1.0
    # picchi lordi mensili (una sola volta: non dipendono dalla soglia)
    s_load = pd.Series(load_kw, index=idx)
    picchi_lordi_m = s_load.groupby(mesi).max()

    def _simula(T):
        """Simula un anno di gestione giornaliera con soglia T (kW).

        Ritorna (net_kw, mwh_scaricati): serie del prelievo netto e MWh
        scaricati (energia erogata alla rete)."""
        soc = cap_kwh  # parte da batteria piena
        net = load_kw.copy()
        scar_kwh = 0.0
        car_kwh = 0.0
        for pos in pos_giorni:
            ld = load_kw[pos]
            pr = price[pos]
            # --- scarica: prima le ore di carico piu' alto ---
            need = np.minimum(np.maximum(ld - T, 0.0), pot_kw)
            if need.sum() > 0.0 and soc > 0.0:
                order = np.argsort(-ld, kind="stable")
                e_need = need[order] / eff_side  # energia da prelevare dalla batteria
                cum = np.cumsum(e_need)
                mask_full = cum <= soc + 1e-9
                take = np.zeros_like(e_need)
                take[mask_full] = need[order][mask_full]
                usato = float(cum[mask_full][-1]) if mask_full.any() else 0.0
                resto = soc - usato
                idx_p = np.flatnonzero(~mask_full)
                if idx_p.size and resto > 1e-9:
                    j = int(idx_p[0])
                    take[j] = min(float(need[order][j]), resto * eff_side)
                d = np.zeros_like(need)
                d[order] = take
                net[pos] = ld - d
                soc = max(0.0, min(cap_kwh, soc - float((d / eff_side).sum())))
                scar_kwh += float(d.sum())
            # --- ricarica: ore piu' economiche senza superare T ---
            room = cap_kwh - soc
            if room > 1e-9:
                nd = net[pos]
                cand = np.minimum(np.maximum(T - nd, 0.0), pot_kw)
                if cand.sum() > 0.0:
                    order_c = np.argsort(pr, kind="stable")
                    e_in = cand[order_c] * eff_side  # energia che entrerebbe in batteria
                    cum_c = np.cumsum(e_in)
                    mask_f = cum_c <= room + 1e-9
                    take_c = np.zeros_like(e_in)
                    take_c[mask_f] = cand[order_c][mask_f]
                    usato_c = float(cum_c[mask_f][-1]) if mask_f.any() else 0.0
                    resto_c = room - usato_c
                    idx_pc = np.flatnonzero(~mask_f)
                    if idx_pc.size and resto_c > 1e-9:
                        j = int(idx_pc[0])
                        take_c[j] = min(float(cand[order_c][j]), resto_c / eff_side)
                    c = np.zeros_like(cand)
                    c[order_c] = take_c
                    net[pos] = nd + c
                    soc = max(0.0, min(cap_kwh, soc + float((c * eff_side).sum())))
                    car_kwh += float(c.sum())
        return net, scar_kwh / 1000.0, car_kwh / 1000.0

    baseline_kw = min(p_att, picco_lordo)  # livello gia' ottenibile senza batteria
    righe = []
    dettaglio = {}
    for T in np.linspace(0.55 * picco_lordo, picco_lordo, n_thr):
        T = float(T)
        net, mwh_scar, _ = _simula(T)
        delta_eur = float((((net - load_kw) / 1000.0) * price).sum())
        degr_eur = mwh_scar * degr
        s_net = pd.Series(net, index=idx)
        picchi_net = s_net.groupby(mesi).max()
        pot_ott = float(picchi_net.max())
        risparmio_quota = max(0.0, baseline_kw - pot_ott) * quota * n_mesi
        beneficio = risparmio_quota - delta_eur - degr_eur
        righe.append({"Soglia (kW)": round(T, 1),
                      "Risparmio annuo netto (\u20ac)": round(beneficio * ann, 0),
                      "Potenza ottimale (kW)": round(pot_ott, 1),
                      "Quota domanda (\u20ac/anno)": round(risparmio_quota * ann, 0),
                      "Delta costo energia (\u20ac/anno)": round(delta_eur * ann, 0),
                      "Degrado (\u20ac/anno)": round(degr_eur * ann, 0)})
        dettaglio[T] = (net, mwh_scar, delta_eur, degr_eur, risparmio_quota,
                        pot_ott, picchi_net, beneficio)

    sweep = pd.DataFrame(righe, columns=cols_s)
    i_best = int(sweep["Risparmio annuo netto (\u20ac)"].idxmax())
    T_best = float(sweep.loc[i_best, "Soglia (kW)"])
    # ritrova la chiave esatta del dettaglio (arrotondamento a 1 decimale)
    T_key = min(dettaglio.keys(), key=lambda k: abs(k - T_best))
    net_b, mwh_scar_b, delta_b, degr_b, quota_b, pot_ott_b, picchi_net_b, ben_b = dettaglio[T_key]

    righe_m = []
    for per, pl in picchi_lordi_m.items():
        pn = float(picchi_net_b[per])
        rq = max(0.0, baseline_kw - pn) * quota
        righe_m.append({"Mese": per.strftime("%Y-%m"),
                        "Picco lordo (kW)": round(float(pl), 1),
                        "Picco netto (kW)": round(pn, 1),
                        "Risparmio quota (\u20ac)": round(rq, 0)})
    mensile = pd.DataFrame(righe_m, columns=cols_m)

    risparmio_annuo = float(sweep.loc[i_best, "Risparmio annuo netto (\u20ac)"])
    quota_annua = float(sweep.loc[i_best, "Quota domanda (\u20ac/anno)"])
    delta_annuo = float(sweep.loc[i_best, "Delta costo energia (\u20ac/anno)"])
    degr_annuo = float(sweep.loc[i_best, "Degrado (\u20ac/anno)"])
    payback = round(capex / risparmio_annuo, 1) if (capex > 0.0 and risparmio_annuo > 0.0) else None
    rid_picco = (1.0 - pot_ott_b / picco_lordo) * 100.0 if picco_lordo > 0 else 0.0

    if risparmio_annuo <= 0.0:
        categoria = "non-conviene"
        verdetto = (f"Con questi parametri il peak shaving non si ripaga "
                    f"({risparmio_annuo:,.0f} \u20ac/anno): la batteria costa piu' "
                    f"di quanto fa risparmiare su quota di potenza ed energia.")
    elif quota_annua <= 0.0:
        categoria = "inutile"
        verdetto = (f"La batteria porta un beneficio energetico ({risparmio_annuo:,.0f} "
                    f"\u20ac/anno) ma non riduce la potenza impegnata sotto il livello "
                    f"gia' ottenibile senza batteria ({baseline_kw:,.0f} kW): per la "
                    f"quota di potenza e' inutile, valuta il solo arbitraggio.")
    else:
        categoria = "conviene"
        verdetto = (f"Conviene: soglia ottima {T_best:,.0f} kW, potenza impegnata "
                    f"riducibile a {pot_ott_b:,.0f} kW con un beneficio netto di "
                    f"{risparmio_annuo:,.0f} \u20ac/anno.")

    return {"errore": None, "valido": True, "n_ore": int(len(p)), "n_mesi": n_mesi,
            "picco_lordo_kw": round(picco_lordo, 1),
            "soglia_ottima_kw": round(T_best, 1),
            "potenza_ottimale_kw": round(pot_ott_b, 1),
            "risparmio_annuo_netto": risparmio_annuo,
            "quota_annua": quota_annua,
            "delta_energia_annuo": delta_annuo,
            "degrado_annuo": degr_annuo,
            "mwh_scaricati_annui": round(mwh_scar_b * ann, 1),
            "payback_anni": payback,
            "riduzione_picco_pct": round(rid_picco, 1),
            "categoria": categoria, "verdetto": verdetto,
            "sweep": sweep, "mensile": mensile}


def _phi_std(z):
    """CDF della normale standard (approssimazione Abramowitz-Stegun 7.1.26).

    Solo numpy: serve ai test standalone che estraggono le funzioni via AST
    senza gli import di modulo (scipy non disponibile nel namespace isolato).
    """
    x = float(z)
    t = 1.0 / (1.0 + 0.2316419 * abs(x))
    d = 0.3989422804014327 * np.exp(-x * x / 2.0)
    p = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 +
         t * (-1.821255978 + t * 1.330274429))))
    return 1.0 - p if x >= 0 else p


def _gammaln(x):
    """Logaritmo della funzione Gamma (Lanczos g=7), solo numpy.

    Serve alla correzione di Anis-Lloyd dell'R/S atteso per rumore bianco:
    la stima R/S grezza su finestre piccole e' distorta verso l'alto
    (su rumore bianco puro darebbe H ~ 0.65 invece di 0.5), quindi H si
    stima come 0.5 + pendenza di log(R/S / E[R/S_bianco]) su log(n).
    Implementata qui (e non via scipy) perche' i test standalone estraggono
    le funzioni via AST senza gli import di modulo.
    """
    xa = np.atleast_1d(np.asarray(x, dtype=float))
    if np.any(xa <= 0.0):
        raise ValueError("gammaln: x deve essere > 0")
    _c = np.array([0.99999999999980993, 676.5203681218851, -1259.1392167224028,
                   771.32342877765313, -176.61502916214059, 12.507343278686905,
                   -0.13857109526572012, 9.9843695780195716e-6,
                   1.5056327351493116e-7])
    refl = xa < 0.5
    y = np.where(refl, 1.0 - xa, xa) - 1.0
    a = _c[0] + sum(_c[k] / (y + k) for k in range(1, 9))
    t = y + 7.5
    out = 0.5 * np.log(2.0 * np.pi) + (y + 0.5) * np.log(t) - t + np.log(a)
    if np.any(refl):
        xr = xa[refl]
        out[refl] = np.log(np.pi) - np.log(np.sin(np.pi * xr)) - out[refl]
    return out[0] if np.ndim(x) == 0 else out


def _rs_atteso_bianco(n):
    """E[R/S_n] per rumore bianco gaussiano (Anis-Lloyd 1976).

    E[R/S_n] = Gamma((n-1)/2) / (sqrt(pi) * Gamma(n/2))
               * sum_{i=1}^{n-1} sqrt((n-i)/i)
    Usato per correggere la distorsione da campione finito dell'analisi R/S.
    """
    n = int(n)
    if n < 2:
        return float("nan")
    i = np.arange(1, n)
    return float(np.exp(_gammaln((n - 1) / 2.0) - _gammaln(n / 2.0))
                 / np.sqrt(np.pi) * np.sqrt((n - i) / i).sum())


def calcola_hurst(prezzi, scala_min_giorni=4, n_scale=12, min_giorni=60):
    """Esponente di Hurst (analisi R/S) sulle medie giornaliere + runs test di efficienza debole.

    Domanda operativa: 'il prezzo dello spot ha memoria?' H misura la memoria
    di LUNGO periodo della serie:
      H < 0.45  -> MEAN-REVERTING (antipersistente): i movimenti tendono a
                   rientrare; conviene comprare sui cali e vendere sui picchi,
                   e dopo uno shock aspettare il rientro prima di fissare;
      0.45-0.55 -> RANDOM WALK: nessuna memoria sfruttabile; il timing non
                   paga, meglio medie di periodo e strategie sistematiche;
      H > 0.55  -> PERSISTENTE (trending): i movimenti tendono a proseguire;
                   conviene seguire il trend, non scommettere sul rientro.

    Metodo: variazioni giornaliere delle medie giornaliere dei prezzi orari
    (la serie stazionaria su cui l'analisi R/S e' valida: sui livelli grezzi
    sia R che S crescerebbero con la scala, falsando H); analisi R/S
    (rescaled range, S con ddof=0 come nella definizione classica) su finestre
    non sovrapposte di n giorni, con n log-spaziato tra scala_min_giorni e
    N/4 giorni (servono >= 4 scale valide). La stima R/S grezza e' distorta
    verso l'alto sulle finestre piccole (su rumore bianco darebbe H ~ 0.65):
    si applica la correzione di Anis-Lloyd e H = 0.5 + pendenza della retta
    OLS in forma chiusa di log10(R/S / E[R/S_bianco]) su log10(n).
    Completato dal RUNS TEST di Wald-Wolfowitz sui segni delle variazioni
    giornaliere (forma debole dell'efficienza di mercato: con p < 5% i segni
    delle variazioni non sono casuali).

    Differenza rispetto agli altri tab: 'Mean reversion' stima AR(1) sulle ore
    (memoria di BREVE periodo, half-life in ore); 'Autocorrelazione' mostra la
    memoria per singolo lag; qui si misura la memoria di LUNGO periodo su piu'
    scale (settimane/mesi), la scala rilevante per le decisioni di fixing,
    di budgeting e di timing degli acquisti.

    NaN-safe: ore NaN ignorate; giorni senza ore valide esclusi; serie vuota /
    indice non datetime / meno di min_giorni giorni validi / serie giornaliera
    costante o variazioni nulle (S = 0 ovunque) / meno di 4 scale valide ->
    errore pulito.
    Deterministico a parita' di input (nessun seed: solo aritmetica).

    Ritorna dict con 'errore', 'valido', 'n_giorni', 'hurst', 'r2_fit',
    'classe' ('mean-reverting'/'random-walk'/'persistente'), 'verdetto',
    'segnale' (implicazione operativa), 'runs_n', 'runs_osservati',
    'runs_attesi', 'runs_z', 'runs_p', 'runs_verdetto', 'n_scale' e 'scale'
    (DataFrame: 'Finestra (giorni)', 'R/S medio', 'Fit R/S').
    """
    cols = ["Finestra (giorni)", "R/S medio", "Fit R/S"]
    vuoto = {"errore": "Dati insufficienti: servono almeno 60 giorni di prezzi orari validi.",
             "valido": False, "n_giorni": 0, "hurst": None, "r2_fit": None,
             "classe": None, "verdetto": "", "segnale": "", "runs_n": 0,
             "runs_osservati": None, "runs_attesi": None, "runs_z": None,
             "runs_p": None, "runs_verdetto": "", "n_scale": 0,
             "scale": pd.DataFrame(columns=cols)}

    def _err(msg):
        out = dict(vuoto)
        out["errore"] = msg
        return out

    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    if len(p) == 0 or not isinstance(p.index, pd.DatetimeIndex):
        return _err("Dati insufficienti: nessuna ora valida nel periodo.")
    idx = p.index.tz_localize(None) if p.index.tz is not None else p.index
    p = pd.Series(p.to_numpy(dtype=float), index=idx)
    giorni = p.resample("D").mean().dropna()
    n_g = len(giorni)
    try:
        mg = int(min_giorni)
    except Exception:
        mg = 60
    if n_g < max(30, mg):
        return _err(f"Dati insufficienti: servono almeno {max(30, mg)} giorni "
                    f"validi, trovati {n_g}.")
    x = giorni.to_numpy(dtype=float)
    if not np.all(np.isfinite(x)) or np.all(x == x[0]):
        return _err("Serie giornaliera costante o non finita: R/S non calcolabile.")
    # R/S va calcolato sulle variazioni (serie stazionaria), non sui livelli:
    # sui livelli sia R che S crescono con la scala e H risulta spurio (~1).
    dx = np.diff(x)
    dx = dx[np.isfinite(dx)]
    if len(dx) < 30 or np.all(dx == 0.0):
        return _err("Variazioni giornaliere insufficienti o nulle: R/S non calcolabile.")

    try:
        n_min = max(2, int(scala_min_giorni))
    except Exception:
        n_min = 4
    try:
        ns = max(4, min(24, int(n_scale)))
    except Exception:
        ns = 12
    n_max = len(dx) // 4
    if n_max <= n_min:
        return _err("Serie troppo corta per le scale richieste.")
    raw = np.unique(np.round(np.logspace(np.log10(n_min), np.log10(n_max), ns)).astype(int))
    scale_n = [int(v) for v in raw if int(v) >= n_min]
    if len(scale_n) < 4:
        return _err("Meno di 4 scale valide per la stima di Hurst.")

    def _rs_medio(v, n):
        k = len(v) // n
        if k < 2:
            return np.nan
        vals = []
        for i in range(k):
            ch = v[i * n:(i + 1) * n]
            s = ch.std(ddof=0)  # ddof=0: definizione classica dell'R/S
            if s > 0.0 and np.isfinite(s):
                cum = np.cumsum(ch - ch.mean())
                vals.append((cum.max() - cum.min()) / s)
        return float(np.mean(vals)) if vals else np.nan

    rs = np.array([_rs_medio(dx, n) for n in scale_n])
    ok = np.isfinite(rs) & (rs > 0.0)
    nn = np.array(scale_n, dtype=float)[ok]
    rs = rs[ok]
    if len(nn) < 4:
        return _err("R/S non calcolabile su abbastanza scale (serie quasi costante?).")
    e_bn = np.array([_rs_atteso_bianco(int(n)) for n in nn])
    ok2 = np.isfinite(e_bn) & (e_bn > 0.0)
    nn, rs, e_bn = nn[ok2], rs[ok2], e_bn[ok2]
    if len(nn) < 4:
        return _err("Correzione di Anis-Lloyd non valutabile sulle scale disponibili.")
    lx = np.log10(nn)
    ly = np.log10(rs / e_bn)  # scostamento dal rumore bianco
    mx, my = lx.mean(), ly.mean()
    den = ((lx - mx) ** 2).sum()
    if den <= 0.0:
        return _err("Scale degeneri: stima di Hurst impossibile.")
    pendenza = float(((lx - mx) * (ly - my)).sum() / den)
    hurst = 0.5 + pendenza  # correzione di Anis-Lloyd: il bianco ha pendenza 0
    interc = float(my - pendenza * mx)
    ss_tot = ((ly - my) ** 2).sum()
    ss_res = ((ly - (interc + pendenza * lx)) ** 2).sum()
    r2 = float(1.0 - ss_res / ss_tot) if ss_tot > 0.0 else 0.0
    r2 = max(0.0, min(1.0, r2))

    if hurst < 0.45:
        classe = "mean-reverting"
        segnale = ("Serie ANTIPERSISTENTE: i movimenti tendono a rientrare. "
                   "Strategia: comprare sui cali, vendere sui picchi; dopo uno "
                   "shock, aspettare il rientro prima di fissare il prezzo.")
    elif hurst > 0.55:
        classe = "persistente"
        segnale = ("Serie PERSISTENTE: i movimenti tendono a proseguire. "
                   "Strategia: seguire il trend in corso, non scommettere sul "
                   "rientro; fissare presto se il trend e' al rialzo.")
    else:
        classe = "random-walk"
        segnale = ("RANDOM WALK: nessuna memoria sfruttabile su queste scale. "
                   "Il timing discrezionale non paga: meglio medie di periodo, "
                   "acquisti programmati e strategie sistematiche.")

    segni = np.sign(dx[dx != 0.0])
    runs_n = int(len(segni))
    r_osservati = r_attesi = r_z = r_p = None
    r_verdetto = "Runs test non valutabile (variazioni insufficienti)."
    if runs_n >= 20:
        n_pos = int((segni > 0).sum())
        n_neg = int((segni < 0).sum())
        if n_pos > 0 and n_neg > 0:
            r_osservati = int(1 + (np.diff(segni) != 0).sum())
            n = float(runs_n)
            mu = 2.0 * n_pos * n_neg / n + 1.0
            var = (2.0 * n_pos * n_neg * (2.0 * n_pos * n_neg - n_pos - n_neg)
                   / (n * n * (n - 1.0)))
            r_attesi = float(mu)
            if var > 0.0:
                r_z = float((r_osservati - mu) / np.sqrt(var))
                r_p = float(2.0 * (1.0 - _phi_std(abs(r_z))))
                r_verdetto = ("Efficienza debole RIFIUTATA (p < 5%): i segni delle "
                              "variazioni giornaliere non sono casuali."
                              if r_p < 0.05 else
                              "Efficienza debole NON rifiutata (p >= 5%): i segni "
                              "delle variazioni sono compatibili col caso.")

    verdetto = (f"H = {hurst:.3f} ({classe.replace('-', ' ')}, R2 del fit {r2:.3f} "
                f"su {len(nn)} scale, {n_g} giorni). {segnale}")
    df_scale = pd.DataFrame({
        "Finestra (giorni)": nn.astype(int),
        "R/S medio": np.round(rs, 4),
        "Fit R/S": np.round(e_bn * 10.0 ** (interc + pendenza * lx), 4),
    })
    return {"errore": None, "valido": True, "n_giorni": int(n_g),
            "hurst": round(hurst, 4), "r2_fit": round(r2, 4),
            "classe": classe, "verdetto": verdetto, "segnale": segnale,
            "runs_n": runs_n, "runs_osservati": r_osservati,
            "runs_attesi": round(r_attesi, 2) if r_attesi is not None else None,
            "runs_z": round(r_z, 3) if r_z is not None else None,
            "runs_p": r_p, "runs_verdetto": r_verdetto,
            "n_scale": int(len(nn)), "scale": df_scale}


def calcola_tornado_sensibilita(prezzi, mw_f1, mw_f2, mw_f3, p_contr_kw,
                                quota_kw_mese, oneri_eur_mwh, delta_pct=10.0):
    """Tornado di sensibilita' del costo annuo di fornitura.

    Il costo annuo e' la somma di tre voci (stesso modello delle altre tab
    di costo): ENERGIA = somma(prezzo_orario x MW_orari), QUOTA POTENZA =
    kW impegnati x quota EUR/kW/mese x mesi, ONERI = oneri EUR/MWh x MWh
    totali. I MW orari sono costruiti dal profilo F1/F2/F3 come nelle
    altre tab.

    Il tornado varia UN driver alla volta di +/-delta_pct e misura di
    quanto si muove il costo annuo: il driver con l'ampiezza maggiore e'
    quello su cui il budget e' piu' esposto. Serve a decidere dove
    concentrare fixing, hedging e demand response.

    Driver: 'Prezzo energia', 'Volumi (MWh)', 'Quota potenza (EUR/kW)',
    'Potenza impegnata (kW)', 'Oneri (EUR/MWh)'. I costi del periodo sono
    annualizzati (x 12 / n_mesi).

    NaN-safe: serie vuota / indice non-datetime / < 24 ore / MW tutti a
    zero / costo base non positivo / potenza <= 0 / quota o oneri negativi /
    delta fuori (0, 100] -> errore pulito; tz-aware reso naive.

    Ritorna dict con errore/valido/n_ore/n_mesi/mwh_tot/costo_base_annuo/
    driver_dominante/impatto_max_pos/impatto_max_neg/quota_max_pct/
    verdetto/tornado (DataFrame ordinato per ampiezza decrescente).
    """
    cols = ["Driver", "Impatto + (EUR/a)", "Impatto - (EUR/a)",
            "Ampiezza (EUR/a)", "Quota sul costo (%)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_ore": 0, "n_mesi": 0,
                "mwh_tot": 0.0, "costo_base_annuo": 0.0,
                "driver_dominante": None, "impatto_max_pos": 0.0,
                "impatto_max_neg": 0.0, "quota_max_pct": 0.0,
                "verdetto": msg, "tornado": pd.DataFrame(columns=cols)}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        p_contr = float(p_contr_kw)
        quota = float(quota_kw_mese)
        oneri = float(oneri_eur_mwh)
        d = float(delta_pct)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: potenza, quota, oneri e delta devono essere numeri.")
    if not p_contr > 0:
        return _err("Potenza contrattuale non valida: inserisci un valore > 0 kW.")
    if quota < 0:
        return _err("Quota potenza non valida: non puo' essere negativa.")
    if oneri < 0:
        return _err("Oneri non validi: non possono essere negativi.")
    if not 0.0 < d <= 100.0:
        return _err("Delta non valido: inserisci una percentuale tra 0 (escluso) e 100.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if len(p) < 24:
        return _err("Serie troppo corta: servono almeno 24 ore di prezzi.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    mw_map = {"F1": max(0.0, float(mw_f1 or 0.0)),
              "F2": max(0.0, float(mw_f2 or 0.0)),
              "F3": max(0.0, float(mw_f3 or 0.0))}
    if all(m == 0.0 for m in mw_map.values()):
        return _err("Imposta una potenza maggiore di zero in almeno una fascia.")

    ore = p.index.hour.to_numpy()
    wd = p.index.weekday.to_numpy()
    fasce = np.array([_fascia_aeegsi(h, dd) for h, dd in zip(ore, wd)])
    mw = np.array([mw_map[f] for f in fasce])  # MW orari del profilo
    pv = p.to_numpy(dtype=float)

    idxn = p.index.tz_localize(None) if p.index.tz is not None else p.index
    n_mesi = int(idxn.to_period("M").nunique())
    ann = 12.0 / n_mesi
    mwh = float(mw.sum())
    ce = float((pv * mw).sum())        # costo energia del periodo
    cq = p_contr * quota * n_mesi      # quota potenza del periodo
    co = oneri * mwh                   # oneri del periodo
    base = ce + cq + co
    if not base > 0:
        return _err("Costo base non positivo: verifica prezzi e profilo di carico.")

    dd = d / 100.0
    drivers = [
        ("Prezzo energia",
         lambda s: float((pv * (1.0 + s) * mw).sum()) + cq + co),
        ("Volumi (MWh)",
         lambda s: float((pv * mw * (1.0 + s)).sum()) + cq + oneri * mwh * (1.0 + s)),
        ("Quota potenza (EUR/kW)",
         lambda s: ce + p_contr * quota * (1.0 + s) * n_mesi + co),
        ("Potenza impegnata (kW)",
         lambda s: ce + p_contr * (1.0 + s) * quota * n_mesi + co),
        ("Oneri (EUR/MWh)",
         lambda s: ce + cq + oneri * (1.0 + s) * mwh),
    ]
    base_a = base * ann
    righe = []
    for nome, fn in drivers:
        up = (fn(dd) - base) * ann
        dn = (fn(-dd) - base) * ann
        amp = max(abs(up), abs(dn))
        righe.append({"Driver": nome,
                      "Impatto + (EUR/a)": round(up, 0),
                      "Impatto - (EUR/a)": round(dn, 0),
                      "Ampiezza (EUR/a)": round(amp, 0),
                      "Quota sul costo (%)": round(100.0 * amp / base_a, 2)})
    tornado = (pd.DataFrame(righe, columns=cols)
               .sort_values("Ampiezza (EUR/a)", ascending=False, kind="mergesort")
               .reset_index(drop=True))
    dom = str(tornado.iloc[0]["Driver"])
    amp_max = float(tornado.iloc[0]["Ampiezza (EUR/a)"])
    q_max = float(tornado.iloc[0]["Quota sul costo (%)"])
    ipos = float(tornado["Impatto + (EUR/a)"].max())
    ineg = float(tornado["Impatto - (EUR/a)"].min())

    nota = {
        "Prezzo energia": "Il mercato pesa piu' del contratto: priorita' a fixing e coperture.",
        "Volumi (MWh)": "Il profilo di consumo pesa piu' del prezzo: priorita' a demand response ed efficienza.",
        "Quota potenza (EUR/kW)": "La voce di rete domina: rinegozia quota e potenza col distributore.",
        "Potenza impegnata (kW)": "Il tetto di potenza domina il conto: vedi la tab 'Potenza impegnata' per l'ottimo.",
        "Oneri (EUR/MWh)": "Gli oneri di sistema dominano: verifica esenzioni e voci in bolletta.",
    }.get(dom, "")
    verdetto = (f"Tornado: driver dominante {dom} — uno shock di ±{d:.0f}% muove il costo "
                f"annuo di {amp_max:,.0f} EUR/anno ({q_max:.1f}% del totale di {base_a:,.0f} EUR/anno). {nota}")

    return {"errore": None, "valido": True, "n_ore": int(len(p)),
            "n_mesi": n_mesi, "mwh_tot": round(mwh, 1),
            "costo_base_annuo": round(base_a, 0),
            "driver_dominante": dom, "impatto_max_pos": round(ipos, 0),
            "impatto_max_neg": round(ineg, 0), "quota_max_pct": round(q_max, 2),
            "verdetto": verdetto, "tornado": tornado}
def calcola_segnali_tecnici(prezzi, rsi_period=14, macd_fast=12, macd_slow=26,
                           macd_signal=9, sma_breve=20, sma_lunga=50,
                           bb_period=20, bb_mult=2.0, orizzonte_gg=5):
    """Segnali tecnici sul prezzo: RSI, MACD, incroci di medie mobili, Bande di Bollinger.

    Lavora sulle medie GIORNALIERE dei prezzi orari (gli indicatori tecnici
    sullo spot orario sono rumore). Per ogni indicatore genera segnali
    BUY/SELL sugli eventi classici:
      - Medie mobili: golden cross (media breve sopra la lunga) = BUY,
        death cross = SELL;
      - MACD: istogramma che attraversa lo zero verso l'alto = BUY, verso il
        basso = SELL;
      - RSI (Wilder): scende sotto 30 = BUY (ipervenduto), sale sopra 70 =
        SELL (ipercomprato);
      - Bollinger: chiusura che rompe la banda inferiore = BUY (mean
        reversion), che rompe la superiore = SELL.
    Ogni segnale e' backtestato sull'orizzonte scelto: esito = variazione
    del prezzo nei giorni successivi (segno invertito per i SELL, cosi' un
    esito positivo = "il segnale aveva ragione"). Hit rate = quota di
    segnali con esito positivo.

    NaN-safe: serie vuota / indice non-datetime / troppo corta / parametri
    non validi -> errore pulito; tz-aware reso naive; prezzi <= 0 saltati
    nel backtest (rendimenti non definiti); deterministico.

    Ritorna dict con errore/valido/n_giorni/giorni_richiesti/ultimo
    (prezzo/rsi/macd/macd_signal/hist/sma_breve/sma_lunga/bb_pos_pct)/
    stance (sma/rsi/macd/bb)/punteggio/verdetto/n_segnali/hit_rate_tot/
    esito_medio_tot/segnali (DataFrame)/riepilogo (DataFrame)/serie
    (DataFrame giornaliero con gli indicatori).
    """
    col_s = ["Data", "Indicatore", "Segnale", "Prezzo (EUR/MWh)",
             "Esito orizzonte (%)", "Esito valido"]
    col_r = ["Indicatore", "N. segnali", "Hit rate (%)", "Esito medio (%)"]

    def _err(msg):
        return {"errore": msg, "valido": False, "n_giorni": 0,
                "giorni_richiesti": 0, "ultimo": {}, "stance": {},
                "punteggio": 0, "verdetto": msg, "n_segnali": 0,
                "hit_rate_tot": float("nan"), "esito_medio_tot": float("nan"),
                "segnali": pd.DataFrame(columns=col_s),
                "riepilogo": pd.DataFrame(columns=col_r),
                "serie": pd.DataFrame()}

    if not isinstance(prezzi, pd.Series):
        return _err("Input non valido: serve una Series pandas.")
    try:
        rp = int(rsi_period); mf = int(macd_fast); ms = int(macd_slow)
        mgs = int(macd_signal); sb = int(sma_breve); sl = int(sma_lunga)
        bp = int(bb_period); bm = float(bb_mult); hz = int(orizzonte_gg)
    except (TypeError, ValueError):
        return _err("Parametri non numerici: periodi e orizzonte devono essere numeri.")
    if not 2 <= rp <= 100:
        return _err("Periodo RSI non valido: inserisci un intero tra 2 e 100.")
    if not (2 <= mf < ms <= 200):
        return _err("Parametri MACD non validi: serve 2 <= fast < slow <= 200.")
    if not 2 <= mgs <= 100:
        return _err("Periodo segnale MACD non valido: inserisci un intero tra 2 e 100.")
    if not (2 <= sb < sl <= 300):
        return _err("Medie mobili non valide: serve 2 <= breve < lunga <= 300.")
    if not 2 <= bp <= 200:
        return _err("Periodo Bollinger non valido: inserisci un intero tra 2 e 200.")
    if not 0.5 <= bm <= 5.0:
        return _err("Moltiplicatore Bollinger non valido: inserisci un valore tra 0,5 e 5.")
    if not 1 <= hz <= 60:
        return _err("Orizzonte non valido: inserisci un intero tra 1 e 60 giorni.")
    try:
        p = pd.to_numeric(prezzi, errors="coerce").dropna()
        p = p[~p.index.duplicated(keep="first")].sort_index()
    except Exception:
        return _err("Input non valido: serie prezzi non leggibile.")
    if not isinstance(p.index, pd.DatetimeIndex):
        return _err("Indice non temporale: serve una serie oraria con DatetimeIndex.")
    if p.index.tz is not None:
        p.index = p.index.tz_localize(None)
    if len(p) == 0:
        return _err("Serie vuota: nessun prezzo valido.")

    richiesti = max(sl, ms + mgs, bp, rp + 1, hz + 2)
    s = p.resample("D").mean().dropna()
    n = len(s)
    if n < richiesti:
        return _err("Serie troppo corta: servono almeno %d giorni di prezzi (ne hai %d)."
                    % (richiesti, n))

    idx = s.index
    px = s.to_numpy(dtype=float)

    # --- RSI di Wilder ---
    delta = s.diff()
    gain = delta.clip(lower=0.0)
    loss = -delta.clip(upper=0.0)
    ag = gain.ewm(alpha=1.0 / rp, min_periods=rp, adjust=False).mean()
    al = loss.ewm(alpha=1.0 / rp, min_periods=rp, adjust=False).mean()
    rsi = 100.0 - 100.0 / (1.0 + ag / al)
    rsi = rsi.mask((ag == 0) & (al == 0), 50.0)  # serie piatta -> RSI neutro

    # --- MACD ---
    ema_f = s.ewm(span=mf, adjust=False).mean()
    ema_s = s.ewm(span=ms, adjust=False).mean()
    macd = ema_f - ema_s
    macd_sig = macd.ewm(span=mgs, adjust=False).mean()
    hist = macd - macd_sig

    # --- Medie mobili ---
    sma_b = s.rolling(sb, min_periods=sb).mean()
    sma_l = s.rolling(sl, min_periods=sl).mean()

    # --- Bande di Bollinger ---
    mid = s.rolling(bp, min_periods=bp).mean()
    sd = s.rolling(bp, min_periods=bp).std(ddof=1)
    up = mid + bm * sd
    lo = mid - bm * sd
    up_v = up.to_numpy(dtype=float)
    lo_v = lo.to_numpy(dtype=float)
    rng = up_v - lo_v
    pos = np.where(rng > 0, (px - lo_v) / rng * 100.0, 50.0)

    rsi_v = rsi.to_numpy(dtype=float)
    hist_v = hist.to_numpy(dtype=float)
    sb_v = sma_b.to_numpy(dtype=float)
    sl_v = sma_l.to_numpy(dtype=float)

    def _ok(*vals):
        return all(v is not None and not (isinstance(v, float) and np.isnan(v))
                   for v in vals)

    segnali = []
    for i in range(1, n):
        d = idx[i]
        pr = px[i]
        if _ok(sb_v[i - 1], sl_v[i - 1], sb_v[i], sl_v[i]):
            if sb_v[i - 1] <= sl_v[i - 1] and sb_v[i] > sl_v[i]:
                segnali.append((d, "Medie mobili", "BUY", pr,
                                "Golden cross: media breve sopra la lunga"))
            elif sb_v[i - 1] >= sl_v[i - 1] and sb_v[i] < sl_v[i]:
                segnali.append((d, "Medie mobili", "SELL", pr,
                                "Death cross: media breve sotto la lunga"))
        if _ok(hist_v[i - 1], hist_v[i]):
            if hist_v[i - 1] <= 0 < hist_v[i]:
                segnali.append((d, "MACD", "BUY", pr, "Istogramma sopra lo zero"))
            elif hist_v[i - 1] >= 0 > hist_v[i]:
                segnali.append((d, "MACD", "SELL", pr, "Istogramma sotto lo zero"))
        if _ok(rsi_v[i - 1], rsi_v[i]):
            if rsi_v[i - 1] >= 30.0 and rsi_v[i] < 30.0:
                segnali.append((d, "RSI", "BUY", pr, "RSI sotto 30: ipervenduto"))
            elif rsi_v[i - 1] <= 70.0 and rsi_v[i] > 70.0:
                segnali.append((d, "RSI", "SELL", pr, "RSI sopra 70: ipercomprato"))
        if _ok(lo_v[i - 1], lo_v[i], up_v[i - 1], up_v[i]):
            if px[i - 1] >= lo_v[i - 1] and pr < lo_v[i]:
                segnali.append((d, "Bollinger", "BUY", pr,
                                "Chiusura sotto la banda inferiore"))
            elif px[i - 1] <= up_v[i - 1] and pr > up_v[i]:
                segnali.append((d, "Bollinger", "SELL", pr,
                                "Chiusura sopra la banda superiore"))

    # --- Backtest dei segnali sull'orizzonte ---
    righe = []
    for (d, ind, tipo, pr, motivo) in segnali:
        i = int(idx.get_loc(d))
        esito = float("nan")
        valido_e = False
        j = i + hz
        if j < n and pr > 0 and px[j] > 0:
            ret = (px[j] - pr) / pr * 100.0
            esito = ret if tipo == "BUY" else -ret
            valido_e = True
        righe.append({"Data": d.date(), "Indicatore": ind, "Segnale": tipo,
                      "Prezzo (EUR/MWh)": round(float(pr), 2),
                      "Esito orizzonte (%)": round(float(esito), 2) if valido_e else float("nan"),
                      "Esito valido": valido_e, "_motivo": motivo})
    df_seg = pd.DataFrame(righe, columns=col_s + ["_motivo"])

    riepilogo = []
    for ind in ["Medie mobili", "MACD", "RSI", "Bollinger"]:
        sub = df_seg[(df_seg["Indicatore"] == ind) & (df_seg["Esito valido"])]
        nn = len(sub)
        if nn:
            hit = float((sub["Esito orizzonte (%)"] > 0).mean() * 100.0)
            avg = float(sub["Esito orizzonte (%)"].mean())
        else:
            hit, avg = float("nan"), float("nan")
        riepilogo.append({"Indicatore": ind, "N. segnali": nn,
                          "Hit rate (%)": round(hit, 1) if nn else float("nan"),
                          "Esito medio (%)": round(avg, 2) if nn else float("nan")})
    df_riep = pd.DataFrame(riepilogo, columns=col_r)
    sub_all = df_seg[df_seg["Esito valido"]]
    if len(sub_all):
        hit_tot = round(float((sub_all["Esito orizzonte (%)"] > 0).mean() * 100.0), 1)
        avg_tot = round(float(sub_all["Esito orizzonte (%)"].mean()), 2)
    else:
        hit_tot, avg_tot = float("nan"), float("nan")

    # --- Lettura dell'ultimo giorno ---
    macd_v = macd.to_numpy(dtype=float)
    msg_v = macd_sig.to_numpy(dtype=float)
    ultimo = {"prezzo": round(float(px[-1]), 2),
              "rsi": round(float(rsi_v[-1]), 1) if _ok(rsi_v[-1]) else float("nan"),
              "macd": round(float(macd_v[-1]), 2),
              "macd_signal": round(float(msg_v[-1]), 2),
              "hist": round(float(hist_v[-1]), 2),
              "sma_breve": round(float(sb_v[-1]), 2),
              "sma_lunga": round(float(sl_v[-1]), 2),
              "bb_pos_pct": round(float(pos[-1]), 1)}
    st_sma = (1 if _ok(sb_v[-1], sl_v[-1]) and sb_v[-1] > sl_v[-1]
              else (-1 if _ok(sb_v[-1], sl_v[-1]) and sb_v[-1] < sl_v[-1] else 0))
    st_rsi = (1 if _ok(rsi_v[-1]) and rsi_v[-1] < 30
              else (-1 if _ok(rsi_v[-1]) and rsi_v[-1] > 70 else 0))
    st_macd = (1 if _ok(hist_v[-1]) and hist_v[-1] > 0
               else (-1 if _ok(hist_v[-1]) and hist_v[-1] < 0 else 0))
    st_bb = 1 if pos[-1] < 20 else (-1 if pos[-1] > 80 else 0)
    stance = {"sma": st_sma, "rsi": st_rsi, "macd": st_macd, "bb": st_bb}
    punteggio = st_sma + st_rsi + st_macd + st_bb
    if punteggio >= 2:
        verdetto = ("Segnale composito RIALZISTA (+%d): la maggioranza degli indicatori "
                    "punta verso l'alto — il mercato spot e' in fase di forza." % punteggio)
    elif punteggio <= -2:
        verdetto = ("Segnale composito RIBASSISTA (%d): la maggioranza degli indicatori "
                    "punta verso il basso — il mercato spot e' in fase di debolezza." % punteggio)
    else:
        verdetto = ("Segnale composito NEUTRO (%+d): gli indicatori sono discordi — "
                    "nessuna direzione prevalente, meglio attendere conferme." % punteggio)
    verdetto += (" Gli indicatori tecnici sullo spot elettrico sono un ausilio di timing, "
                 "non una previsione: usali insieme a fondamentali e coperture.")

    serie = pd.DataFrame({"prezzo": s, "sma_breve": sma_b, "sma_lunga": sma_l,
                          "bb_mid": mid, "bb_up": up, "bb_lo": lo,
                          "rsi": rsi, "macd": macd, "macd_signal": macd_sig,
                          "hist": hist})

    return {"errore": None, "valido": True, "n_giorni": n,
            "giorni_richiesti": richiesti, "ultimo": ultimo, "stance": stance,
            "punteggio": punteggio, "verdetto": verdetto,
            "n_segnali": len(df_seg), "hit_rate_tot": hit_tot,
            "esito_medio_tot": avg_tot,
            "segnali": df_seg.drop(columns=["_motivo"]),
            "riepilogo": df_riep, "serie": serie}











