            render_kpi("Miglior contratto", f"{best_m['Nome']}: {best_m['MtM (€)']:+,.0f} €", m3)
            render_kpi("Peggior contratto", f"{worst_m['Nome']}: {worst_m['MtM (€)']:+,.0f} €", m4)
