            render_kpi(edu("Spike / Drop", "Spike = ore con prezzo sopra l'atteso (spesa inattesa). Drop = ore con prezzo sotto l'atteso (opportunita': se il carico era acceso, hai risparmiato)."),
                       f"{ap['n_spike']} / {ap['n_drop']}", k2)
