            df_lc["Margine (€/MWh)"] = round(df_lc["Catturato"] - lcoe_v, 1)
            df_lc.columns = ["Mese", "Prezzo catturato (€/MWh)", "Media spot (€/MWh)",
                             "LCOE (€/MWh)", "Margine (€/MWh)"]
