        if np.isfinite(pb):
            segno_ef = "🟢" if pb <= vita_ef else "🔴"
            render_kpi(f"{segno_ef} Payback semplice (anni)", f"{pb:.1f}" if pb != float("inf") else "> vita utile", k3)
        else:
            render_kpi("Payback semplice (anni)", "n.d.", k3)
        tir_ef = ris_ef["tir_pct"]
